(function(r){const data={"edition":"World English Bible (engwebp)","source":"https://ebible.org/engwebp/","license":"Public domain","retrieved":"2026-09-23","entries":[{"id":"1co-12-12-20","reference":"1 Corinthians 12:12–20","chapterKey":"1CO-12","start":12,"end":20},{"id":"1co-12-4-7","reference":"1 Corinthians 12:4–7","chapterKey":"1CO-12","start":4,"end":7},{"id":"1co-14-40-40","reference":"1 Corinthians 14:40","chapterKey":"1CO-14","start":40,"end":40},{"id":"1co-14-9-9","reference":"1 Corinthians 14:9","chapterKey":"1CO-14","start":9,"end":9},{"id":"1co-15-58-58","reference":"1 Corinthians 15:58","chapterKey":"1CO-15","start":58,"end":58},{"id":"2co-11-26-28","reference":"2 Corinthians 11:26–28","chapterKey":"2CO-11","start":26,"end":28},{"id":"2ki-22-8-13","reference":"2 Kings 22:8–13","chapterKey":"2KI-22","start":8,"end":13},{"id":"2ti-1-13-14","reference":"2 Timothy 1:13–14","chapterKey":"2TI-1","start":13,"end":14},{"id":"2ti-2-1-7","reference":"2 Timothy 2:1–7","chapterKey":"2TI-2","start":1,"end":7},{"id":"2ti-2-15-15","reference":"2 Timothy 2:15","chapterKey":"2TI-2","start":15,"end":15},{"id":"2ti-2-2-2","reference":"2 Timothy 2:2","chapterKey":"2TI-2","start":2,"end":2},{"id":"3jn-1-5-8","reference":"3 John 1:5–8","chapterKey":"3JN-1","start":5,"end":8},{"id":"act-1-8-8","reference":"Acts 1:8","chapterKey":"ACT-1","start":8,"end":8},{"id":"act-13-1-3","reference":"Acts 13:1–3","chapterKey":"ACT-13","start":1,"end":3},{"id":"act-13-1-4","reference":"Acts 13:1–4","chapterKey":"ACT-13","start":1,"end":4},{"id":"act-13-2-4","reference":"Acts 13:2–4","chapterKey":"ACT-13","start":2,"end":4},{"id":"act-13-47-47","reference":"Acts 13:47","chapterKey":"ACT-13","start":47,"end":47},{"id":"act-14-21-28","reference":"Acts 14:21–28","chapterKey":"ACT-14","start":21,"end":28},{"id":"act-17-11-11","reference":"Acts 17:11","chapterKey":"ACT-17","start":11,"end":11},{"id":"act-17-16-34","reference":"Acts 17:16–34","chapterKey":"ACT-17","start":16,"end":34},{"id":"act-18-24-26","reference":"Acts 18:24–26","chapterKey":"ACT-18","start":24,"end":26},{"id":"act-19-8-10","reference":"Acts 19:8–10","chapterKey":"ACT-19","start":8,"end":10},{"id":"act-2-42-47","reference":"Acts 2:42–47","chapterKey":"ACT-2","start":42,"end":47},{"id":"act-2-5-11","reference":"Acts 2:5–11","chapterKey":"ACT-2","start":5,"end":11},{"id":"act-4-18-31","reference":"Acts 4:18–31","chapterKey":"ACT-4","start":18,"end":31},{"id":"act-6-1-4","reference":"Acts 6:1–4","chapterKey":"ACT-6","start":1,"end":4},{"id":"act-8-26-40","reference":"Acts 8:26–40","chapterKey":"ACT-8","start":26,"end":40},{"id":"act-8-30-35","reference":"Acts 8:30–35","chapterKey":"ACT-8","start":30,"end":35},{"id":"act-9-31-31","reference":"Acts 9:31","chapterKey":"ACT-9","start":31,"end":31},{"id":"amo-5-21-24","reference":"Amos 5:21–24","chapterKey":"AMO-5","start":21,"end":24},{"id":"col-4-3-4","reference":"Colossians 4:3–4","chapterKey":"COL-4","start":3,"end":4},{"id":"deu-17-18-19","reference":"Deuteronomy 17:18–19","chapterKey":"DEU-17","start":18,"end":19},{"id":"deu-17-18-20","reference":"Deuteronomy 17:18–20","chapterKey":"DEU-17","start":18,"end":20},{"id":"deu-6-4-9","reference":"Deuteronomy 6:4–9","chapterKey":"DEU-6","start":4,"end":9},{"id":"ecc-7-12-12","reference":"Ecclesiastes 7:12","chapterKey":"ECC-7","start":12,"end":12},{"id":"ecc-7-13-14","reference":"Ecclesiastes 7:13–14","chapterKey":"ECC-7","start":13,"end":14},{"id":"eph-4-11-16","reference":"Ephesians 4:11–16","chapterKey":"EPH-4","start":11,"end":16},{"id":"exo-18-13-26","reference":"Exodus 18:13–26","chapterKey":"EXO-18","start":13,"end":26},{"id":"exo-18-17-23","reference":"Exodus 18:17–23","chapterKey":"EXO-18","start":17,"end":23},{"id":"exo-18-21-23","reference":"Exodus 18:21–23","chapterKey":"EXO-18","start":21,"end":23},{"id":"ezr-7-10-10","reference":"Ezra 7:10","chapterKey":"EZR-7","start":10,"end":10},{"id":"gal-6-9-9","reference":"Galatians 6:9","chapterKey":"GAL-6","start":9,"end":9},{"id":"gen-11-1-9","reference":"Genesis 11:1–9","chapterKey":"GEN-11","start":1,"end":9},{"id":"hab-2-2-2","reference":"Habakkuk 2:2","chapterKey":"HAB-2","start":2,"end":2},{"id":"isa-55-10-11","reference":"Isaiah 55:10–11","chapterKey":"ISA-55","start":10,"end":11},{"id":"isa-55-8-11","reference":"Isaiah 55:8–11","chapterKey":"ISA-55","start":8,"end":11},{"id":"jas-3-1-1","reference":"James 3:1","chapterKey":"JAS-3","start":1,"end":1},{"id":"jer-36-27-32","reference":"Jeremiah 36:27–32","chapterKey":"JER-36","start":27,"end":32},{"id":"jer-36-4-4","reference":"Jeremiah 36:4","chapterKey":"JER-36","start":4,"end":4},{"id":"jhn-20-19-23","reference":"John 20:19–23","chapterKey":"JHN-20","start":19,"end":23},{"id":"jhn-20-21-21","reference":"John 20:21","chapterKey":"JHN-20","start":21,"end":21},{"id":"jos-4-1-7","reference":"Joshua 4:1–7","chapterKey":"JOS-4","start":1,"end":7},{"id":"luk-14-28-28","reference":"Luke 14:28","chapterKey":"LUK-14","start":28,"end":28},{"id":"luk-24-27-27","reference":"Luke 24:27","chapterKey":"LUK-24","start":27,"end":27},{"id":"luk-24-44-49","reference":"Luke 24:44–49","chapterKey":"LUK-24","start":44,"end":49},{"id":"mat-28-18-20","reference":"Matthew 28:18–20","chapterKey":"MAT-28","start":18,"end":20},{"id":"mic-6-6-8","reference":"Micah 6:6–8","chapterKey":"MIC-6","start":6,"end":8},{"id":"mic-6-8-8","reference":"Micah 6:8","chapterKey":"MIC-6","start":8,"end":8},{"id":"neh-2-17-18","reference":"Nehemiah 2:17–18","chapterKey":"NEH-2","start":17,"end":18},{"id":"neh-8-1-8","reference":"Nehemiah 8:1–8","chapterKey":"NEH-8","start":1,"end":8},{"id":"neh-8-8-8","reference":"Nehemiah 8:8","chapterKey":"NEH-8","start":8,"end":8},{"id":"php-1-3-5","reference":"Philippians 1:3–5","chapterKey":"PHP-1","start":3,"end":5},{"id":"php-1-3-7","reference":"Philippians 1:3–7","chapterKey":"PHP-1","start":3,"end":7},{"id":"php-3-16-16","reference":"Philippians 3:16","chapterKey":"PHP-3","start":16,"end":16},{"id":"php-4-9-9","reference":"Philippians 4:9","chapterKey":"PHP-4","start":9,"end":9},{"id":"pro-15-22-22","reference":"Proverbs 15:22","chapterKey":"PRO-15","start":22,"end":22},{"id":"pro-21-5-5","reference":"Proverbs 21:5","chapterKey":"PRO-21","start":5,"end":5},{"id":"pro-22-29-29","reference":"Proverbs 22:29","chapterKey":"PRO-22","start":29,"end":29},{"id":"pro-24-27-27","reference":"Proverbs 24:27","chapterKey":"PRO-24","start":27,"end":27},{"id":"psa-145-4-4","reference":"Psalm 145:4","chapterKey":"PSA-145","start":4,"end":4},{"id":"psa-78-5-7","reference":"Psalm 78:5–7","chapterKey":"PSA-78","start":5,"end":7},{"id":"psa-96-3-3","reference":"Psalm 96:3","chapterKey":"PSA-96","start":3,"end":3},{"id":"rev-21-22-27","reference":"Revelation 21:22–27","chapterKey":"REV-21","start":22,"end":27},{"id":"rev-5-9-10","reference":"Revelation 5:9–10","chapterKey":"REV-5","start":9,"end":10},{"id":"rev-5-9-14","reference":"Revelation 5:9–14","chapterKey":"REV-5","start":9,"end":14},{"id":"rev-7-9-10","reference":"Revelation 7:9–10","chapterKey":"REV-7","start":9,"end":10},{"id":"rev-7-9-12","reference":"Revelation 7:9–12","chapterKey":"REV-7","start":9,"end":12},{"id":"rom-10-14-15","reference":"Romans 10:14–15","chapterKey":"ROM-10","start":14,"end":15},{"id":"rom-10-17-17","reference":"Romans 10:17","chapterKey":"ROM-10","start":17,"end":17},{"id":"rom-15-20-21","reference":"Romans 15:20–21","chapterKey":"ROM-15","start":20,"end":21},{"id":"tit-2-1-1","reference":"Titus 2:1","chapterKey":"TIT-2","start":1,"end":1},{"id":"tit-2-1-8","reference":"Titus 2:1–8","chapterKey":"TIT-2","start":1,"end":8},{"id":"zec-4-10-10","reference":"Zechariah 4:10","chapterKey":"ZEC-4","start":10,"end":10}],"chapters":{"1CO-12":{"book":"1 Corinthians","chapter":12,"verses":[{"number":1,"text":"Now concerning spiritual things, brothers, I don’t want you to be ignorant.","notes":[]},{"number":2,"text":"You know that when you were heathen, you were led away to those mute idols, however you might be led.","notes":["or Gentiles"]},{"number":3,"text":"Therefore I make known to you that no man speaking by God’s Spirit says, “Jesus is accursed.” No one can say, “Jesus is Lord,” but by the Holy Spirit.","notes":[]},{"number":4,"text":"Now there are various kinds of gifts, but the same Spirit.","notes":[]},{"number":5,"text":"There are various kinds of service, and the same Lord.","notes":[]},{"number":6,"text":"There are various kinds of workings, but the same God who works all things in all.","notes":[]},{"number":7,"text":"But to each one is given the manifestation of the Spirit for the profit of all.","notes":[]},{"number":8,"text":"For to one is given through the Spirit the word of wisdom, and to another the word of knowledge according to the same Spirit,","notes":[]},{"number":9,"text":"to another faith by the same Spirit, and to another gifts of healings by the same Spirit,","notes":[]},{"number":10,"text":"and to another workings of miracles, and to another prophecy, and to another discerning of spirits, to another different kinds of languages, and to another the interpretation of languages.","notes":[]},{"number":11,"text":"But the one and the same Spirit produces all of these, distributing to each one separately as he desires.","notes":[]},{"number":12,"text":"For as the body is one and has many members, and all the members of the body, being many, are one body; so also is Christ.","notes":[]},{"number":13,"text":"For in one Spirit we were all baptized into one body, whether Jews or Greeks, whether bond or free; and were all given to drink into one Spirit.","notes":[]},{"number":14,"text":"For the body is not one member, but many.","notes":[]},{"number":15,"text":"If the foot would say, “Because I’m not the hand, I’m not part of the body,” it is not therefore not part of the body.","notes":[]},{"number":16,"text":"If the ear would say, “Because I’m not the eye, I’m not part of the body,” it’s not therefore not part of the body.","notes":[]},{"number":17,"text":"If the whole body were an eye, where would the hearing be? If the whole were hearing, where would the smelling be?","notes":[]},{"number":18,"text":"But now God has set the members, each one of them, in the body, just as he desired.","notes":[]},{"number":19,"text":"If they were all one member, where would the body be?","notes":[]},{"number":20,"text":"But now they are many members, but one body.","notes":[]},{"number":21,"text":"The eye can’t tell the hand, “I have no need for you,” or again the head to the feet, “I have no need for you.”","notes":[]},{"number":22,"text":"No, much rather, those members of the body which seem to be weaker are necessary.","notes":[]},{"number":23,"text":"Those parts of the body which we think to be less honorable, on those we bestow more abundant honor; and our unpresentable parts have more abundant modesty,","notes":[]},{"number":24,"text":"while our presentable parts have no such need. But God composed the body together, giving more abundant honor to the inferior part,","notes":[]},{"number":25,"text":"that there should be no division in the body, but that the members should have the same care for one another.","notes":[]},{"number":26,"text":"When one member suffers, all the members suffer with it. When one member is honored, all the members rejoice with it.","notes":[]},{"number":27,"text":"Now you are the body of Christ, and members individually.","notes":[]},{"number":28,"text":"God has set some in the assembly: first apostles, second prophets, third teachers, then miracle workers, then gifts of healings, helps, governments, and various kinds of languages.","notes":[]},{"number":29,"text":"Are all apostles? Are all prophets? Are all teachers? Are all miracle workers?","notes":[]},{"number":30,"text":"Do all have gifts of healings? Do all speak with various languages? Do all interpret?","notes":[]},{"number":31,"text":"But earnestly desire the best gifts. Moreover, I show a most excellent way to you.","notes":[]}],"source":"https://ebible.org/engwebp/1CO12.htm"},"1CO-14":{"book":"1 Corinthians","chapter":14,"verses":[{"number":1,"text":"Follow after love and earnestly desire spiritual gifts, but especially that you may prophesy.","notes":[]},{"number":2,"text":"For he who speaks in another language speaks not to men, but to God, for no one understands, but in the Spirit he speaks mysteries.","notes":[]},{"number":3,"text":"But he who prophesies speaks to men for their edification, exhortation, and consolation.","notes":[]},{"number":4,"text":"He who speaks in another language edifies himself, but he who prophesies edifies the assembly.","notes":[]},{"number":5,"text":"Now I desire to have you all speak with other languages, but even more that you would prophesy. For he is greater who prophesies than he who speaks with other languages, unless he interprets, that the assembly may be built up.","notes":[]},{"number":6,"text":"But now, brothers, if I come to you speaking with other languages, what would I profit you unless I speak to you either by way of revelation, or of knowledge, or of prophesying, or of teaching?","notes":["The word for “brothers” here and where context allows may also be correctly translated “brothers and sisters” or “siblings.”"]},{"number":7,"text":"Even lifeless things that make a sound, whether pipe or harp, if they didn’t give a distinction in the sounds, how would it be known what is piped or harped?","notes":[]},{"number":8,"text":"For if the trumpet gave an uncertain sound, who would prepare himself for war?","notes":[]},{"number":9,"text":"So also you, unless you uttered by the tongue words easy to understand, how would it be known what is spoken? For you would be speaking into the air.","notes":[]},{"number":10,"text":"There are, it may be, so many kinds of languages in the world, and none of them is without meaning.","notes":[]},{"number":11,"text":"If then I don’t know the meaning of the language, I would be to him who speaks a foreigner, and he who speaks would be a foreigner to me.","notes":[]},{"number":12,"text":"So also you, since you are zealous for spiritual gifts, seek that you may abound to the building up of the assembly.","notes":[]},{"number":13,"text":"Therefore let him who speaks in another language pray that he may interpret.","notes":[]},{"number":14,"text":"For if I pray in another language, my spirit prays, but my understanding is unfruitful.","notes":[]},{"number":15,"text":"What should I do? I will pray with the spirit, and I will pray with the understanding also. I will sing with the spirit, and I will sing with the understanding also.","notes":[]},{"number":16,"text":"Otherwise, if you bless with the spirit, how will he who fills the place of the unlearned say the “Amen” at your giving of thanks, seeing he doesn’t know what you say?","notes":[]},{"number":17,"text":"For you most certainly give thanks well, but the other person is not built up.","notes":[]},{"number":18,"text":"I thank my God, I speak with other languages more than you all.","notes":[]},{"number":19,"text":"However, in the assembly I would rather speak five words with my understanding, that I might instruct others also, than ten thousand words in another language.","notes":[]},{"number":20,"text":"Brothers, don’t be children in thoughts, yet in malice be babies, but in thoughts be mature.","notes":[]},{"number":21,"text":"In the law it is written, “By men of strange languages and by the lips of strangers I will speak to this people. They won’t even listen to me that way, says the Lord.”","notes":["Isaiah 28:11-12"]},{"number":22,"text":"Therefore other languages are for a sign, not to those who believe, but to the unbelieving; but prophesying is for a sign, not to the unbelieving, but to those who believe.","notes":[]},{"number":23,"text":"If therefore the whole assembly is assembled together and all speak with other languages, and unlearned or unbelieving people come in, won’t they say that you are crazy?","notes":[]},{"number":24,"text":"But if all prophesy, and someone unbelieving or unlearned comes in, he is reproved by all, and he is judged by all.","notes":[]},{"number":25,"text":"And thus the secrets of his heart are revealed. So he will fall down on his face and worship God, declaring that God is among you indeed.","notes":[]},{"number":26,"text":"What is it then, brothers? When you come together, each one of you has a psalm, has a teaching, has a revelation, has another language, or has an interpretation. Let all things be done to build each other up.","notes":[]},{"number":27,"text":"If any man speaks in another language, let there be two, or at the most three, and in turn; and let one interpret.","notes":[]},{"number":28,"text":"But if there is no interpreter, let him keep silent in the assembly, and let him speak to himself and to God.","notes":[]},{"number":29,"text":"Let two or three of the prophets speak, and let the others discern.","notes":[]},{"number":30,"text":"But if a revelation is made to another sitting by, let the first keep silent.","notes":[]},{"number":31,"text":"For you all can prophesy one by one, that all may learn and all may be exhorted.","notes":[]},{"number":32,"text":"The spirits of the prophets are subject to the prophets,","notes":[]},{"number":33,"text":"for God is not a God of confusion but of peace, as in all the assemblies of the saints.","notes":[]},{"number":34,"text":"Let the wives be quiet in the assemblies, for it has not been permitted for them to be talking except in submission, as the law also says,","notes":["Deuteronomy 27:9"]},{"number":35,"text":"if they desire to learn anything. “Let them ask their own husbands at home, for it is shameful for a wife to be talking in the assembly.”","notes":[]},{"number":36,"text":"What!? Was it from you that the word of God went out? Or did it come to you alone?","notes":[]},{"number":37,"text":"If any man thinks himself to be a prophet or spiritual, let him recognize the things which I write to you, that they are the commandment of the Lord.","notes":[]},{"number":38,"text":"But if anyone is ignorant, let him be ignorant.","notes":[]},{"number":39,"text":"Therefore, brothers, desire earnestly to prophesy, and don’t forbid speaking with other languages.","notes":[]},{"number":40,"text":"Let all things be done decently and in order.","notes":[]}],"source":"https://ebible.org/engwebp/1CO14.htm"},"1CO-15":{"book":"1 Corinthians","chapter":15,"verses":[{"number":1,"text":"Now I declare to you, brothers, the Good News which I preached to you, which also you received, in which you also stand,","notes":[]},{"number":2,"text":"by which also you are saved, if you hold firmly the word which I preached to you—unless you believed in vain.","notes":[]},{"number":3,"text":"For I delivered to you first of all that which I also received: that Christ died for our sins according to the Scriptures,","notes":[]},{"number":4,"text":"that he was buried, that he was raised on the third day according to the Scriptures,","notes":[]},{"number":5,"text":"and that he appeared to Cephas, then to the twelve.","notes":[]},{"number":6,"text":"Then he appeared to over five hundred brothers at once, most of whom remain until now, but some have also fallen asleep.","notes":[]},{"number":7,"text":"Then he appeared to James, then to all the apostles,","notes":[]},{"number":8,"text":"and last of all, as to the child born at the wrong time, he appeared to me also.","notes":[]},{"number":9,"text":"For I am the least of the apostles, who is not worthy to be called an apostle, because I persecuted the assembly of God.","notes":[]},{"number":10,"text":"But by the grace of God I am what I am. His grace which was given to me was not futile, but I worked more than all of them; yet not I, but the grace of God which was with me.","notes":[]},{"number":11,"text":"Whether then it is I or they, so we preach, and so you believed.","notes":[]},{"number":12,"text":"Now if Christ is preached, that he has been raised from the dead, how do some among you say that there is no resurrection of the dead?","notes":[]},{"number":13,"text":"But if there is no resurrection of the dead, neither has Christ been raised.","notes":[]},{"number":14,"text":"If Christ has not been raised, then our preaching is in vain and your faith also is in vain.","notes":[]},{"number":15,"text":"Yes, we are also found false witnesses of God, because we testified about God that he raised up Christ, whom he didn’t raise up if it is true that the dead are not raised.","notes":[]},{"number":16,"text":"For if the dead aren’t raised, neither has Christ been raised.","notes":[]},{"number":17,"text":"If Christ has not been raised, your faith is vain; you are still in your sins.","notes":[]},{"number":18,"text":"Then they also who are fallen asleep in Christ have perished.","notes":[]},{"number":19,"text":"If we have only hoped in Christ in this life, we are of all men most pitiable.","notes":[]},{"number":20,"text":"But now Christ has been raised from the dead. He became the first fruit of those who are asleep.","notes":[]},{"number":21,"text":"For since death came by man, the resurrection of the dead also came by man.","notes":[]},{"number":22,"text":"For as in Adam all die, so also in Christ all will be made alive.","notes":[]},{"number":23,"text":"But each in his own order: Christ the first fruits, then those who are Christ’s at his coming.","notes":[]},{"number":24,"text":"Then the end comes, when he will deliver up the Kingdom to God the Father, when he will have abolished all rule and all authority and power.","notes":[]},{"number":25,"text":"For he must reign until he has put all his enemies under his feet.","notes":[]},{"number":26,"text":"The last enemy that will be abolished is death.","notes":[]},{"number":27,"text":"For, “He put all things in subjection under his feet.” But when he says, “All things are put in subjection”, it is evident that he is excepted who subjected all things to him.","notes":["Psalms 8:6"]},{"number":28,"text":"When all things have been subjected to him, then the Son will also himself be subjected to him who subjected all things to him, that God may be all in all.","notes":[]},{"number":29,"text":"Or else what will they do who are baptized for the dead? If the dead aren’t raised at all, why then are they baptized for the dead?","notes":[]},{"number":30,"text":"Why do we also stand in jeopardy every hour?","notes":[]},{"number":31,"text":"I affirm, by the boasting in you which I have in Christ Jesus our Lord, I die daily.","notes":[]},{"number":32,"text":"If I fought with animals at Ephesus for human purposes, what does it profit me? If the dead are not raised, then “let’s eat and drink, for tomorrow we die.”","notes":["Isaiah 22:13"]},{"number":33,"text":"Don’t be deceived! “Evil companionships corrupt good morals.”","notes":[]},{"number":34,"text":"Wake up righteously and don’t sin, for some have no knowledge of God. I say this to your shame.","notes":[]},{"number":35,"text":"But someone will say, “How are the dead raised?” and, “With what kind of body do they come?”","notes":[]},{"number":36,"text":"You foolish one, that which you yourself sow is not made alive unless it dies.","notes":[]},{"number":37,"text":"That which you sow, you don’t sow the body that will be, but a bare grain, maybe of wheat, or of some other kind.","notes":[]},{"number":38,"text":"But God gives it a body even as it pleased him, and to each seed a body of its own.","notes":[]},{"number":39,"text":"All flesh is not the same flesh, but there is one flesh of men, another flesh of animals, another of fish, and another of birds.","notes":[]},{"number":40,"text":"There are also celestial bodies and terrestrial bodies; but the glory of the celestial differs from that of the terrestrial.","notes":[]},{"number":41,"text":"There is one glory of the sun, another glory of the moon, and another glory of the stars; for one star differs from another star in glory.","notes":[]},{"number":42,"text":"So also is the resurrection of the dead. The body is sown perishable; it is raised imperishable.","notes":[]},{"number":43,"text":"It is sown in dishonor; it is raised in glory. It is sown in weakness; it is raised in power.","notes":[]},{"number":44,"text":"It is sown a natural body; it is raised a spiritual body. There is a natural body and there is also a spiritual body.","notes":[]},{"number":45,"text":"So also it is written, “The first man Adam became a living soul.” The last Adam became a life-giving spirit.","notes":["Genesis 2:7"]},{"number":46,"text":"However, that which is spiritual isn’t first, but that which is natural, then that which is spiritual.","notes":[]},{"number":47,"text":"The first man is of the earth, made of dust. The second man is the Lord from heaven.","notes":[]},{"number":48,"text":"As is the one made of dust, such are those who are also made of dust; and as is the heavenly, such are they also that are heavenly.","notes":[]},{"number":49,"text":"As we have borne the image of those made of dust, let’s also bear the image of the heavenly.","notes":["NU, TR read “we will” instead of “let’s”"]},{"number":50,"text":"Now I say this, brothers, that flesh and blood can’t inherit God’s Kingdom; neither does the perishable inherit imperishable.","notes":["The word for “brothers” here and where context allows may also be correctly translated “brothers and sisters” or “siblings.”"]},{"number":51,"text":"Behold, I tell you a mystery. We will not all sleep, but we will all be changed,","notes":["“Behold”, from “ἰδοὺ”, means look at, take notice, observe, see, or gaze at. It is often used as an interjection."]},{"number":52,"text":"in a moment, in the twinkling of an eye, at the last trumpet. For the trumpet will sound and the dead will be raised incorruptible, and we will be changed.","notes":[]},{"number":53,"text":"For this perishable body must become imperishable, and this mortal must put on immortality.","notes":[]},{"number":54,"text":"But when this perishable body will have become imperishable, and this mortal will have put on immortality, then what is written will happen: “Death is swallowed up in victory.”","notes":["Isaiah 25:8"]},{"number":55,"text":"“Death, where is your sting? Hades, where is your victory?”","notes":["or, Hell","See Hosea 13:14"]},{"number":56,"text":"The sting of death is sin, and the power of sin is the law.","notes":[]},{"number":57,"text":"But thanks be to God, who gives us the victory through our Lord Jesus Christ.","notes":[]},{"number":58,"text":"Therefore, my beloved brothers, be steadfast, immovable, always abounding in the Lord’s work, because you know that your labor is not in vain in the Lord.","notes":[]}],"source":"https://ebible.org/engwebp/1CO15.htm"},"2CO-11":{"book":"2 Corinthians","chapter":11,"verses":[{"number":1,"text":"I wish that you would bear with me in a little foolishness, but indeed you do bear with me.","notes":[]},{"number":2,"text":"For I am jealous over you with a godly jealousy. For I promised you in marriage to one husband, that I might present you as a pure virgin to Christ.","notes":[]},{"number":3,"text":"But I am afraid that somehow, as the serpent deceived Eve in his craftiness, so your minds might be corrupted from the simplicity that is in Christ.","notes":[]},{"number":4,"text":"For if he who comes preaches another Jesus whom we didn’t preach, or if you receive a different spirit which you didn’t receive, or a different “good news” which you didn’t accept, you put up with that well enough.","notes":[]},{"number":5,"text":"For I reckon that I am not at all behind the very best apostles.","notes":[]},{"number":6,"text":"But though I am unskilled in speech, yet I am not unskilled in knowledge. No, in every way we have been revealed to you in all things.","notes":[]},{"number":7,"text":"Or did I commit a sin in humbling myself that you might be exalted, because I preached to you God’s Good News free of charge?","notes":[]},{"number":8,"text":"I robbed other assemblies, taking wages from them that I might serve you.","notes":[]},{"number":9,"text":"When I was present with you and was in need, I wasn’t a burden on anyone, for the brothers, when they came from Macedonia, supplied the measure of my need. In everything I kept myself from being burdensome to you, and I will continue to do so.","notes":[]},{"number":10,"text":"As the truth of Christ is in me, no one will stop me from this boasting in the regions of Achaia.","notes":[]},{"number":11,"text":"Why? Because I don’t love you? God knows.","notes":[]},{"number":12,"text":"But what I do, that I will continue to do, that I may cut off opportunity from those who desire an opportunity, that in which they boast, they may be recognized just like us.","notes":[]},{"number":13,"text":"For such men are false apostles, deceitful workers, masquerading as Christ’s apostles.","notes":[]},{"number":14,"text":"And no wonder, for even Satan masquerades as an angel of light.","notes":[]},{"number":15,"text":"It is no great thing therefore if his servants also masquerade as servants of righteousness, whose end will be according to their works.","notes":[]},{"number":16,"text":"I say again, let no one think me foolish. But if so, yet receive me as foolish, that I also may boast a little.","notes":[]},{"number":17,"text":"That which I speak, I don’t speak according to the Lord, but as in foolishness, in this confidence of boasting.","notes":[]},{"number":18,"text":"Seeing that many boast after the flesh, I will also boast.","notes":[]},{"number":19,"text":"For you bear with the foolish gladly, being wise.","notes":[]},{"number":20,"text":"For you bear with a man if he brings you into bondage, if he devours you, if he takes you captive, if he exalts himself, or if he strikes you on the face.","notes":[]},{"number":21,"text":"To my shame, I speak as though we had been weak. Yet in whatever way anyone is bold (I speak in foolishness), I am bold also.","notes":[]},{"number":22,"text":"Are they Hebrews? So am I. Are they Israelites? So am I. Are they the offspring of Abraham? So am I.","notes":["or, seed"]},{"number":23,"text":"Are they servants of Christ? (I speak as one beside himself.) I am more so: in labors more abundantly, in prisons more abundantly, in stripes above measure, and in deaths often.","notes":[]},{"number":24,"text":"Five times I received forty stripes minus one from the Jews.","notes":[]},{"number":25,"text":"Three times I was beaten with rods. Once I was stoned. Three times I suffered shipwreck. I have been a night and a day in the deep.","notes":[]},{"number":26,"text":"I have been in travels often, perils of rivers, perils of robbers, perils from my countrymen, perils from the Gentiles, perils in the city, perils in the wilderness, perils in the sea, perils among false brothers;","notes":[]},{"number":27,"text":"in labor and travail, in watchings often, in hunger and thirst, in fastings often, and in cold and nakedness.","notes":[]},{"number":28,"text":"Besides those things that are outside, there is that which presses on me daily: anxiety for all the assemblies.","notes":[]},{"number":29,"text":"Who is weak, and I am not weak? Who is caused to stumble, and I don’t burn with indignation?","notes":[]},{"number":30,"text":"If I must boast, I will boast of the things that concern my weakness.","notes":[]},{"number":31,"text":"The God and Father of the Lord Jesus Christ, he who is blessed forever more, knows that I don’t lie.","notes":[]},{"number":32,"text":"In Damascus the governor under King Aretas guarded the Damascenes’ city, desiring to arrest me.","notes":[]},{"number":33,"text":"I was let down in a basket through a window by the wall, and escaped his hands.","notes":[]}],"source":"https://ebible.org/engwebp/2CO11.htm"},"2KI-22":{"book":"2 Kings","chapter":22,"verses":[{"number":1,"text":"Josiah was eight years old when he began to reign, and he reigned thirty-one years in Jerusalem. His mother’s name was Jedidah the daughter of Adaiah of Bozkath.","notes":[]},{"number":2,"text":"He did that which was right in the LORD’s eyes, and walked in all the ways of David his father, and didn’t turn away to the right hand or to the left.","notes":[]},{"number":3,"text":"In the eighteenth year of King Josiah, the king sent Shaphan, the son of Azaliah the son of Meshullam, the scribe, to the LORD’s house, saying,","notes":[]},{"number":4,"text":"“Go up to Hilkiah the high priest, that he may count the money which is brought into the LORD’s house, which the keepers of the threshold have gathered of the people.","notes":[]},{"number":5,"text":"Let them deliver it into the hand of the workers who have the oversight of the LORD’s house; and let them give it to the workers who are in the LORD’s house, to repair the damage to the house,","notes":[]},{"number":6,"text":"to the carpenters, and to the builders, and to the masons, and for buying timber and cut stone to repair the house.","notes":[]},{"number":7,"text":"However, no accounting shall be asked of them for the money delivered into their hand, for they deal faithfully.”","notes":[]},{"number":8,"text":"Hilkiah the high priest said to Shaphan the scribe, “I have found the book of the law in the LORD’s house.” Hilkiah delivered the book to Shaphan, and he read it.","notes":[]},{"number":9,"text":"Shaphan the scribe came to the king, and brought the king word again, and said, “Your servants have emptied out the money that was found in the house, and have delivered it into the hands of the workmen who have the oversight of the LORD’s house.”","notes":[]},{"number":10,"text":"Shaphan the scribe told the king, saying, “Hilkiah the priest has delivered a book to me.” Then Shaphan read it before the king.","notes":[]},{"number":11,"text":"When the king had heard the words of the book of the law, he tore his clothes.","notes":[]},{"number":12,"text":"The king commanded Hilkiah the priest, Ahikam the son of Shaphan, Achbor the son of Micaiah, Shaphan the scribe, and Asaiah the king’s servant, saying,","notes":[]},{"number":13,"text":"“Go inquire of the LORD for me, and for the people, and for all Judah, concerning the words of this book that is found; for great is the LORD’s wrath that is kindled against us, because our fathers have not listened to the words of this book, to do according to all that which is written concerning us.”","notes":[]},{"number":14,"text":"So Hilkiah the priest, Ahikam, Achbor, Shaphan, and Asaiah went to Huldah the prophetess, the wife of Shallum the son of Tikvah, the son of Harhas, keeper of the wardrobe (now she lived in Jerusalem in the second quarter); and they talked with her.","notes":[]},{"number":15,"text":"She said to them, “The LORD the God of Israel says, ‘Tell the man who sent you to me,","notes":[]},{"number":16,"text":"“The LORD says, ‘Behold, I will bring evil on this place and on its inhabitants, even all the words of the book which the king of Judah has read.","notes":[]},{"number":17,"text":"Because they have forsaken me and have burned incense to other gods, that they might provoke me to anger with all the work of their hands, therefore my wrath shall be kindled against this place, and it will not be quenched.’ ”","notes":[]},{"number":18,"text":"But to the king of Judah, who sent you to inquire of the LORD, tell him, “The LORD the God of Israel says, ‘Concerning the words which you have heard,","notes":[]},{"number":19,"text":"because your heart was tender, and you humbled yourself before the LORD when you heard what I spoke against this place and against its inhabitants, that they should become a desolation and a curse, and have torn your clothes and wept before me, I also have heard you,’ says the LORD.","notes":[]},{"number":20,"text":"‘Therefore behold, I will gather you to your fathers, and you will be gathered to your grave in peace. Your eyes will not see all the evil which I will bring on this place.’ ” ’ ” So they brought this message back to the king.","notes":[]}],"source":"https://ebible.org/engwebp/2KI22.htm"},"2TI-1":{"book":"2 Timothy","chapter":1,"verses":[{"number":1,"text":"Paul, an apostle of Jesus Christ through the will of God, according to the promise of the life which is in Christ Jesus,","notes":["“Christ” means “Anointed One”."]},{"number":2,"text":"to Timothy, my beloved child: Grace, mercy, and peace, from God the Father and Christ Jesus our Lord.","notes":[]},{"number":3,"text":"I thank God, whom I serve as my forefathers did, with a pure conscience. How unceasing is my memory of you in my petitions, night and day","notes":[]},{"number":4,"text":"longing to see you, remembering your tears, that I may be filled with joy;","notes":[]},{"number":5,"text":"having been reminded of the sincere faith that is in you, which lived first in your grandmother Lois and your mother Eunice and, I am persuaded, in you also.","notes":[]},{"number":6,"text":"For this cause, I remind you that you should stir up the gift of God which is in you through the laying on of my hands.","notes":[]},{"number":7,"text":"For God didn’t give us a spirit of fear, but of power, love, and self-control.","notes":[]},{"number":8,"text":"Therefore don’t be ashamed of the testimony of our Lord, nor of me his prisoner; but endure hardship for the Good News according to the power of God,","notes":[]},{"number":9,"text":"who saved us and called us with a holy calling, not according to our works, but according to his own purpose and grace, which was given to us in Christ Jesus before times eternal,","notes":[]},{"number":10,"text":"but has now been revealed by the appearing of our Savior, Christ Jesus, who abolished death, and brought life and immortality to light through the Good News.","notes":[]},{"number":11,"text":"For this I was appointed as a preacher, an apostle, and a teacher of the Gentiles.","notes":[]},{"number":12,"text":"For this cause I also suffer these things. Yet I am not ashamed, for I know him whom I have believed, and I am persuaded that he is able to guard that which I have committed to him against that day.","notes":[]},{"number":13,"text":"Hold the pattern of sound words which you have heard from me, in faith and love which is in Christ Jesus.","notes":[]},{"number":14,"text":"That good thing which was committed to you, guard through the Holy Spirit who dwells in us.","notes":[]},{"number":15,"text":"This you know, that all who are in Asia turned away from me, of whom are Phygelus and Hermogenes.","notes":[]},{"number":16,"text":"May the Lord grant mercy to the house of Onesiphorus, for he often refreshed me, and was not ashamed of my chain,","notes":[]},{"number":17,"text":"but when he was in Rome, he sought me diligently and found me","notes":[]},{"number":18,"text":"(the Lord grant to him to find the Lord’s mercy in that day); and in how many things he served at Ephesus, you know very well.","notes":[]}],"source":"https://ebible.org/engwebp/2TI01.htm"},"2TI-2":{"book":"2 Timothy","chapter":2,"verses":[{"number":1,"text":"You therefore, my child, be strengthened in the grace that is in Christ Jesus.","notes":[]},{"number":2,"text":"The things which you have heard from me among many witnesses, commit the same things to faithful men who will be able to teach others also.","notes":[]},{"number":3,"text":"You therefore must endure hardship as a good soldier of Christ Jesus.","notes":[]},{"number":4,"text":"No soldier on duty entangles himself in the affairs of life, that he may please him who enrolled him as a soldier.","notes":[]},{"number":5,"text":"Also, if anyone competes in athletics, he isn’t crowned unless he has competed by the rules.","notes":[]},{"number":6,"text":"The farmer who labors must be the first to get a share of the crops.","notes":[]},{"number":7,"text":"Consider what I say, and may the Lord give you understanding in all things.","notes":[]},{"number":8,"text":"Remember Jesus Christ, risen from the dead, of the offspring of David, according to my Good News,","notes":["or, seed"]},{"number":9,"text":"in which I suffer hardship to the point of chains as a criminal. But God’s word isn’t chained.","notes":[]},{"number":10,"text":"Therefore I endure all things for the chosen ones’ sake, that they also may obtain the salvation which is in Christ Jesus with eternal glory.","notes":[]},{"number":11,"text":"This saying is trustworthy: “For if we died with him, we will also live with him.","notes":[]},{"number":12,"text":"If we endure, we will also reign with him. If we deny him, he also will deny us.","notes":[]},{"number":13,"text":"If we are faithless, he remains faithful; for he can’t deny himself.”","notes":[]},{"number":14,"text":"Remind them of these things, charging them in the sight of the Lord that they don’t argue about words to no profit, to the subverting of those who hear.","notes":[]},{"number":15,"text":"Give diligence to present yourself approved by God, a workman who doesn’t need to be ashamed, properly handling the Word of Truth.","notes":[]},{"number":16,"text":"But shun empty chatter, for it will go further in ungodliness,","notes":[]},{"number":17,"text":"and those words will consume like gangrene, of whom is Hymenaeus and Philetus:","notes":[]},{"number":18,"text":"men who have erred concerning the truth, saying that the resurrection is already past, and overthrowing the faith of some.","notes":[]},{"number":19,"text":"However, God’s firm foundation stands, having this seal: “The Lord knows those who are his,” and, “Let every one who names the name of the Lord depart from unrighteousness.”","notes":["Numbers 16:5","TR reads “Christ” instead of “the Lord”"]},{"number":20,"text":"Now in a large house there are not only vessels of gold and of silver, but also of wood and of clay. Some are for honor and some for dishonor.","notes":[]},{"number":21,"text":"If anyone therefore purges himself from these, he will be a vessel for honor, sanctified, and suitable for the master’s use, prepared for every good work.","notes":[]},{"number":22,"text":"Flee from youthful lusts; but pursue righteousness, faith, love, and peace with those who call on the Lord out of a pure heart.","notes":[]},{"number":23,"text":"But refuse foolish and ignorant questionings, knowing that they generate strife.","notes":[]},{"number":24,"text":"The Lord’s servant must not quarrel, but be gentle toward all, able to teach, patient,","notes":[]},{"number":25,"text":"in gentleness correcting those who oppose him. Perhaps God may give them repentance leading to a full knowledge of the truth,","notes":[]},{"number":26,"text":"and they may recover themselves out of the devil’s snare, having been taken captive by him to do his will.","notes":[]}],"source":"https://ebible.org/engwebp/2TI02.htm"},"3JN-1":{"book":"3 John","chapter":1,"verses":[{"number":1,"text":"The elder to Gaius the beloved, whom I love in truth.","notes":[]},{"number":2,"text":"Beloved, I pray that you may prosper in all things and be healthy, even as your soul prospers.","notes":[]},{"number":3,"text":"For I rejoiced greatly when brothers came and testified about your truth, even as you walk in truth.","notes":[]},{"number":4,"text":"I have no greater joy than this: to hear about my children walking in truth.","notes":[]},{"number":5,"text":"Beloved, you do a faithful work in whatever you accomplish for those who are brothers and strangers.","notes":[]},{"number":6,"text":"They have testified about your love before the assembly. You will do well to send them forward on their journey in a way worthy of God,","notes":[]},{"number":7,"text":"because for the sake of the Name they went out, taking nothing from the Gentiles.","notes":[]},{"number":8,"text":"We therefore ought to receive such, that we may be fellow workers for the truth.","notes":[]},{"number":9,"text":"I wrote to the assembly, but Diotrephes, who loves to be first among them, doesn’t accept what we say.","notes":[]},{"number":10,"text":"Therefore, if I come, I will call attention to his deeds which he does, unjustly accusing us with wicked words. Not content with this, he doesn’t receive the brothers himself, and those who would, he forbids and throws out of the assembly.","notes":[]},{"number":11,"text":"Beloved, don’t imitate that which is evil, but that which is good. He who does good is of God. He who does evil hasn’t seen God.","notes":[]},{"number":12,"text":"Demetrius has the testimony of all, and of the truth itself; yes, we also testify, and you know that our testimony is true.","notes":[]},{"number":13,"text":"I had many things to write to you, but I am unwilling to write to you with ink and pen;","notes":[]},{"number":14,"text":"but I hope to see you soon. Then we will speak face to face. Peace be to you. The friends greet you. Greet the friends by name.","notes":[]}],"source":"https://ebible.org/engwebp/3JN01.htm"},"ACT-1":{"book":"Acts","chapter":1,"verses":[{"number":1,"text":"The first book I wrote, Theophilus, concerned all that Jesus began both to do and to teach,","notes":[]},{"number":2,"text":"until the day in which he was received up, after he had given commandment through the Holy Spirit to the apostles whom he had chosen.","notes":[]},{"number":3,"text":"To these he also showed himself alive after he suffered, by many proofs, appearing to them over a period of forty days and speaking about God’s Kingdom.","notes":[]},{"number":4,"text":"Being assembled together with them, he commanded them, “Don’t depart from Jerusalem, but wait for the promise of the Father, which you heard from me.","notes":[]},{"number":5,"text":"For John indeed baptized in water, but you will be baptized in the Holy Spirit not many days from now.”","notes":[]},{"number":6,"text":"Therefore, when they had come together, they asked him, “Lord, are you now restoring the kingdom to Israel?”","notes":[]},{"number":7,"text":"He said to them, “It isn’t for you to know times or seasons which the Father has set within his own authority.","notes":[]},{"number":8,"text":"But you will receive power when the Holy Spirit has come upon you. You will be witnesses to me in Jerusalem, in all Judea and Samaria, and to the uttermost parts of the earth.”","notes":[]},{"number":9,"text":"When he had said these things, as they were looking, he was taken up, and a cloud received him out of their sight.","notes":[]},{"number":10,"text":"While they were looking steadfastly into the sky as he went, behold, two men stood by them in white clothing,","notes":["“Behold”, from “ἰδοὺ”, means look at, take notice, observe, see, or gaze at. It is often used as an interjection."]},{"number":11,"text":"who also said, “You men of Galilee, why do you stand looking into the sky? This Jesus, who was received up from you into the sky, will come back in the same way as you saw him going into the sky.”","notes":[]},{"number":12,"text":"Then they returned to Jerusalem from the mountain called Olivet, which is near Jerusalem, a Sabbath day’s journey away.","notes":[]},{"number":13,"text":"When they had come in, they went up into the upper room where they were staying, that is Peter, John, James, Andrew, Philip, Thomas, Bartholomew, Matthew, James the son of Alphaeus, Simon the Zealot, and Judas the son of James.","notes":[]},{"number":14,"text":"All these with one accord continued steadfastly in prayer and supplication, along with the women and Mary the mother of Jesus, and with his brothers.","notes":[]},{"number":15,"text":"In these days, Peter stood up in the middle of the disciples (and the number of names was about one hundred twenty), and said,","notes":[]},{"number":16,"text":"“Brothers, it was necessary that this Scripture should be fulfilled, which the Holy Spirit spoke before by the mouth of David concerning Judas, who was guide to those who took Jesus.","notes":[]},{"number":17,"text":"For he was counted with us, and received his portion in this ministry.","notes":[]},{"number":18,"text":"Now this man obtained a field with the reward for his wickedness; and falling headlong, his body burst open and all his intestines gushed out.","notes":[]},{"number":19,"text":"It became known to everyone who lived in Jerusalem that in their language that field was called ‘Akeldama,’ that is, ‘The field of blood.’","notes":[]},{"number":20,"text":"For it is written in the book of Psalms, ‘Let his habitation be made desolate. Let no one dwell in it;’ and, ‘Let another take his office.’","notes":["Psalms 69:25","Psalms 109:8"]},{"number":21,"text":"“Of the men therefore who have accompanied us all the time that the Lord Jesus went in and out among us,","notes":[]},{"number":22,"text":"beginning from the baptism of John to the day that he was received up from us, of these one must become a witness with us of his resurrection.”","notes":[]},{"number":23,"text":"They put forward two: Joseph called Barsabbas, who was also called Justus, and Matthias.","notes":[]},{"number":24,"text":"They prayed and said, “You, Lord, who know the hearts of all men, show which one of these two you have chosen","notes":[]},{"number":25,"text":"to take part in this ministry and apostleship from which Judas fell away, that he might go to his own place.”","notes":[]},{"number":26,"text":"They drew lots for them, and the lot fell on Matthias; and he was counted with the eleven apostles.","notes":[]}],"source":"https://ebible.org/engwebp/ACT01.htm"},"ACT-13":{"book":"Acts","chapter":13,"verses":[{"number":1,"text":"Now in the assembly that was at Antioch there were some prophets and teachers: Barnabas, Simeon who was called Niger, Lucius of Cyrene, Manaen the foster brother of Herod the tetrarch, and Saul.","notes":[]},{"number":2,"text":"As they served the Lord and fasted, the Holy Spirit said, “Separate Barnabas and Saul for me, for the work to which I have called them.”","notes":[]},{"number":3,"text":"Then, when they had fasted and prayed and laid their hands on them, they sent them away.","notes":[]},{"number":4,"text":"So, being sent out by the Holy Spirit, they went down to Seleucia. From there they sailed to Cyprus.","notes":[]},{"number":5,"text":"When they were at Salamis, they proclaimed God’s word in the Jewish synagogues. They also had John as their attendant.","notes":[]},{"number":6,"text":"When they had gone through the island to Paphos, they found a certain sorcerer, a false prophet, a Jew whose name was Bar Jesus,","notes":[]},{"number":7,"text":"who was with the proconsul, Sergius Paulus, a man of understanding. This man summoned Barnabas and Saul, and sought to hear the word of God.","notes":[]},{"number":8,"text":"But Elymas the sorcerer (for so is his name by interpretation) withstood them, seeking to turn the proconsul away from the faith.","notes":[]},{"number":9,"text":"But Saul, who is also called Paul, filled with the Holy Spirit, fastened his eyes on him","notes":[]},{"number":10,"text":"and said, “You son of the devil, full of all deceit and all cunning, you enemy of all righteousness, will you not cease to pervert the right ways of the Lord?","notes":[]},{"number":11,"text":"Now, behold, the hand of the Lord is on you, and you will be blind, not seeing the sun for a season!” Immediately a mist and darkness fell on him. He went around seeking someone to lead him by the hand.","notes":[]},{"number":12,"text":"Then the proconsul, when he saw what was done, believed, being astonished at the teaching of the Lord.","notes":[]},{"number":13,"text":"Now Paul and his company set sail from Paphos and came to Perga in Pamphylia. John departed from them and returned to Jerusalem.","notes":[]},{"number":14,"text":"But they, passing on from Perga, came to Antioch of Pisidia. They went into the synagogue on the Sabbath day and sat down.","notes":[]},{"number":15,"text":"After the reading of the law and the prophets, the rulers of the synagogue sent to them, saying, “Brothers, if you have any word of exhortation for the people, speak.”","notes":[]},{"number":16,"text":"Paul stood up, and gesturing with his hand said, “Men of Israel, and you who fear God, listen.","notes":[]},{"number":17,"text":"The God of this people chose our fathers, and exalted the people when they stayed as aliens in the land of Egypt, and with an uplifted arm, he led them out of it.","notes":["TR, NU add “Israel”"]},{"number":18,"text":"For a period of about forty years he put up with them in the wilderness.","notes":[]},{"number":19,"text":"When he had destroyed seven nations in the land of Canaan, he gave them their land for an inheritance for about four hundred fifty years.","notes":[]},{"number":20,"text":"After these things, he gave them judges until Samuel the prophet.","notes":[]},{"number":21,"text":"Afterward they asked for a king, and God gave to them Saul the son of Kish, a man of the tribe of Benjamin, for forty years.","notes":[]},{"number":22,"text":"When he had removed him, he raised up David to be their king, to whom he also testified, ‘I have found David the son of Jesse, a man after my heart, who will do all my will.’","notes":[]},{"number":23,"text":"From this man’s offspring, God has brought salvation to Israel according to his promise,","notes":["TR, NU read “a Savior, Jesus” instead of “salvation”"]},{"number":24,"text":"before his coming, when John had first preached the baptism of repentance to Israel.","notes":["TR, NU read “to all the people of Israel” instead of “to Israel”"]},{"number":25,"text":"As John was fulfilling his course, he said, ‘What do you suppose that I am? I am not he. But behold, one comes after me, the sandals of whose feet I am not worthy to untie.’","notes":[]},{"number":26,"text":"“Brothers, children of the stock of Abraham, and those among you who fear God, the word of this salvation is sent out to you.","notes":[]},{"number":27,"text":"For those who dwell in Jerusalem, and their rulers, because they didn’t know him, nor the voices of the prophets which are read every Sabbath, fulfilled them by condemning him.","notes":[]},{"number":28,"text":"Though they found no cause for death, they still asked Pilate to have him killed.","notes":[]},{"number":29,"text":"When they had fulfilled all things that were written about him, they took him down from the tree and laid him in a tomb.","notes":[]},{"number":30,"text":"But God raised him from the dead,","notes":[]},{"number":31,"text":"and he was seen for many days by those who came up with him from Galilee to Jerusalem, who are his witnesses to the people.","notes":[]},{"number":32,"text":"We bring you good news of the promise made to the fathers,","notes":[]},{"number":33,"text":"that God has fulfilled this to us, their children, in that he raised up Jesus. As it is also written in the second psalm, ‘You are my Son. Today I have become your father.’","notes":["Psalms 2:7"]},{"number":34,"text":"“Concerning that he raised him up from the dead, now no more to return to corruption, he has spoken thus: ‘I will give you the holy and sure blessings of David.’","notes":["Isaiah 55:3"]},{"number":35,"text":"Therefore he says also in another psalm, ‘You will not allow your Holy One to see decay.’","notes":["Psalms 16:10"]},{"number":36,"text":"For David, after he had in his own generation served the counsel of God, fell asleep, was laid with his fathers, and saw decay.","notes":[]},{"number":37,"text":"But he whom God raised up saw no decay.","notes":[]},{"number":38,"text":"Be it known to you therefore, brothers, that through this man is proclaimed to you remission of sins;","notes":["The word for “brothers” here and where the context allows may also be correctly translated “brothers and sisters” or “siblings.”"]},{"number":39,"text":"and by him everyone who believes is justified from all things, from which you could not be justified by the law of Moses.","notes":[]},{"number":40,"text":"Beware therefore, lest that come on you which is spoken in the prophets:","notes":[]},{"number":41,"text":"‘Behold, you scoffers! Wonder and perish, for I work a work in your days, a work which you will in no way believe, if one declares it to you.’ ”","notes":["Habakkuk 1:5"]},{"number":42,"text":"So when the Jews went out of the synagogue, the Gentiles begged that these words might be preached to them the next Sabbath.","notes":[]},{"number":43,"text":"Now when the synagogue broke up, many of the Jews and of the devout proselytes followed Paul and Barnabas; who, speaking to them, urged them to continue in the grace of God.","notes":[]},{"number":44,"text":"The next Sabbath, almost the whole city was gathered together to hear the word of God.","notes":[]},{"number":45,"text":"But when the Jews saw the multitudes, they were filled with jealousy, and contradicted the things which were spoken by Paul, and blasphemed.","notes":[]},{"number":46,"text":"Paul and Barnabas spoke out boldly, and said, “It was necessary that God’s word should be spoken to you first. Since indeed you thrust it from yourselves, and judge yourselves unworthy of eternal life, behold, we turn to the Gentiles.","notes":[]},{"number":47,"text":"For so has the Lord commanded us, saying, ‘I have set you as a light for the Gentiles, that you should bring salvation to the uttermost parts of the earth.’ ”","notes":["Isaiah 49:6"]},{"number":48,"text":"As the Gentiles heard this, they were glad and glorified the word of God. As many as were appointed to eternal life believed.","notes":[]},{"number":49,"text":"The Lord’s word was spread abroad throughout all the region.","notes":[]},{"number":50,"text":"But the Jews stirred up the devout and prominent women and the chief men of the city, and stirred up a persecution against Paul and Barnabas, and threw them out of their borders.","notes":[]},{"number":51,"text":"But they shook off the dust of their feet against them, and came to Iconium.","notes":[]},{"number":52,"text":"The disciples were filled with joy and with the Holy Spirit.","notes":[]}],"source":"https://ebible.org/engwebp/ACT13.htm"},"ACT-14":{"book":"Acts","chapter":14,"verses":[{"number":1,"text":"In Iconium, they entered together into the synagogue of the Jews, and so spoke that a great multitude both of Jews and of Greeks believed.","notes":[]},{"number":2,"text":"But the disbelieving Jews stirred up and embittered the souls of the Gentiles against the brothers.","notes":["or, disobedient"]},{"number":3,"text":"Therefore they stayed there a long time, speaking boldly in the Lord, who testified to the word of his grace, granting signs and wonders to be done by their hands.","notes":[]},{"number":4,"text":"But the multitude of the city was divided. Part sided with the Jews and part with the apostles.","notes":[]},{"number":5,"text":"When some of both the Gentiles and the Jews, with their rulers, made a violent attempt to mistreat and stone them,","notes":[]},{"number":6,"text":"they became aware of it and fled to the cities of Lycaonia, Lystra, Derbe, and the surrounding region.","notes":[]},{"number":7,"text":"There they preached the Good News.","notes":[]},{"number":8,"text":"At Lystra a certain man sat, impotent in his feet, a cripple from his mother’s womb, who never had walked.","notes":[]},{"number":9,"text":"He was listening to Paul speaking, who, fastening eyes on him and seeing that he had faith to be made whole,","notes":[]},{"number":10,"text":"said with a loud voice, “Stand upright on your feet!” He leaped up and walked.","notes":[]},{"number":11,"text":"When the multitude saw what Paul had done, they lifted up their voice, saying in the language of Lycaonia, “The gods have come down to us in the likeness of men!”","notes":[]},{"number":12,"text":"They called Barnabas “Jupiter”, and Paul “Mercury”, because he was the chief speaker.","notes":[]},{"number":13,"text":"The priest of Jupiter, whose temple was in front of their city, brought oxen and garlands to the gates, and would have made a sacrifice along with the multitudes.","notes":[]},{"number":14,"text":"But when the apostles, Barnabas and Paul, heard of it, they tore their clothes and sprang into the multitude, crying out,","notes":[]},{"number":15,"text":"“Men, why are you doing these things? We also are men of the same nature as you, and bring you good news, that you should turn from these vain things to the living God, who made the sky, the earth, the sea, and all that is in them;","notes":[]},{"number":16,"text":"who in the generations gone by allowed all the nations to walk in their own ways.","notes":[]},{"number":17,"text":"Yet he didn’t leave himself without witness, in that he did good and gave you rains from the sky and fruitful seasons, filling our hearts with food and gladness.”","notes":["TR reads “us” instead of “you”"]},{"number":18,"text":"Even saying these things, they hardly stopped the multitudes from making a sacrifice to them.","notes":[]},{"number":19,"text":"But some Jews from Antioch and Iconium came there, and having persuaded the multitudes, they stoned Paul and dragged him out of the city, supposing that he was dead.","notes":[]},{"number":20,"text":"But as the disciples stood around him, he rose up, and entered into the city. On the next day he went out with Barnabas to Derbe.","notes":[]},{"number":21,"text":"When they had preached the Good News to that city and had made many disciples, they returned to Lystra, Iconium, and Antioch,","notes":[]},{"number":22,"text":"strengthening the souls of the disciples, exhorting them to continue in the faith, and that through many afflictions we must enter into God’s Kingdom.","notes":[]},{"number":23,"text":"When they had appointed elders for them in every assembly, and had prayed with fasting, they commended them to the Lord on whom they had believed.","notes":[]},{"number":24,"text":"They passed through Pisidia and came to Pamphylia.","notes":[]},{"number":25,"text":"When they had spoken the word in Perga, they went down to Attalia.","notes":[]},{"number":26,"text":"From there they sailed to Antioch, from where they had been committed to the grace of God for the work which they had fulfilled.","notes":[]},{"number":27,"text":"When they had arrived and had gathered the assembly together, they reported all the things that God had done with them, and that he had opened a door of faith to the nations.","notes":[]},{"number":28,"text":"They stayed there with the disciples for a long time.","notes":[]}],"source":"https://ebible.org/engwebp/ACT14.htm"},"ACT-17":{"book":"Acts","chapter":17,"verses":[{"number":1,"text":"Now when they had passed through Amphipolis and Apollonia, they came to Thessalonica, where there was a Jewish synagogue.","notes":[]},{"number":2,"text":"Paul, as was his custom, went in to them; and for three Sabbath days reasoned with them from the Scriptures,","notes":[]},{"number":3,"text":"explaining and demonstrating that the Christ had to suffer and rise again from the dead, and saying, “This Jesus, whom I proclaim to you, is the Christ.”","notes":[]},{"number":4,"text":"Some of them were persuaded and joined Paul and Silas: of the devout Greeks a great multitude, and not a few of the chief women.","notes":[]},{"number":5,"text":"But the unpersuaded Jews took along some wicked men from the marketplace and gathering a crowd, set the city in an uproar. Assaulting the house of Jason, they sought to bring them out to the people.","notes":["TR reads “And the Jews who were unpersuaded, becoming envious and taking along” instead of “But the unpersuaded Jews took along”"]},{"number":6,"text":"When they didn’t find them, they dragged Jason and certain brothers before the rulers of the city, crying, “These who have turned the world upside down have come here also,","notes":["The word for “brothers” here and where the context allows may be also correctly translated “brothers and sisters” or “siblings.”"]},{"number":7,"text":"whom Jason has received. These all act contrary to the decrees of Caesar, saying that there is another king, Jesus!”","notes":[]},{"number":8,"text":"The multitude and the rulers of the city were troubled when they heard these things.","notes":[]},{"number":9,"text":"When they had taken security from Jason and the rest, they let them go.","notes":[]},{"number":10,"text":"The brothers immediately sent Paul and Silas away by night to Beroea. When they arrived, they went into the Jewish synagogue.","notes":[]},{"number":11,"text":"Now these were more noble than those in Thessalonica, in that they received the word with all readiness of mind, examining the Scriptures daily to see whether these things were so.","notes":[]},{"number":12,"text":"Many of them therefore believed; also of the prominent Greek women, and not a few men.","notes":[]},{"number":13,"text":"But when the Jews of Thessalonica had knowledge that the word of God was proclaimed by Paul at Beroea also, they came there likewise, agitating the multitudes.","notes":[]},{"number":14,"text":"Then the brothers immediately sent out Paul to go as far as to the sea, and Silas and Timothy still stayed there.","notes":[]},{"number":15,"text":"But those who escorted Paul brought him as far as Athens. Receiving a commandment to Silas and Timothy that they should come to him very quickly, they departed.","notes":[]},{"number":16,"text":"Now while Paul waited for them at Athens, his spirit was provoked within him as he saw the city full of idols.","notes":[]},{"number":17,"text":"So he reasoned in the synagogue with the Jews and the devout persons, and in the marketplace every day with those who met him.","notes":[]},{"number":18,"text":"Some of the Epicurean and Stoic philosophers also were conversing with him. Some said, “What does this babbler want to say?” Others said, “He seems to be advocating foreign deities,” because he preached Jesus and the resurrection.","notes":["TR omits “also”"]},{"number":19,"text":"They took hold of him and brought him to the Areopagus, saying, “May we know what this new teaching is, which you are speaking about?","notes":[]},{"number":20,"text":"For you bring certain strange things to our ears. We want to know therefore what these things mean.”","notes":[]},{"number":21,"text":"Now all the Athenians and the strangers living there spent their time in nothing else, but either to tell or to hear some new thing.","notes":[]},{"number":22,"text":"Paul stood in the middle of the Areopagus and said, “You men of Athens, I perceive that you are very religious in all things.","notes":[]},{"number":23,"text":"For as I passed along and observed the objects of your worship, I also found an altar with this inscription: ‘TO AN UNKNOWN GOD.’ What therefore you worship in ignorance, I announce to you.","notes":[]},{"number":24,"text":"The God who made the world and all things in it, he, being Lord of heaven and earth, doesn’t dwell in temples made with hands.","notes":[]},{"number":25,"text":"He isn’t served by men’s hands, as though he needed anything, seeing he himself gives to all life and breath and all things.","notes":[]},{"number":26,"text":"He made from one blood every nation of men to dwell on all the surface of the earth, having determined appointed seasons and the boundaries of their dwellings,","notes":[]},{"number":27,"text":"that they should seek the Lord, if perhaps they might reach out for him and find him, though he is not far from each one of us.","notes":[]},{"number":28,"text":"‘For in him we live, move, and have our being.’ As some of your own poets have said, ‘For we are also his offspring.’","notes":[]},{"number":29,"text":"Being then the offspring of God, we ought not to think that the Divine Nature is like gold, or silver, or stone, engraved by art and design of man.","notes":[]},{"number":30,"text":"The times of ignorance therefore God overlooked. But now he commands that all people everywhere should repent,","notes":[]},{"number":31,"text":"because he has appointed a day in which he will judge the world in righteousness by the man whom he has ordained; of which he has given assurance to all men, in that he has raised him from the dead.”","notes":[]},{"number":32,"text":"Now when they heard of the resurrection of the dead, some mocked; but others said, “We want to hear you again concerning this.”","notes":[]},{"number":33,"text":"Thus Paul went out from among them.","notes":[]},{"number":34,"text":"But certain men joined with him and believed, including Dionysius the Areopagite, and a woman named Damaris, and others with them.","notes":[]}],"source":"https://ebible.org/engwebp/ACT17.htm"},"ACT-18":{"book":"Acts","chapter":18,"verses":[{"number":1,"text":"After these things Paul departed from Athens and came to Corinth.","notes":[]},{"number":2,"text":"He found a certain Jew named Aquila, a man of Pontus by race, who had recently come from Italy with his wife Priscilla, because Claudius had commanded all the Jews to depart from Rome. He came to them,","notes":[]},{"number":3,"text":"and because he practiced the same trade, he lived with them and worked, for by trade they were tent makers.","notes":[]},{"number":4,"text":"He reasoned in the synagogue every Sabbath and persuaded Jews and Greeks.","notes":[]},{"number":5,"text":"When Silas and Timothy came down from Macedonia, Paul was compelled by the Spirit, testifying to the Jews that Jesus was the Christ.","notes":[]},{"number":6,"text":"When they opposed him and blasphemed, he shook out his clothing and said to them, “Your blood be on your own heads! I am clean. From now on, I will go to the Gentiles!”","notes":[]},{"number":7,"text":"He departed there and went into the house of a certain man named Justus, one who worshiped God, whose house was next door to the synagogue.","notes":[]},{"number":8,"text":"Crispus, the ruler of the synagogue, believed in the Lord with all his house. Many of the Corinthians, when they heard, believed and were baptized.","notes":[]},{"number":9,"text":"The Lord said to Paul in the night by a vision, “Don’t be afraid, but speak and don’t be silent;","notes":[]},{"number":10,"text":"for I am with you, and no one will attack you to harm you, for I have many people in this city.”","notes":[]},{"number":11,"text":"He lived there a year and six months, teaching the word of God among them.","notes":[]},{"number":12,"text":"But when Gallio was proconsul of Achaia, the Jews with one accord rose up against Paul and brought him before the judgment seat,","notes":[]},{"number":13,"text":"saying, “This man persuades men to worship God contrary to the law.”","notes":[]},{"number":14,"text":"But when Paul was about to open his mouth, Gallio said to the Jews, “If indeed it were a matter of wrong or of wicked crime, you Jews, it would be reasonable that I should bear with you;","notes":[]},{"number":15,"text":"but if they are questions about words and names and your own law, look to it yourselves. For I don’t want to be a judge of these matters.”","notes":[]},{"number":16,"text":"So he drove them from the judgment seat.","notes":[]},{"number":17,"text":"Then all the Greeks seized Sosthenes, the ruler of the synagogue, and beat him before the judgment seat. Gallio didn’t care about any of these things.","notes":[]},{"number":18,"text":"Paul, having stayed after this many more days, took his leave of the brothers, and sailed from there for Syria, together with Priscilla and Aquila. He shaved his head in Cenchreae, for he had a vow.","notes":["The word for “brothers” here and where the context allows may also be correctly translated “brothers and sisters” or “siblings.”"]},{"number":19,"text":"He came to Ephesus, and he left them there; but he himself entered into the synagogue and reasoned with the Jews.","notes":[]},{"number":20,"text":"When they asked him to stay with them a longer time, he declined;","notes":[]},{"number":21,"text":"but taking his leave of them, he said, “I must by all means keep this coming feast in Jerusalem, but I will return again to you if God wills.” Then he set sail from Ephesus.","notes":[]},{"number":22,"text":"When he had landed at Caesarea, he went up and greeted the assembly, and went down to Antioch.","notes":[]},{"number":23,"text":"Having spent some time there, he departed and went through the region of Galatia and Phrygia, in order, establishing all the disciples.","notes":[]},{"number":24,"text":"Now a certain Jew named Apollos, an Alexandrian by race, an eloquent man, came to Ephesus. He was mighty in the Scriptures.","notes":[]},{"number":25,"text":"This man had been instructed in the way of the Lord; and being fervent in spirit, he spoke and taught accurately the things concerning Jesus, although he knew only the baptism of John.","notes":[]},{"number":26,"text":"He began to speak boldly in the synagogue. But when Priscilla and Aquila heard him, they took him aside, and explained to him the way of God more accurately.","notes":[]},{"number":27,"text":"When he had determined to pass over into Achaia, the brothers encouraged him; and wrote to the disciples to receive him. When he had come, he greatly helped those who had believed through grace;","notes":[]},{"number":28,"text":"for he powerfully refuted the Jews, publicly showing by the Scriptures that Jesus was the Christ.","notes":[]}],"source":"https://ebible.org/engwebp/ACT18.htm"},"ACT-19":{"book":"Acts","chapter":19,"verses":[{"number":1,"text":"While Apollos was at Corinth, Paul, having passed through the upper country, came to Ephesus and found certain disciples.","notes":[]},{"number":2,"text":"He said to them, “Did you receive the Holy Spirit when you believed?” They said to him, “No, we haven’t even heard that there is a Holy Spirit.”","notes":[]},{"number":3,"text":"He said, “Into what then were you baptized?” They said, “Into John’s baptism.”","notes":[]},{"number":4,"text":"Paul said, “John indeed baptized with the baptism of repentance, saying to the people that they should believe in the one who would come after him, that is, in Christ Jesus.”","notes":["NU omits Christ."]},{"number":5,"text":"When they heard this, they were baptized in the name of the Lord Jesus.","notes":[]},{"number":6,"text":"When Paul had laid his hands on them, the Holy Spirit came on them and they spoke with other languages and prophesied.","notes":[]},{"number":7,"text":"They were about twelve men in all.","notes":[]},{"number":8,"text":"He entered into the synagogue and spoke boldly for a period of three months, reasoning and persuading about the things concerning God’s Kingdom.","notes":[]},{"number":9,"text":"But when some were hardened and disobedient, speaking evil of the Way before the multitude, he departed from them and separated the disciples, reasoning daily in the school of Tyrannus.","notes":[]},{"number":10,"text":"This continued for two years, so that all those who lived in Asia heard the word of the Lord Jesus, both Jews and Greeks.","notes":[]},{"number":11,"text":"God worked special miracles by the hands of Paul,","notes":[]},{"number":12,"text":"so that even handkerchiefs or aprons were carried away from his body to the sick, and the diseases departed from them, and the evil spirits went out.","notes":[]},{"number":13,"text":"But some of the itinerant Jews, exorcists, took on themselves to invoke over those who had the evil spirits the name of the Lord Jesus, saying, “We adjure you by Jesus whom Paul preaches.”","notes":[]},{"number":14,"text":"There were seven sons of one Sceva, a Jewish chief priest, who did this.","notes":[]},{"number":15,"text":"The evil spirit answered, “Jesus I know, and Paul I know, but who are you?”","notes":[]},{"number":16,"text":"The man in whom the evil spirit was leaped on them, overpowered them, and prevailed against them, so that they fled out of that house naked and wounded.","notes":[]},{"number":17,"text":"This became known to all, both Jews and Greeks, who lived at Ephesus. Fear fell on them all, and the name of the Lord Jesus was magnified.","notes":[]},{"number":18,"text":"Many also of those who had believed came, confessing and declaring their deeds.","notes":[]},{"number":19,"text":"Many of those who practiced magical arts brought their books together and burned them in the sight of all. They counted their price, and found it to be fifty thousand pieces of silver.","notes":["The 50,000 pieces of silver here probably referred to 50,000 drachmas. If so, the value of the burned books was equivalent to about 160 man-years of wages for agricultural laborers"]},{"number":20,"text":"So the word of the Lord was growing and becoming mighty.","notes":[]},{"number":21,"text":"Now after these things had ended, Paul determined in the Spirit, when he had passed through Macedonia and Achaia, to go to Jerusalem, saying, “After I have been there, I must also see Rome.”","notes":[]},{"number":22,"text":"Having sent into Macedonia two of those who served him, Timothy and Erastus, he himself stayed in Asia for a while.","notes":[]},{"number":23,"text":"About that time there arose no small disturbance concerning the Way.","notes":[]},{"number":24,"text":"For a certain man named Demetrius, a silversmith who made silver shrines of Artemis, brought no little business to the craftsmen,","notes":[]},{"number":25,"text":"whom he gathered together with the workmen of like occupation, and said, “Sirs, you know that by this business we have our wealth.","notes":[]},{"number":26,"text":"You see and hear that not at Ephesus alone, but almost throughout all Asia, this Paul has persuaded and turned away many people, saying that they are no gods that are made with hands.","notes":[]},{"number":27,"text":"Not only is there danger that this our trade come into disrepute, but also that the temple of the great goddess Artemis will be counted as nothing and her majesty destroyed, whom all Asia and the world worships.”","notes":[]},{"number":28,"text":"When they heard this they were filled with anger, and cried out, saying, “Great is Artemis of the Ephesians!”","notes":[]},{"number":29,"text":"The whole city was filled with confusion, and they rushed with one accord into the theater, having seized Gaius and Aristarchus, men of Macedonia, Paul’s companions in travel.","notes":[]},{"number":30,"text":"When Paul wanted to enter in to the people, the disciples didn’t allow him.","notes":[]},{"number":31,"text":"Certain also of the Asiarchs, being his friends, sent to him and begged him not to venture into the theater.","notes":[]},{"number":32,"text":"Some therefore cried one thing, and some another, for the assembly was in confusion. Most of them didn’t know why they had come together.","notes":[]},{"number":33,"text":"They brought Alexander out of the multitude, the Jews putting him forward. Alexander beckoned with his hand, and would have made a defense to the people.","notes":[]},{"number":34,"text":"But when they perceived that he was a Jew, all with one voice for a time of about two hours cried out, “Great is Artemis of the Ephesians!”","notes":[]},{"number":35,"text":"When the town clerk had quieted the multitude, he said, “You men of Ephesus, what man is there who doesn’t know that the city of the Ephesians is temple keeper of the great goddess Artemis, and of the image which fell down from Zeus?","notes":[]},{"number":36,"text":"Seeing then that these things can’t be denied, you ought to be quiet and to do nothing rash.","notes":[]},{"number":37,"text":"For you have brought these men here, who are neither robbers of temples nor blasphemers of your goddess.","notes":[]},{"number":38,"text":"If therefore Demetrius and the craftsmen who are with him have a matter against anyone, the courts are open and there are proconsuls. Let them press charges against one another.","notes":[]},{"number":39,"text":"But if you seek anything about other matters, it will be settled in the regular assembly.","notes":[]},{"number":40,"text":"For indeed we are in danger of being accused concerning today’s riot, there being no cause. Concerning it, we wouldn’t be able to give an account of this commotion.”","notes":[]},{"number":41,"text":"When he had thus spoken, he dismissed the assembly.","notes":[]}],"source":"https://ebible.org/engwebp/ACT19.htm"},"ACT-2":{"book":"Acts","chapter":2,"verses":[{"number":1,"text":"Now when the day of Pentecost had come, they were all with one accord in one place.","notes":[]},{"number":2,"text":"Suddenly there came from the sky a sound like the rushing of a mighty wind, and it filled all the house where they were sitting.","notes":[]},{"number":3,"text":"Tongues like fire appeared and were distributed to them, and one sat on each of them.","notes":[]},{"number":4,"text":"They were all filled with the Holy Spirit and began to speak with other languages, as the Spirit gave them the ability to speak.","notes":[]},{"number":5,"text":"Now there were dwelling in Jerusalem Jews, devout men, from every nation under the sky.","notes":[]},{"number":6,"text":"When this sound was heard, the multitude came together and were bewildered, because everyone heard them speaking in his own language.","notes":[]},{"number":7,"text":"They were all amazed and marveled, saying to one another, “Behold, aren’t all these who speak Galileans?","notes":[]},{"number":8,"text":"How do we hear, everyone in our own native language?","notes":[]},{"number":9,"text":"Parthians, Medes, Elamites, and people from Mesopotamia, Judea, Cappadocia, Pontus, Asia,","notes":[]},{"number":10,"text":"Phrygia, Pamphylia, Egypt, the parts of Libya around Cyrene, visitors from Rome, both Jews and proselytes,","notes":[]},{"number":11,"text":"Cretans and Arabians—we hear them speaking in our languages the mighty works of God!”","notes":[]},{"number":12,"text":"They were all amazed and were perplexed, saying to one another, “What does this mean?”","notes":[]},{"number":13,"text":"Others, mocking, said, “They are filled with new wine.”","notes":[]},{"number":14,"text":"But Peter, standing up with the eleven, lifted up his voice and spoke out to them, “You men of Judea and all you who dwell at Jerusalem, let this be known to you, and listen to my words.","notes":[]},{"number":15,"text":"For these aren’t drunken, as you suppose, seeing it is only the third hour of the day.","notes":["about 9:00 a.m."]},{"number":16,"text":"But this is what has been spoken through the prophet Joel:","notes":[]},{"number":17,"text":"‘It will be in the last days, says God, that I will pour out my Spirit on all flesh. Your sons and your daughters will prophesy. Your young men will see visions. Your old men will dream dreams.","notes":[]},{"number":18,"text":"Yes, and on my servants and on my handmaidens in those days, I will pour out my Spirit, and they will prophesy.","notes":[]},{"number":19,"text":"I will show wonders in the sky above, and signs on the earth beneath: blood, and fire, and billows of smoke.","notes":[]},{"number":20,"text":"The sun will be turned into darkness, and the moon into blood, before the great and glorious day of the Lord comes.","notes":[]},{"number":21,"text":"It will be that whoever will call on the name of the Lord will be saved.’","notes":["Joel 2:28-32"]},{"number":22,"text":"“Men of Israel, hear these words! Jesus of Nazareth, a man approved by God to you by mighty works and wonders and signs which God did by him among you, even as you yourselves know,","notes":[]},{"number":23,"text":"him, being delivered up by the determined counsel and foreknowledge of God, you have taken by the hand of lawless men, crucified and killed;","notes":[]},{"number":24,"text":"whom God raised up, having freed him from the agony of death, because it was not possible that he should be held by it.","notes":[]},{"number":25,"text":"For David says concerning him, ‘I saw the Lord always before my face, for he is on my right hand, that I should not be moved.","notes":[]},{"number":26,"text":"Therefore my heart was glad, and my tongue rejoiced. Moreover my flesh also will dwell in hope,","notes":[]},{"number":27,"text":"because you will not leave my soul in Hades, neither will you allow your Holy One to see decay.","notes":["or, Hell"]},{"number":28,"text":"You made known to me the ways of life. You will make me full of gladness with your presence.’","notes":["Psalms 16:8-11"]},{"number":29,"text":"“Brothers, I may tell you freely of the patriarch David, that he both died and was buried, and his tomb is with us to this day.","notes":[]},{"number":30,"text":"Therefore, being a prophet, and knowing that God had sworn with an oath to him that of the fruit of his body, according to the flesh, he would raise up the Christ to sit on his throne,","notes":["“Christ” means “Anointed One”."]},{"number":31,"text":"he foreseeing this, spoke about the resurrection of the Christ, that his soul wasn’t left in Hades, and his flesh didn’t see decay.","notes":["or, Hell"]},{"number":32,"text":"This Jesus God raised up, to which we all are witnesses.","notes":[]},{"number":33,"text":"Being therefore exalted by the right hand of God, and having received from the Father the promise of the Holy Spirit, he has poured out this which you now see and hear.","notes":[]},{"number":34,"text":"For David didn’t ascend into the heavens, but he says himself, ‘The Lord said to my Lord, “Sit by my right hand","notes":[]},{"number":35,"text":"until I make your enemies a footstool for your feet.” ’","notes":["Psalms 110:1"]},{"number":36,"text":"“Let all the house of Israel therefore know certainly that God has made him both Lord and Christ, this Jesus whom you crucified.”","notes":[]},{"number":37,"text":"Now when they heard this, they were cut to the heart, and said to Peter and the rest of the apostles, “Brothers, what shall we do?”","notes":[]},{"number":38,"text":"Peter said to them, “Repent and be baptized, every one of you, in the name of Jesus Christ for the forgiveness of sins, and you will receive the gift of the Holy Spirit.","notes":[]},{"number":39,"text":"For the promise is to you and to your children, and to all who are far off, even as many as the Lord our God will call to himself.”","notes":[]},{"number":40,"text":"With many other words he testified and exhorted them, saying, “Save yourselves from this crooked generation!”","notes":[]},{"number":41,"text":"Then those who gladly received his word were baptized. There were added that day about three thousand souls.","notes":[]},{"number":42,"text":"They continued steadfastly in the apostles’ teaching and fellowship, in the breaking of bread, and prayer.","notes":[]},{"number":43,"text":"Fear came on every soul, and many wonders and signs were done through the apostles.","notes":[]},{"number":44,"text":"All who believed were together, and had all things in common.","notes":[]},{"number":45,"text":"They sold their possessions and goods, and distributed them to all, according as anyone had need.","notes":[]},{"number":46,"text":"Day by day, continuing steadfastly with one accord in the temple, and breaking bread at home, they took their food with gladness and singleness of heart,","notes":[]},{"number":47,"text":"praising God and having favor with all the people. The Lord added to the assembly day by day those who were being saved.","notes":[]}],"source":"https://ebible.org/engwebp/ACT02.htm"},"ACT-4":{"book":"Acts","chapter":4,"verses":[{"number":1,"text":"As they spoke to the people, the priests and the captain of the temple and the Sadducees came to them,","notes":[]},{"number":2,"text":"being upset because they taught the people and proclaimed in Jesus the resurrection from the dead.","notes":[]},{"number":3,"text":"They laid hands on them, and put them in custody until the next day, for it was now evening.","notes":[]},{"number":4,"text":"But many of those who heard the word believed, and the number of the men came to be about five thousand.","notes":[]},{"number":5,"text":"In the morning, their rulers, elders, and scribes were gathered together in Jerusalem.","notes":[]},{"number":6,"text":"Annas the high priest was there, with Caiaphas, John, Alexander, and as many as were relatives of the high priest.","notes":[]},{"number":7,"text":"When they had stood Peter and John in the middle of them, they inquired, “By what power, or in what name, have you done this?”","notes":[]},{"number":8,"text":"Then Peter, filled with the Holy Spirit, said to them, “You rulers of the people and elders of Israel,","notes":[]},{"number":9,"text":"if we are examined today concerning a good deed done to a crippled man, by what means this man has been healed,","notes":[]},{"number":10,"text":"may it be known to you all, and to all the people of Israel, that in the name of Jesus Christ of Nazareth, whom you crucified, whom God raised from the dead, this man stands here before you whole in him.","notes":[]},{"number":11,"text":"He is ‘the stone which was regarded as worthless by you, the builders, which has become the head of the corner.’","notes":["Psalms 118:22"]},{"number":12,"text":"There is salvation in no one else, for there is no other name under heaven that is given among men, by which we must be saved!”","notes":[]},{"number":13,"text":"Now when they saw the boldness of Peter and John, and had perceived that they were unlearned and ignorant men, they marveled. They recognized that they had been with Jesus.","notes":[]},{"number":14,"text":"Seeing the man who was healed standing with them, they could say nothing against it.","notes":[]},{"number":15,"text":"But when they had commanded them to go aside out of the council, they conferred among themselves,","notes":[]},{"number":16,"text":"saying, “What shall we do to these men? Because indeed a notable miracle has been done through them, as can be plainly seen by all who dwell in Jerusalem, and we can’t deny it.","notes":[]},{"number":17,"text":"But so that this spreads no further among the people, let’s threaten them, that from now on they don’t speak to anyone in this name.”","notes":[]},{"number":18,"text":"They called them, and commanded them not to speak at all nor teach in the name of Jesus.","notes":[]},{"number":19,"text":"But Peter and John answered them, “Whether it is right in the sight of God to listen to you rather than to God, judge for yourselves,","notes":[]},{"number":20,"text":"for we can’t help telling the things which we saw and heard.”","notes":[]},{"number":21,"text":"When they had further threatened them, they let them go, finding no way to punish them, because of the people; for everyone glorified God for that which was done.","notes":[]},{"number":22,"text":"For the man on whom this miracle of healing was performed was more than forty years old.","notes":[]},{"number":23,"text":"Being let go, they came to their own company and reported all that the chief priests and the elders had said to them.","notes":[]},{"number":24,"text":"When they heard it, they lifted up their voice to God with one accord and said, “O Lord, you are God, who made the sky, the earth, the sea, and all that is in them;","notes":[]},{"number":25,"text":"who by the mouth of your servant David, said, ‘Why do the nations rage, and the peoples plot a vain thing?","notes":[]},{"number":26,"text":"The kings of the earth take a stand, and the rulers plot together, against the Lord, and against his Christ.’","notes":["Christ (Greek) and Messiah (Hebrew) both mean Anointed One.","Psalms 2:1-2"]},{"number":27,"text":"“For truly, both Herod and Pontius Pilate, with the Gentiles and the people of Israel, were gathered together against your holy servant Jesus, whom you anointed,","notes":["nu adds “in this city,”"]},{"number":28,"text":"to do whatever your hand and your counsel foreordained to happen.","notes":[]},{"number":29,"text":"Now, Lord, look at their threats, and grant to your servants to speak your word with all boldness,","notes":[]},{"number":30,"text":"while you stretch out your hand to heal; and that signs and wonders may be done through the name of your holy Servant Jesus.”","notes":[]},{"number":31,"text":"When they had prayed, the place was shaken where they were gathered together. They were all filled with the Holy Spirit, and they spoke the word of God with boldness.","notes":[]},{"number":32,"text":"The multitude of those who believed were of one heart and soul. Not one of them claimed that anything of the things which he possessed was his own, but they had all things in common.","notes":[]},{"number":33,"text":"With great power, the apostles gave their testimony of the resurrection of the Lord Jesus. Great grace was on them all.","notes":[]},{"number":34,"text":"For neither was there among them any who lacked, for as many as were owners of lands or houses sold them, and brought the proceeds of the things that were sold,","notes":[]},{"number":35,"text":"and laid them at the apostles’ feet; and distribution was made to each, according as anyone had need.","notes":[]},{"number":36,"text":"Joses, who by the apostles was also called Barnabas (which is, being interpreted, Son of Encouragement), a Levite, a man of Cyprus by race,","notes":[]},{"number":37,"text":"having a field, sold it and brought the money and laid it at the apostles’ feet.","notes":[]}],"source":"https://ebible.org/engwebp/ACT04.htm"},"ACT-6":{"book":"Acts","chapter":6,"verses":[{"number":1,"text":"Now in those days, when the number of the disciples was multiplying, a complaint arose from the Hellenists against the Hebrews, because their widows were neglected in the daily service.","notes":["The Hellenists used Greek language and culture, even though they were also of Hebrew descent."]},{"number":2,"text":"The twelve summoned the multitude of the disciples and said, “It is not appropriate for us to forsake the word of God and serve tables.","notes":[]},{"number":3,"text":"Therefore, select from among you, brothers, seven men of good report, full of the Holy Spirit and of wisdom, whom we may appoint over this business.","notes":[]},{"number":4,"text":"But we will continue steadfastly in prayer and in the ministry of the word.”","notes":[]},{"number":5,"text":"These words pleased the whole multitude. They chose Stephen, a man full of faith and of the Holy Spirit, Philip, Prochorus, Nicanor, Timon, Parmenas, and Nicolaus, a proselyte of Antioch,","notes":[]},{"number":6,"text":"whom they set before the apostles. When they had prayed, they laid their hands on them.","notes":[]},{"number":7,"text":"The word of God increased and the number of the disciples greatly multiplied in Jerusalem. A great company of the priests were obedient to the faith.","notes":[]},{"number":8,"text":"Stephen, full of faith and power, performed great wonders and signs among the people.","notes":[]},{"number":9,"text":"But some of those who were of the synagogue called “The Libertines”, and of the Cyrenians, of the Alexandrians, and of those of Cilicia and Asia arose, disputing with Stephen.","notes":[]},{"number":10,"text":"They weren’t able to withstand the wisdom and the Spirit by which he spoke.","notes":[]},{"number":11,"text":"Then they secretly induced men to say, “We have heard him speak blasphemous words against Moses and God.”","notes":[]},{"number":12,"text":"They stirred up the people, the elders, and the scribes, and came against him and seized him, then brought him in to the council,","notes":[]},{"number":13,"text":"and set up false witnesses who said, “This man never stops speaking blasphemous words against this holy place and the law.","notes":[]},{"number":14,"text":"For we have heard him say that this Jesus of Nazareth will destroy this place, and will change the customs which Moses delivered to us.”","notes":[]},{"number":15,"text":"All who sat in the council, fastening their eyes on him, saw his face like it was the face of an angel.","notes":[]}],"source":"https://ebible.org/engwebp/ACT06.htm"},"ACT-8":{"book":"Acts","chapter":8,"verses":[{"number":1,"text":"Saul was consenting to his death. A great persecution arose against the assembly which was in Jerusalem in that day. They were all scattered abroad throughout the regions of Judea and Samaria, except for the apostles.","notes":[]},{"number":2,"text":"Devout men buried Stephen and lamented greatly over him.","notes":[]},{"number":3,"text":"But Saul ravaged the assembly, entering into every house and dragged both men and women off to prison.","notes":[]},{"number":4,"text":"Therefore those who were scattered abroad went around preaching the word.","notes":[]},{"number":5,"text":"Philip went down to the city of Samaria and proclaimed to them the Christ.","notes":[]},{"number":6,"text":"The multitudes listened with one accord to the things that were spoken by Philip when they heard and saw the signs which he did.","notes":[]},{"number":7,"text":"For unclean spirits came out of many of those who had them. They came out, crying with a loud voice. Many who had been paralyzed and lame were healed.","notes":[]},{"number":8,"text":"There was great joy in that city.","notes":[]},{"number":9,"text":"But there was a certain man, Simon by name, who used to practice sorcery in the city and amazed the people of Samaria, making himself out to be some great one,","notes":[]},{"number":10,"text":"to whom they all listened, from the least to the greatest, saying, “This man is that great power of God.”","notes":[]},{"number":11,"text":"They listened to him because for a long time he had amazed them with his sorceries.","notes":[]},{"number":12,"text":"But when they believed Philip preaching good news concerning God’s Kingdom and the name of Jesus Christ, they were baptized, both men and women.","notes":[]},{"number":13,"text":"Simon himself also believed. Being baptized, he continued with Philip. Seeing signs and great miracles occurring, he was amazed.","notes":[]},{"number":14,"text":"Now when the apostles who were at Jerusalem heard that Samaria had received the word of God, they sent Peter and John to them,","notes":[]},{"number":15,"text":"who, when they had come down, prayed for them, that they might receive the Holy Spirit;","notes":[]},{"number":16,"text":"for as yet he had fallen on none of them. They had only been baptized in the name of Christ Jesus.","notes":[]},{"number":17,"text":"Then they laid their hands on them, and they received the Holy Spirit.","notes":[]},{"number":18,"text":"Now when Simon saw that the Holy Spirit was given through the laying on of the apostles’ hands, he offered them money,","notes":[]},{"number":19,"text":"saying, “Give me also this power, that whomever I lay my hands on may receive the Holy Spirit.”","notes":[]},{"number":20,"text":"But Peter said to him, “May your silver perish with you, because you thought you could obtain the gift of God with money!","notes":[]},{"number":21,"text":"You have neither part nor lot in this matter, for your heart isn’t right before God.","notes":[]},{"number":22,"text":"Repent therefore of this, your wickedness, and ask God if perhaps the thought of your heart may be forgiven you.","notes":[]},{"number":23,"text":"For I see that you are in the poison of bitterness and in the bondage of iniquity.”","notes":[]},{"number":24,"text":"Simon answered, “Pray for me to the Lord, that none of the things which you have spoken happen to me.”","notes":[]},{"number":25,"text":"They therefore, when they had testified and spoken the word of the Lord, returned to Jerusalem, and preached the Good News to many villages of the Samaritans.","notes":[]},{"number":26,"text":"Then an angel of the Lord spoke to Philip, saying, “Arise, and go toward the south to the way that goes down from Jerusalem to Gaza. This is a desert.”","notes":[]},{"number":27,"text":"He arose and went; and behold, there was a man of Ethiopia, a eunuch of great authority under Candace, queen of the Ethiopians, who was over all her treasure, who had come to Jerusalem to worship.","notes":[]},{"number":28,"text":"He was returning and sitting in his chariot, and was reading the prophet Isaiah.","notes":[]},{"number":29,"text":"The Spirit said to Philip, “Go near, and join yourself to this chariot.”","notes":[]},{"number":30,"text":"Philip ran to him, and heard him reading Isaiah the prophet, and said, “Do you understand what you are reading?”","notes":[]},{"number":31,"text":"He said, “How can I, unless someone explains it to me?” He begged Philip to come up and sit with him.","notes":[]},{"number":32,"text":"Now the passage of the Scripture which he was reading was this, “He was led as a sheep to the slaughter. As a lamb before his shearer is silent, so he doesn’t open his mouth.","notes":[]},{"number":33,"text":"In his humiliation, his judgment was taken away. Who will declare His generation? For his life is taken from the earth.”","notes":["Isaiah 53:7,8"]},{"number":34,"text":"The eunuch answered Philip, “Who is the prophet talking about? About himself, or about someone else?”","notes":[]},{"number":35,"text":"Philip opened his mouth, and beginning from this Scripture, preached to him about Jesus.","notes":[]},{"number":36,"text":"As they went on the way, they came to some water; and the eunuch said, “Behold, here is water. What is keeping me from being baptized?”","notes":[]},{"number":37,"text":"","notes":["TR adds Philip said, “If you believe with all your heart, you may.” He answered, “I believe that Jesus Christ is the Son of God.”"]},{"number":38,"text":"He commanded the chariot to stand still, and they both went down into the water, both Philip and the eunuch, and he baptized him.","notes":[]},{"number":39,"text":"When they came up out of the water, the Spirit of the Lord caught Philip away, and the eunuch didn’t see him any more, for he went on his way rejoicing.","notes":[]},{"number":40,"text":"But Philip was found at Azotus. Passing through, he preached the Good News to all the cities until he came to Caesarea.","notes":[]}],"source":"https://ebible.org/engwebp/ACT08.htm"},"ACT-9":{"book":"Acts","chapter":9,"verses":[{"number":1,"text":"But Saul, still breathing threats and slaughter against the disciples of the Lord, went to the high priest","notes":[]},{"number":2,"text":"and asked for letters from him to the synagogues of Damascus, that if he found any who were of the Way, whether men or women, he might bring them bound to Jerusalem.","notes":[]},{"number":3,"text":"As he traveled, he got close to Damascus, and suddenly a light from the sky shone around him.","notes":[]},{"number":4,"text":"He fell on the earth, and heard a voice saying to him, “Saul, Saul, why do you persecute me?”","notes":[]},{"number":5,"text":"He said, “Who are you, Lord?” The Lord said, “I am Jesus, whom you are persecuting.","notes":["TR adds “It’s hard for you to kick against the cattle prods.”"]},{"number":6,"text":"But rise up and enter into the city, then you will be told what you must do.”","notes":["TR omits “But”"]},{"number":7,"text":"The men who traveled with him stood speechless, hearing the sound, but seeing no one.","notes":[]},{"number":8,"text":"Saul arose from the ground, and when his eyes were opened, he saw no one. They led him by the hand and brought him into Damascus.","notes":[]},{"number":9,"text":"He was without sight for three days, and neither ate nor drank.","notes":[]},{"number":10,"text":"Now there was a certain disciple at Damascus named Ananias. The Lord said to him in a vision, “Ananias!” He said, “Behold, it’s me, Lord.”","notes":[]},{"number":11,"text":"The Lord said to him, “Arise and go to the street which is called Straight, and inquire in the house of Judah for one named Saul, a man of Tarsus. For behold, he is praying,","notes":["or, Judas"]},{"number":12,"text":"and in a vision he has seen a man named Ananias coming in and laying his hands on him, that he might receive his sight.”","notes":[]},{"number":13,"text":"But Ananias answered, “Lord, I have heard from many about this man, how much evil he did to your saints at Jerusalem.","notes":[]},{"number":14,"text":"Here he has authority from the chief priests to bind all who call on your name.”","notes":[]},{"number":15,"text":"But the Lord said to him, “Go your way, for he is my chosen vessel to bear my name before the nations and kings, and the children of Israel.","notes":[]},{"number":16,"text":"For I will show him how many things he must suffer for my name’s sake.”","notes":[]},{"number":17,"text":"Ananias departed and entered into the house. Laying his hands on him, he said, “Brother Saul, the Lord, who appeared to you on the road by which you came, has sent me that you may receive your sight and be filled with the Holy Spirit.”","notes":[]},{"number":18,"text":"Immediately something like scales fell from his eyes, and he received his sight. He arose and was baptized.","notes":[]},{"number":19,"text":"He took food and was strengthened. Saul stayed several days with the disciples who were at Damascus.","notes":[]},{"number":20,"text":"Immediately in the synagogues he proclaimed the Christ, that he is the Son of God.","notes":[]},{"number":21,"text":"All who heard him were amazed, and said, “Isn’t this he who in Jerusalem made havoc of those who called on this name? And he had come here intending to bring them bound before the chief priests!”","notes":[]},{"number":22,"text":"But Saul increased more in strength, and confounded the Jews who lived at Damascus, proving that this is the Christ.","notes":[]},{"number":23,"text":"When many days were fulfilled, the Jews conspired together to kill him,","notes":[]},{"number":24,"text":"but their plot became known to Saul. They watched the gates both day and night that they might kill him,","notes":[]},{"number":25,"text":"but his disciples took him by night and let him down through the wall, lowering him in a basket.","notes":[]},{"number":26,"text":"When Saul had come to Jerusalem, he tried to join himself to the disciples; but they were all afraid of him, not believing that he was a disciple.","notes":[]},{"number":27,"text":"But Barnabas took him and brought him to the apostles, and declared to them how he had seen the Lord on the way, and that he had spoken to him, and how at Damascus he had preached boldly in the name of Jesus.","notes":[]},{"number":28,"text":"He was with them entering into Jerusalem,","notes":["TR and NU add “and going out”"]},{"number":29,"text":"preaching boldly in the name of the Lord Jesus. He spoke and disputed against the Hellenists, but they were seeking to kill him.","notes":["TR and NU omit “Jesus” and reverse the order of verses 28 & 29.","The Hellenists were Hebrews who used Greek language and culture."]},{"number":30,"text":"When the brothers knew it, they brought him down to Caesarea and sent him off to Tarsus.","notes":["The word for “brothers” here and where the context allows may also be correctly translated “brothers and sisters” or “siblings.”"]},{"number":31,"text":"So the assemblies throughout all Judea, Galilee, and Samaria had peace and were built up. They were multiplied, walking in the fear of the Lord and in the comfort of the Holy Spirit.","notes":[]},{"number":32,"text":"As Peter went throughout all those parts, he came down also to the saints who lived at Lydda.","notes":[]},{"number":33,"text":"There he found a certain man named Aeneas, who had been bedridden for eight years because he was paralyzed.","notes":[]},{"number":34,"text":"Peter said to him, “Aeneas, Jesus Christ heals you. Get up and make your bed!” Immediately he arose.","notes":[]},{"number":35,"text":"All who lived at Lydda and in Sharon saw him, and they turned to the Lord.","notes":[]},{"number":36,"text":"Now there was at Joppa a certain disciple named Tabitha, which when translated means Dorcas. This woman was full of good works and acts of mercy which she did.","notes":["“Dorcas” is Greek for “Gazelle.”"]},{"number":37,"text":"In those days, she became sick and died. When they had washed her, they laid her in an upper room.","notes":[]},{"number":38,"text":"As Lydda was near Joppa, the disciples, hearing that Peter was there, sent two men to him, imploring him not to delay in coming to them.","notes":["Reading from NU, TR; MT omits “two men”"]},{"number":39,"text":"Peter got up and went with them. When he had come, they brought him into the upper room. All the widows stood by him weeping, and showing the tunics and other garments which Dorcas had made while she was with them.","notes":[]},{"number":40,"text":"Peter sent them all out, and knelt down and prayed. Turning to the body, he said, “Tabitha, get up!” She opened her eyes, and when she saw Peter, she sat up.","notes":[]},{"number":41,"text":"He gave her his hand and raised her up. Calling the saints and widows, he presented her alive.","notes":[]},{"number":42,"text":"This became known throughout all Joppa, and many believed in the Lord.","notes":[]},{"number":43,"text":"He stayed many days in Joppa with a tanner named Simon.","notes":[]}],"source":"https://ebible.org/engwebp/ACT09.htm"},"AMO-5":{"book":"Amos","chapter":5,"verses":[{"number":1,"text":"Listen to this word which I take up for a lamentation over you, O house of Israel:","notes":[]},{"number":2,"text":"“The virgin of Israel has fallen; She shall rise no more. She is cast down on her land; there is no one to raise her up.”","notes":[]},{"number":3,"text":"For the Lord GOD says: “The city that went out a thousand shall have a hundred left, and that which went out one hundred shall have ten left to the house of Israel.”","notes":[]},{"number":4,"text":"For the LORD says to the house of Israel: “Seek me, and you will live;","notes":[]},{"number":5,"text":"but don’t seek Bethel, nor enter into Gilgal, and don’t pass to Beersheba; for Gilgal shall surely go into captivity, and Bethel shall come to nothing.","notes":[]},{"number":6,"text":"Seek the LORD, and you will live, lest he break out like fire in the house of Joseph, and it devour, and there be no one to quench it in Bethel.","notes":[]},{"number":7,"text":"You who turn justice to wormwood, and cast down righteousness to the earth!","notes":[]},{"number":8,"text":"Seek him who made the Pleiades and Orion, and turns the shadow of death into the morning, and makes the day dark with night; who calls for the waters of the sea, and pours them out on the surface of the earth, the LORD is his name,","notes":[]},{"number":9,"text":"who brings sudden destruction on the strong, so that destruction comes on the fortress.","notes":[]},{"number":10,"text":"They hate him who reproves in the gate, and they abhor him who speaks blamelessly.","notes":[]},{"number":11,"text":"Therefore, because you trample on the poor and take taxes from him of wheat, you have built houses of cut stone, but you will not dwell in them. You have planted pleasant vineyards, but you shall not drink their wine.","notes":[]},{"number":12,"text":"For I know how many are your offenses, and how great are your sins— you who afflict the just, who take a bribe, and who turn away the needy in the courts.","notes":[]},{"number":13,"text":"Therefore a prudent person keeps silent in such a time, for it is an evil time.","notes":[]},{"number":14,"text":"Seek good, and not evil, that you may live; and so the LORD, the God of Armies, will be with you, as you say.","notes":[]},{"number":15,"text":"Hate evil, love good, and establish justice in the courts. It may be that the LORD, the God of Armies, will be gracious to the remnant of Joseph.”","notes":[]},{"number":16,"text":"Therefore the LORD, the God of Armies, the Lord, says: “Wailing will be in all the wide ways. They will say in all the streets, ‘Alas! Alas!’ They will call the farmer to mourning, and those who are skillful in lamentation to wailing.","notes":[]},{"number":17,"text":"In all vineyards there will be wailing, for I will pass through the middle of you,” says the LORD.","notes":[]},{"number":18,"text":"“Woe to you who desire the day of the LORD! Why do you long for the day of the LORD? It is darkness, and not light.","notes":[]},{"number":19,"text":"As if a man fled from a lion, and a bear met him; or he went into the house and leaned his hand on the wall, and a snake bit him.","notes":[]},{"number":20,"text":"Won’t the day of the LORD be darkness, and not light? Even very dark, and no brightness in it?","notes":[]},{"number":21,"text":"I hate, I despise your feasts, and I can’t stand your solemn assemblies.","notes":[]},{"number":22,"text":"Yes, though you offer me your burnt offerings and meal offerings, I will not accept them; neither will I regard the peace offerings of your fat animals.","notes":[]},{"number":23,"text":"Take away from me the noise of your songs! I will not listen to the music of your harps.","notes":[]},{"number":24,"text":"But let justice roll on like rivers, and righteousness like a mighty stream.","notes":[]},{"number":25,"text":"“Did you bring to me sacrifices and offerings in the wilderness forty years, house of Israel?","notes":[]},{"number":26,"text":"You also carried the tent of your king and the shrine of your images, the star of your god, which you made for yourselves.","notes":[]},{"number":27,"text":"Therefore I will cause you to go into captivity beyond Damascus,” says the LORD, whose name is the God of Armies.","notes":[]}],"source":"https://ebible.org/engwebp/AMO05.htm"},"COL-4":{"book":"Colossians","chapter":4,"verses":[{"number":1,"text":"Masters, give to your servants that which is just and equal, knowing that you also have a Master in heaven.","notes":[]},{"number":2,"text":"Continue steadfastly in prayer, watching in it with thanksgiving,","notes":[]},{"number":3,"text":"praying together for us also, that God may open to us a door for the word, to speak the mystery of Christ, for which I am also in bonds,","notes":[]},{"number":4,"text":"that I may reveal it as I ought to speak.","notes":[]},{"number":5,"text":"Walk in wisdom toward those who are outside, redeeming the time.","notes":[]},{"number":6,"text":"Let your speech always be with grace, seasoned with salt, that you may know how you ought to answer each one.","notes":[]},{"number":7,"text":"All my affairs will be made known to you by Tychicus, the beloved brother, faithful servant, and fellow bondservant in the Lord.","notes":[]},{"number":8,"text":"I am sending him to you for this very purpose, that he may know your circumstances and comfort your hearts,","notes":[]},{"number":9,"text":"together with Onesimus, the faithful and beloved brother, who is one of you. They will make known to you everything that is going on here.","notes":[]},{"number":10,"text":"Aristarchus, my fellow prisoner, greets you, and Mark the cousin of Barnabas (concerning whom you received instructions, “if he comes to you, receive him”),","notes":[]},{"number":11,"text":"and Jesus who is called Justus. These are my only fellow workers for God’s Kingdom who are of the circumcision, men who have been a comfort to me.","notes":[]},{"number":12,"text":"Epaphras, who is one of you, a servant of Christ, salutes you, always striving for you in his prayers, that you may stand perfect and complete in all the will of God.","notes":[]},{"number":13,"text":"For I testify about him that he has great zeal for you, and for those in Laodicea, and for those in Hierapolis.","notes":[]},{"number":14,"text":"Luke the beloved physician and Demas greet you.","notes":[]},{"number":15,"text":"Greet the brothers who are in Laodicea, with Nymphas and the assembly that is in his house.","notes":[]},{"number":16,"text":"When this letter has been read among you, cause it to be read also in the assembly of the Laodiceans, and that you also read the letter from Laodicea.","notes":[]},{"number":17,"text":"Tell Archippus, “Take heed to the ministry which you have received in the Lord, that you fulfill it.”","notes":[]},{"number":18,"text":"I, Paul, write this greeting with my own hand. Remember my chains. Grace be with you. Amen.","notes":[]}],"source":"https://ebible.org/engwebp/COL04.htm"},"DEU-17":{"book":"Deuteronomy","chapter":17,"verses":[{"number":1,"text":"You shall not sacrifice to the LORD your God an ox or a sheep in which is a defect or anything evil; for that is an abomination to the LORD your God.","notes":[]},{"number":2,"text":"If there is found among you, within any of your gates which the LORD your God gives you, a man or woman who does that which is evil in the LORD your God’s sight in transgressing his covenant,","notes":[]},{"number":3,"text":"and has gone and served other gods and worshiped them, or the sun, or the moon, or any of the stars of the sky, which I have not commanded,","notes":[]},{"number":4,"text":"and you are told, and you have heard of it, then you shall inquire diligently. Behold, if it is true, and the thing certain, that such abomination is done in Israel,","notes":[]},{"number":5,"text":"then you shall bring out that man or that woman who has done this evil thing to your gates, even that same man or woman; and you shall stone them to death with stones.","notes":[]},{"number":6,"text":"At the mouth of two witnesses, or three witnesses, he who is to die shall be put to death. At the mouth of one witness he shall not be put to death.","notes":[]},{"number":7,"text":"The hands of the witnesses shall be first on him to put him to death, and afterward the hands of all the people. So you shall remove the evil from among you.","notes":[]},{"number":8,"text":"If there arises a matter too hard for you in judgment, between blood and blood, between plea and plea, and between stroke and stroke, being matters of controversy within your gates, then you shall arise, and go up to the place which the LORD your God chooses.","notes":[]},{"number":9,"text":"You shall come to the priests who are Levites and to the judge who shall be in those days. You shall inquire, and they shall give you the verdict.","notes":[]},{"number":10,"text":"You shall do according to the decisions of the verdict which they shall give you from that place which the LORD chooses. You shall observe to do according to all that they shall teach you.","notes":[]},{"number":11,"text":"According to the decisions of the law which they shall teach you, and according to the judgment which they shall tell you, you shall do. You shall not turn away from the sentence which they announce to you, to the right hand, nor to the left.","notes":[]},{"number":12,"text":"The man who does presumptuously in not listening to the priest who stands to minister there before the LORD your God, or to the judge, even that man shall die. You shall put away the evil from Israel.","notes":[]},{"number":13,"text":"All the people shall hear and fear, and do no more presumptuously.","notes":[]},{"number":14,"text":"When you have come to the land which the LORD your God gives you, and possess it and dwell in it, and say, “I will set a king over me, like all the nations that are around me,”","notes":[]},{"number":15,"text":"you shall surely set him whom the LORD your God chooses as king over yourselves. You shall set as king over you one from among your brothers. You may not put a foreigner over you, who is not your brother.","notes":[]},{"number":16,"text":"Only he shall not multiply horses to himself, nor cause the people to return to Egypt, to the end that he may multiply horses; because the LORD has said to you, “You shall not go back that way again.”","notes":[]},{"number":17,"text":"He shall not multiply wives to himself, that his heart not turn away. He shall not greatly multiply to himself silver and gold.","notes":[]},{"number":18,"text":"It shall be, when he sits on the throne of his kingdom, that he shall write himself a copy of this law in a book, out of that which is before the Levitical priests.","notes":[]},{"number":19,"text":"It shall be with him, and he shall read from it all the days of his life, that he may learn to fear the LORD his God, to keep all the words of this law and these statutes, to do them;","notes":[]},{"number":20,"text":"that his heart not be lifted up above his brothers, and that he not turn away from the commandment to the right hand, or to the left, to the end that he may prolong his days in his kingdom, he and his children, in the middle of Israel.","notes":[]}],"source":"https://ebible.org/engwebp/DEU17.htm"},"DEU-6":{"book":"Deuteronomy","chapter":6,"verses":[{"number":1,"text":"Now these are the commandments, the statutes, and the ordinances, which the LORD your God commanded to teach you, that you might do them in the land that you go over to possess;","notes":[]},{"number":2,"text":"that you might fear the LORD your God, to keep all his statutes and his commandments, which I command you—you, your son, and your son’s son, all the days of your life; and that your days may be prolonged.","notes":[]},{"number":3,"text":"Hear therefore, Israel, and observe to do it, that it may be well with you, and that you may increase mightily, as the LORD, the God of your fathers, has promised to you, in a land flowing with milk and honey.","notes":[]},{"number":4,"text":"Hear, Israel: The LORD is our God. The LORD is one.","notes":[]},{"number":5,"text":"You shall love the LORD your God with all your heart, with all your soul, and with all your might.","notes":[]},{"number":6,"text":"These words, which I command you today, shall be on your heart;","notes":[]},{"number":7,"text":"and you shall teach them diligently to your children, and shall talk of them when you sit in your house, and when you walk by the way, and when you lie down, and when you rise up.","notes":[]},{"number":8,"text":"You shall bind them for a sign on your hand, and they shall be for frontlets between your eyes.","notes":[]},{"number":9,"text":"You shall write them on the door posts of your house and on your gates.","notes":[]},{"number":10,"text":"It shall be, when the LORD your God brings you into the land which he swore to your fathers, to Abraham, to Isaac, and to Jacob, to give you, great and goodly cities which you didn’t build,","notes":[]},{"number":11,"text":"and houses full of all good things which you didn’t fill, and cisterns dug out which you didn’t dig, vineyards and olive trees which you didn’t plant, and you shall eat and be full;","notes":[]},{"number":12,"text":"then beware lest you forget the LORD, who brought you out of the land of Egypt, out of the house of bondage.","notes":[]},{"number":13,"text":"You shall fear the LORD your God; and you shall serve him, and shall swear by his name.","notes":[]},{"number":14,"text":"You shall not go after other gods, of the gods of the peoples who are around you,","notes":[]},{"number":15,"text":"for the LORD your God among you is a jealous God, lest the anger of the LORD your God be kindled against you, and he destroy you from off the face of the earth.","notes":[]},{"number":16,"text":"You shall not tempt the LORD your God, as you tempted him in Massah.","notes":[]},{"number":17,"text":"You shall diligently keep the commandments of the LORD your God, and his testimonies, and his statutes, which he has commanded you.","notes":[]},{"number":18,"text":"You shall do that which is right and good in the LORD’s sight, that it may be well with you and that you may go in and possess the good land which the LORD swore to your fathers,","notes":[]},{"number":19,"text":"to thrust out all your enemies from before you, as the LORD has spoken.","notes":[]},{"number":20,"text":"When your son asks you in time to come, saying, “What do the testimonies, the statutes, and the ordinances, which the LORD our God has commanded you mean?”","notes":[]},{"number":21,"text":"then you shall tell your son, “We were Pharaoh’s slaves in Egypt. The LORD brought us out of Egypt with a mighty hand;","notes":[]},{"number":22,"text":"and the LORD showed great and awesome signs and wonders on Egypt, on Pharaoh, and on all his house, before our eyes;","notes":[]},{"number":23,"text":"and he brought us out from there, that he might bring us in, to give us the land which he swore to our fathers.","notes":[]},{"number":24,"text":"The LORD commanded us to do all these statutes, to fear the LORD our God, for our good always, that he might preserve us alive, as we are today.","notes":[]},{"number":25,"text":"It shall be righteousness to us, if we observe to do all these commandments before the LORD our God, as he has commanded us.”","notes":[]}],"source":"https://ebible.org/engwebp/DEU06.htm"},"ECC-7":{"book":"Ecclesiastes","chapter":7,"verses":[{"number":1,"text":"A good name is better than fine perfume; and the day of death better than the day of one’s birth.","notes":[]},{"number":2,"text":"It is better to go to the house of mourning than to go to the house of feasting; for that is the end of all men, and the living should take this to heart.","notes":[]},{"number":3,"text":"Sorrow is better than laughter; for by the sadness of the face the heart is made good.","notes":[]},{"number":4,"text":"The heart of the wise is in the house of mourning; but the heart of fools is in the house of mirth.","notes":[]},{"number":5,"text":"It is better to hear the rebuke of the wise than for a man to hear the song of fools.","notes":[]},{"number":6,"text":"For as the crackling of thorns under a pot, so is the laughter of the fool. This also is vanity.","notes":[]},{"number":7,"text":"Surely extortion makes the wise man foolish; and a bribe destroys the understanding.","notes":[]},{"number":8,"text":"Better is the end of a thing than its beginning. The patient in spirit is better than the proud in spirit.","notes":[]},{"number":9,"text":"Don’t be hasty in your spirit to be angry, for anger rests in the bosom of fools.","notes":[]},{"number":10,"text":"Don’t say, “Why were the former days better than these?” For you do not ask wisely about this.","notes":[]},{"number":11,"text":"Wisdom is as good as an inheritance. Yes, it is more excellent for those who see the sun.","notes":[]},{"number":12,"text":"For wisdom is a defense, even as money is a defense; but the excellency of knowledge is that wisdom preserves the life of him who has it.","notes":[]},{"number":13,"text":"Consider the work of God, for who can make that straight which he has made crooked?","notes":[]},{"number":14,"text":"In the day of prosperity be joyful, and in the day of adversity consider; yes, God has made the one side by side with the other, to the end that man should not find out anything after him.","notes":[]},{"number":15,"text":"All this I have seen in my days of vanity: there is a righteous man who perishes in his righteousness, and there is a wicked man who lives long in his evildoing.","notes":[]},{"number":16,"text":"Don’t be overly righteous, neither make yourself overly wise. Why should you destroy yourself?","notes":[]},{"number":17,"text":"Don’t be too wicked, neither be foolish. Why should you die before your time?","notes":[]},{"number":18,"text":"It is good that you should take hold of this. Yes, also don’t withdraw your hand from that; for he who fears God will come out of them all.","notes":[]},{"number":19,"text":"Wisdom is a strength to the wise man more than ten rulers who are in a city.","notes":[]},{"number":20,"text":"Surely there is not a righteous man on earth who does good and doesn’t sin.","notes":[]},{"number":21,"text":"Also don’t take heed to all words that are spoken, lest you hear your servant curse you;","notes":[]},{"number":22,"text":"for often your own heart knows that you yourself have likewise cursed others.","notes":[]},{"number":23,"text":"All this I have proved in wisdom. I said, “I will be wise;” but it was far from me.","notes":[]},{"number":24,"text":"That which is, is far off and exceedingly deep. Who can find it out?","notes":[]},{"number":25,"text":"I turned around, and my heart sought to know and to search out, and to seek wisdom and the scheme of things, and to know that wickedness is stupidity, and that foolishness is madness.","notes":[]},{"number":26,"text":"I find more bitter than death the woman whose heart is snares and traps, whose hands are chains. Whoever pleases God shall escape from her; but the sinner will be ensnared by her.","notes":[]},{"number":27,"text":"“Behold, I have found this,” says the Preacher, “to one another, to find an explanation","notes":[]},{"number":28,"text":"which my soul still seeks, but I have not found. I have found one man among a thousand, but I have not found a woman among all those.","notes":[]},{"number":29,"text":"Behold, I have only found this: that God made mankind upright; but they search for many inventions.”","notes":[]}],"source":"https://ebible.org/engwebp/ECC07.htm"},"EPH-4":{"book":"Ephesians","chapter":4,"verses":[{"number":1,"text":"I therefore, the prisoner in the Lord, beg you to walk worthily of the calling with which you were called,","notes":[]},{"number":2,"text":"with all lowliness and humility, with patience, bearing with one another in love,","notes":[]},{"number":3,"text":"being eager to keep the unity of the Spirit in the bond of peace.","notes":[]},{"number":4,"text":"There is one body and one Spirit, even as you also were called in one hope of your calling,","notes":[]},{"number":5,"text":"one Lord, one faith, one baptism,","notes":[]},{"number":6,"text":"one God and Father of all, who is over all and through all and in us all.","notes":[]},{"number":7,"text":"But to each one of us, the grace was given according to the measure of the gift of Christ.","notes":[]},{"number":8,"text":"Therefore he says, “When he ascended on high, he led captivity captive, and gave gifts to people.”","notes":["Psalms 68:18"]},{"number":9,"text":"Now this, “He ascended”, what is it but that he also first descended into the lower parts of the earth?","notes":[]},{"number":10,"text":"He who descended is the one who also ascended far above all the heavens, that he might fill all things.","notes":[]},{"number":11,"text":"He gave some to be apostles; and some, prophets; and some, evangelists; and some, shepherds and teachers;","notes":["or, pastors"]},{"number":12,"text":"for the perfecting of the saints, to the work of serving, to the building up of the body of Christ,","notes":[]},{"number":13,"text":"until we all attain to the unity of the faith and of the knowledge of the Son of God, to a full grown man, to the measure of the stature of the fullness of Christ,","notes":[]},{"number":14,"text":"that we may no longer be children, tossed back and forth and carried about with every wind of doctrine, by the trickery of men, in craftiness, after the wiles of error;","notes":[]},{"number":15,"text":"but speaking truth in love, we may grow up in all things into him who is the head, Christ,","notes":[]},{"number":16,"text":"from whom all the body, being fitted and knit together through that which every joint supplies, according to the working in measure of each individual part, makes the body increase to the building up of itself in love.","notes":[]},{"number":17,"text":"This I say therefore, and testify in the Lord, that you no longer walk as the rest of the Gentiles also walk, in the futility of their mind,","notes":[]},{"number":18,"text":"being darkened in their understanding, alienated from the life of God because of the ignorance that is in them, because of the hardening of their hearts.","notes":[]},{"number":19,"text":"They, having become callous, gave themselves up to lust, to work all uncleanness with greediness.","notes":[]},{"number":20,"text":"But you didn’t learn Christ that way,","notes":[]},{"number":21,"text":"if indeed you heard him and were taught in him, even as truth is in Jesus:","notes":[]},{"number":22,"text":"that you put away, as concerning your former way of life, the old man that grows corrupt after the lusts of deceit,","notes":[]},{"number":23,"text":"and that you be renewed in the spirit of your mind,","notes":[]},{"number":24,"text":"and put on the new man, who in the likeness of God has been created in righteousness and holiness of truth.","notes":[]},{"number":25,"text":"Therefore, putting away falsehood, speak truth each one with his neighbor, for we are members of one another.","notes":[]},{"number":26,"text":"“Be angry, and don’t sin.” Don’t let the sun go down on your wrath,","notes":["Psalms 4:4"]},{"number":27,"text":"and don’t give place to the devil.","notes":["or, opportunity"]},{"number":28,"text":"Let him who stole steal no more; but rather let him labor, producing with his hands something that is good, that he may have something to give to him who has need.","notes":[]},{"number":29,"text":"Let no corrupt speech proceed out of your mouth, but only what is good for building others up as the need may be, that it may give grace to those who hear.","notes":[]},{"number":30,"text":"Don’t grieve the Holy Spirit of God, in whom you were sealed for the day of redemption.","notes":[]},{"number":31,"text":"Let all bitterness, wrath, anger, outcry, and slander be put away from you, with all malice.","notes":[]},{"number":32,"text":"And be kind to one another, tender hearted, forgiving each other, just as God also in Christ forgave you.","notes":[]}],"source":"https://ebible.org/engwebp/EPH04.htm"},"EXO-18":{"book":"Exodus","chapter":18,"verses":[{"number":1,"text":"Now Jethro, the priest of Midian, Moses’ father-in-law, heard of all that God had done for Moses and for Israel his people, how the LORD had brought Israel out of Egypt.","notes":[]},{"number":2,"text":"Jethro, Moses’ father-in-law, received Zipporah, Moses’ wife, after he had sent her away,","notes":[]},{"number":3,"text":"and her two sons. The name of one son was Gershom, for Moses said, “I have lived as a foreigner in a foreign land”.","notes":["“Gershom” sounds like the Hebrew for “an alien there”."]},{"number":4,"text":"The name of the other was Eliezer, for he said, “My father’s God was my help and delivered me from Pharaoh’s sword.”","notes":["Eliezer means “God is my helper”."]},{"number":5,"text":"Jethro, Moses’ father-in-law, came with Moses’ sons and his wife to Moses into the wilderness where he was encamped, at the Mountain of God.","notes":[]},{"number":6,"text":"He said to Moses, “I, your father-in-law Jethro, have come to you with your wife, and her two sons with her.”","notes":[]},{"number":7,"text":"Moses went out to meet his father-in-law, and bowed and kissed him. They asked each other of their welfare, and they came into the tent.","notes":[]},{"number":8,"text":"Moses told his father-in-law all that the LORD had done to Pharaoh and to the Egyptians for Israel’s sake, all the hardships that had come on them on the way, and how the LORD delivered them.","notes":[]},{"number":9,"text":"Jethro rejoiced for all the goodness which the LORD had done to Israel, in that he had delivered them out of the hand of the Egyptians.","notes":[]},{"number":10,"text":"Jethro said, “Blessed be the LORD, who has delivered you out of the hand of the Egyptians, and out of the hand of Pharaoh; who has delivered the people from under the hand of the Egyptians.","notes":[]},{"number":11,"text":"Now I know that the LORD is greater than all gods because of the way that they treated people arrogantly.”","notes":[]},{"number":12,"text":"Jethro, Moses’ father-in-law, took a burnt offering and sacrifices for God. Aaron came with all the elders of Israel, to eat bread with Moses’ father-in-law before God.","notes":[]},{"number":13,"text":"On the next day, Moses sat to judge the people, and the people stood around Moses from the morning to the evening.","notes":[]},{"number":14,"text":"When Moses’ father-in-law saw all that he did to the people, he said, “What is this thing that you do for the people? Why do you sit alone, and all the people stand around you from morning to evening?”","notes":[]},{"number":15,"text":"Moses said to his father-in-law, “Because the people come to me to inquire of God.","notes":[]},{"number":16,"text":"When they have a matter, they come to me, and I judge between a man and his neighbor, and I make them know the statutes of God, and his laws.”","notes":[]},{"number":17,"text":"Moses’ father-in-law said to him, “The thing that you do is not good.","notes":[]},{"number":18,"text":"You will surely wear away, both you, and this people that is with you; for the thing is too heavy for you. You are not able to perform it yourself alone.","notes":[]},{"number":19,"text":"Listen now to my voice. I will give you counsel, and God be with you. You represent the people before God, and bring the causes to God.","notes":[]},{"number":20,"text":"You shall teach them the statutes and the laws, and shall show them the way in which they must walk, and the work that they must do.","notes":[]},{"number":21,"text":"Moreover you shall provide out of all the people able men which fear God: men of truth, hating unjust gain; and place such over them, to be rulers of thousands, rulers of hundreds, rulers of fifties, and rulers of tens.","notes":[]},{"number":22,"text":"Let them judge the people at all times. It shall be that every great matter they shall bring to you, but every small matter they shall judge themselves. So shall it be easier for you, and they shall share the load with you.","notes":[]},{"number":23,"text":"If you will do this thing, and God commands you so, then you will be able to endure, and all these people also will go to their place in peace.”","notes":[]},{"number":24,"text":"So Moses listened to the voice of his father-in-law, and did all that he had said.","notes":[]},{"number":25,"text":"Moses chose able men out of all Israel, and made them heads over the people, rulers of thousands, rulers of hundreds, rulers of fifties, and rulers of tens.","notes":[]},{"number":26,"text":"They judged the people at all times. They brought the hard cases to Moses, but every small matter they judged themselves.","notes":[]},{"number":27,"text":"Moses let his father-in-law depart, and he went his way into his own land.","notes":[]}],"source":"https://ebible.org/engwebp/EXO18.htm"},"EZR-7":{"book":"Ezra","chapter":7,"verses":[{"number":1,"text":"Now after these things, in the reign of Artaxerxes king of Persia, Ezra the son of Seraiah, the son of Azariah, the son of Hilkiah,","notes":[]},{"number":2,"text":"the son of Shallum, the son of Zadok, the son of Ahitub,","notes":[]},{"number":3,"text":"the son of Amariah, the son of Azariah, the son of Meraioth,","notes":[]},{"number":4,"text":"the son of Zerahiah, the son of Uzzi, the son of Bukki,","notes":[]},{"number":5,"text":"the son of Abishua, the son of Phinehas, the son of Eleazar, the son of Aaron the chief priest—","notes":[]},{"number":6,"text":"this Ezra went up from Babylon. He was a skilled scribe in the law of Moses, which the LORD, the God of Israel, had given; and the king granted him all his request, according to the LORD his God’s hand on him.","notes":[]},{"number":7,"text":"Some of the children of Israel, including some of the priests, the Levites, the singers, the gatekeepers, and the temple servants went up to Jerusalem in the seventh year of Artaxerxes the king.","notes":[]},{"number":8,"text":"He came to Jerusalem in the fifth month, which was in the seventh year of the king.","notes":[]},{"number":9,"text":"For on the first day of the first month he began to go up from Babylon; and on the first day of the fifth month he came to Jerusalem, according to the good hand of his God on him.","notes":[]},{"number":10,"text":"For Ezra had set his heart to seek the LORD’s law, and to do it, and to teach statutes and ordinances in Israel.","notes":[]},{"number":11,"text":"Now this is the copy of the letter that King Artaxerxes gave to Ezra the priest, the scribe, even the scribe of the words of the LORD’s commandments, and of his statutes to Israel:","notes":[]},{"number":12,"text":"Artaxerxes, king of kings, To Ezra the priest, the scribe of the law of the perfect God of heaven. Now","notes":[]},{"number":13,"text":"I make a decree that all those of the people of Israel and their priests and the Levites in my realm, who intend of their own free will to go to Jerusalem, go with you.","notes":[]},{"number":14,"text":"Because you are sent by the king and his seven counselors to inquire concerning Judah and Jerusalem, according to the law of your God which is in your hand,","notes":[]},{"number":15,"text":"and to carry the silver and gold, which the king and his counselors have freely offered to the God of Israel, whose habitation is in Jerusalem,","notes":[]},{"number":16,"text":"and all the silver and gold that you will find in all the province of Babylon, with the free will offering of the people and of the priests, offering willingly for the house of their God which is in Jerusalem.","notes":[]},{"number":17,"text":"Therefore you shall with all diligence buy with this money bulls, rams, and lambs with their meal offerings and their drink offerings, and shall offer them on the altar of the house of your God which is in Jerusalem.","notes":[]},{"number":18,"text":"Whatever seems good to you and to your brothers to do with the rest of the silver and the gold, do that according to the will of your God.","notes":[]},{"number":19,"text":"The vessels that are given to you for the service of the house of your God, deliver before the God of Jerusalem.","notes":[]},{"number":20,"text":"Whatever more will be needed for the house of your God, which you may have occasion to give, give it out of the king’s treasure house.","notes":[]},{"number":21,"text":"I, even I, Artaxerxes the king, make a decree to all the treasurers who are beyond the River, that whatever Ezra the priest, the scribe of the law of the God of heaven, requires of you, it shall be done with all diligence,","notes":[]},{"number":22,"text":"up to one hundred talents of silver, and to one hundred cors of wheat, and to one hundred baths of wine, and to one hundred baths of oil, and salt without prescribing how much.","notes":["A talent is about 30 kilograms or 66 pounds or 965 Troy ounces","1 cor is the same as a homer, or about 55.9 U. S. gallons (liquid) or 211 liters or 6 bushels.","1 bath is one tenth of a cor, or about 5.6 U. S. gallons or 21 liters or 2.4 pecks. 100 baths would be about 2,100 liters."]},{"number":23,"text":"Whatever is commanded by the God of heaven, let it be done exactly for the house of the God of heaven; for why should there be wrath against the realm of the king and his sons?","notes":[]},{"number":24,"text":"Also we inform you that it shall not be lawful to impose tribute, custom, or toll on any of the priests, Levites, singers, gatekeepers, temple servants, or laborers of this house of God.","notes":[]},{"number":25,"text":"You, Ezra, according to the wisdom of your God that is in your hand, appoint magistrates and judges who may judge all the people who are beyond the River, who all know the laws of your God; and teach him who doesn’t know them.","notes":[]},{"number":26,"text":"Whoever will not do the law of your God and the law of the king, let judgment be executed on him with all diligence, whether it is to death, or to banishment, or to confiscation of goods, or to imprisonment.","notes":[]},{"number":27,"text":"Blessed be the LORD, the God of our fathers, who has put such a thing as this in the king’s heart, to beautify the LORD’s house which is in Jerusalem;","notes":[]},{"number":28,"text":"and has extended loving kindness to me before the king and his counselors, and before all the king’s mighty princes. I was strengthened according to the LORD my God’s hand on me, and I gathered together chief men out of Israel to go up with me.","notes":[]}],"source":"https://ebible.org/engwebp/EZR07.htm"},"GAL-6":{"book":"Galatians","chapter":6,"verses":[{"number":1,"text":"Brothers, even if a man is caught in some fault, you who are spiritual must restore such a one in a spirit of gentleness, looking to yourself so that you also aren’t tempted.","notes":[]},{"number":2,"text":"Bear one another’s burdens, and so fulfill the law of Christ.","notes":[]},{"number":3,"text":"For if a man thinks himself to be something when he is nothing, he deceives himself.","notes":[]},{"number":4,"text":"But let each man examine his own work, and then he will have reason to boast in himself, and not in someone else.","notes":[]},{"number":5,"text":"For each man will bear his own burden.","notes":[]},{"number":6,"text":"But let him who is taught in the word share all good things with him who teaches.","notes":[]},{"number":7,"text":"Don’t be deceived. God is not mocked, for whatever a man sows, that he will also reap.","notes":[]},{"number":8,"text":"For he who sows to his own flesh will from the flesh reap corruption. But he who sows to the Spirit will from the Spirit reap eternal life.","notes":[]},{"number":9,"text":"Let’s not be weary in doing good, for we will reap in due season if we don’t give up.","notes":[]},{"number":10,"text":"So then, as we have opportunity, let’s do what is good toward all men, and especially toward those who are of the household of the faith.","notes":[]},{"number":11,"text":"See with what large letters I write to you with my own hand.","notes":[]},{"number":12,"text":"As many as desire to make a good impression in the flesh compel you to be circumcised, just so they may not be persecuted for the cross of Christ.","notes":[]},{"number":13,"text":"For even they who receive circumcision don’t keep the law themselves, but they desire to have you circumcised, so that they may boast in your flesh.","notes":[]},{"number":14,"text":"But far be it from me to boast except in the cross of our Lord Jesus Christ, through which the world has been crucified to me, and I to the world.","notes":[]},{"number":15,"text":"For in Christ Jesus neither is circumcision anything, nor uncircumcision, but a new creation.","notes":[]},{"number":16,"text":"As many as walk by this rule, peace and mercy be on them, and on God’s Israel.","notes":[]},{"number":17,"text":"From now on, let no one cause me any trouble, for I bear the marks of the Lord Jesus branded on my body.","notes":[]},{"number":18,"text":"The grace of our Lord Jesus Christ be with your spirit, brothers. Amen.","notes":[]}],"source":"https://ebible.org/engwebp/GAL06.htm"},"GEN-11":{"book":"Genesis","chapter":11,"verses":[{"number":1,"text":"The whole earth was of one language and of one speech.","notes":[]},{"number":2,"text":"As they traveled east, they found a plain in the land of Shinar, and they lived there.","notes":["LXX reads “from the east”."]},{"number":3,"text":"They said to one another, “Come, let’s make bricks, and burn them thoroughly.” They had brick for stone, and they used tar for mortar.","notes":[]},{"number":4,"text":"They said, “Come, let’s build ourselves a city, and a tower whose top reaches to the sky, and let’s make a name for ourselves, lest we be scattered abroad on the surface of the whole earth.”","notes":[]},{"number":5,"text":"The LORD came down to see the city and the tower, which the children of men built.","notes":[]},{"number":6,"text":"The LORD said, “Behold, they are one people, and they all have one language, and this is what they begin to do. Now nothing will be withheld from them, which they intend to do.","notes":[]},{"number":7,"text":"Come, let’s go down, and there confuse their language, that they may not understand one another’s speech.”","notes":[]},{"number":8,"text":"So the LORD scattered them abroad from there on the surface of all the earth. They stopped building the city.","notes":[]},{"number":9,"text":"Therefore its name was called Babel, because there the LORD confused the language of all the earth. From there, the LORD scattered them abroad on the surface of all the earth.","notes":[]},{"number":10,"text":"This is the history of the generations of Shem: Shem was one hundred years old when he became the father of Arpachshad two years after the flood.","notes":[]},{"number":11,"text":"Shem lived five hundred years after he became the father of Arpachshad, and became the father of more sons and daughters.","notes":[]},{"number":12,"text":"Arpachshad lived thirty-five years and became the father of Shelah.","notes":[]},{"number":13,"text":"Arpachshad lived four hundred three years after he became the father of Shelah, and became the father of more sons and daughters.","notes":[]},{"number":14,"text":"Shelah lived thirty years, and became the father of Eber.","notes":[]},{"number":15,"text":"Shelah lived four hundred three years after he became the father of Eber, and became the father of more sons and daughters.","notes":[]},{"number":16,"text":"Eber lived thirty-four years, and became the father of Peleg.","notes":[]},{"number":17,"text":"Eber lived four hundred thirty years after he became the father of Peleg, and became the father of more sons and daughters.","notes":[]},{"number":18,"text":"Peleg lived thirty years, and became the father of Reu.","notes":[]},{"number":19,"text":"Peleg lived two hundred nine years after he became the father of Reu, and became the father of more sons and daughters.","notes":[]},{"number":20,"text":"Reu lived thirty-two years, and became the father of Serug.","notes":[]},{"number":21,"text":"Reu lived two hundred seven years after he became the father of Serug, and became the father of more sons and daughters.","notes":[]},{"number":22,"text":"Serug lived thirty years, and became the father of Nahor.","notes":[]},{"number":23,"text":"Serug lived two hundred years after he became the father of Nahor, and became the father of more sons and daughters.","notes":[]},{"number":24,"text":"Nahor lived twenty-nine years, and became the father of Terah.","notes":[]},{"number":25,"text":"Nahor lived one hundred nineteen years after he became the father of Terah, and became the father of more sons and daughters.","notes":[]},{"number":26,"text":"Terah lived seventy years, and became the father of Abram, Nahor, and Haran.","notes":[]},{"number":27,"text":"Now this is the history of the generations of Terah. Terah became the father of Abram, Nahor, and Haran. Haran became the father of Lot.","notes":[]},{"number":28,"text":"Haran died in the land of his birth, in Ur of the Chaldees, while his father Terah was still alive.","notes":[]},{"number":29,"text":"Abram and Nahor married wives. The name of Abram’s wife was Sarai, and the name of Nahor’s wife was Milcah, the daughter of Haran, who was also the father of Iscah.","notes":[]},{"number":30,"text":"Sarai was barren. She had no child.","notes":[]},{"number":31,"text":"Terah took Abram his son, Lot the son of Haran, his son’s son, and Sarai his daughter-in-law, his son Abram’s wife. They went from Ur of the Chaldees, to go into the land of Canaan. They came to Haran and lived there.","notes":[]},{"number":32,"text":"The days of Terah were two hundred five years. Terah died in Haran.","notes":[]}],"source":"https://ebible.org/engwebp/GEN11.htm"},"HAB-2":{"book":"Habakkuk","chapter":2,"verses":[{"number":1,"text":"I will stand at my watch and set myself on the ramparts, and will look out to see what he will say to me, and what I will answer concerning my complaint.","notes":[]},{"number":2,"text":"The LORD answered me, “Write the vision, and make it plain on tablets, that he who runs may read it.","notes":[]},{"number":3,"text":"For the vision is yet for the appointed time, and it hurries toward the end, and won’t prove false. Though it takes time, wait for it, because it will surely come. It won’t delay.","notes":[]},{"number":4,"text":"Behold, his soul is puffed up. It is not upright in him, but the righteous will live by his faith.","notes":[]},{"number":5,"text":"Yes, moreover, wine is treacherous: an arrogant man who doesn’t stay at home, who enlarges his desire as Sheol; he is like death and can’t be satisfied, but gathers to himself all nations and heaps to himself all peoples.","notes":["Sheol is the place of the dead."]},{"number":6,"text":"Won’t all these take up a parable against him, and a taunting proverb against him, and say, ‘Woe to him who increases that which is not his, and who enriches himself by extortion! How long?’","notes":[]},{"number":7,"text":"Won’t your debtors rise up suddenly, and wake up those who make you tremble, and you will be their victim?","notes":[]},{"number":8,"text":"Because you have plundered many nations, all the remnant of the peoples will plunder you because of men’s blood, and for the violence done to the land, to the city and to all who dwell in it.","notes":[]},{"number":9,"text":"Woe to him who gets an evil gain for his house, that he may set his nest on high, that he may be delivered from the hand of evil!","notes":[]},{"number":10,"text":"You have devised shame to your house by cutting off many peoples, and have sinned against your soul.","notes":[]},{"number":11,"text":"For the stone will cry out of the wall, and the beam out of the woodwork will answer it.","notes":[]},{"number":12,"text":"Woe to him who builds a town with blood, and establishes a city by iniquity!","notes":[]},{"number":13,"text":"Behold, isn’t it from the LORD of Armies that the peoples labor for the fire, and the nations weary themselves for vanity?","notes":[]},{"number":14,"text":"For the earth will be filled with the knowledge of the LORD’s glory, as the waters cover the sea.","notes":[]},{"number":15,"text":"“Woe to him who gives his neighbor drink, pouring your inflaming wine until they are drunk, so that you may gaze at their naked bodies!","notes":[]},{"number":16,"text":"You are filled with shame, and not glory. You will also drink and be exposed! The cup of the LORD’s right hand will come around to you, and disgrace will cover your glory.","notes":[]},{"number":17,"text":"For the violence done to Lebanon will overwhelm you, and the destruction of the animals will terrify you, because of men’s blood and for the violence done to the land, to every city and to those who dwell in them.","notes":[]},{"number":18,"text":"“What value does the engraved image have, that its maker has engraved it; the molten image, even the teacher of lies, that he who fashions its form trusts in it, to make mute idols?","notes":[]},{"number":19,"text":"Woe to him who says to the wood, ‘Awake!’ or to the mute stone, ‘Arise!’ Shall this teach? Behold, it is overlaid with gold and silver, and there is no breath at all within it.","notes":[]},{"number":20,"text":"But the LORD is in his holy temple. Let all the earth be silent before him!”","notes":[]}],"source":"https://ebible.org/engwebp/HAB02.htm"},"ISA-55":{"book":"Isaiah","chapter":55,"verses":[{"number":1,"text":"“Hey! Come, everyone who thirsts, to the waters! Come, he who has no money, buy, and eat! Yes, come, buy wine and milk without money and without price.","notes":[]},{"number":2,"text":"Why do you spend money for that which is not bread, and your labor for that which doesn’t satisfy? Listen diligently to me, and eat that which is good, and let your soul delight itself in richness.","notes":[]},{"number":3,"text":"Turn your ear, and come to me. Hear, and your soul will live. I will make an everlasting covenant with you, even the sure mercies of David.","notes":[]},{"number":4,"text":"Behold, I have given him for a witness to the peoples, a leader and commander to the peoples.","notes":[]},{"number":5,"text":"Behold, you shall call a nation that you don’t know; and a nation that didn’t know you shall run to you, because of the LORD your God, and for the Holy One of Israel; for he has glorified you.”","notes":[]},{"number":6,"text":"Seek the LORD while he may be found. Call on him while he is near.","notes":[]},{"number":7,"text":"Let the wicked forsake his way, and the unrighteous man his thoughts. Let him return to the LORD, and he will have mercy on him, to our God, for he will freely pardon.","notes":[]},{"number":8,"text":"“For my thoughts are not your thoughts, and your ways are not my ways,” says the LORD.","notes":[]},{"number":9,"text":"“For as the heavens are higher than the earth, so are my ways higher than your ways, and my thoughts than your thoughts.","notes":[]},{"number":10,"text":"For as the rain comes down and the snow from the sky, and doesn’t return there, but waters the earth, and makes it grow and bud, and gives seed to the sower and bread to the eater;","notes":[]},{"number":11,"text":"so is my word that goes out of my mouth: it will not return to me void, but it will accomplish that which I please, and it will prosper in the thing I sent it to do.","notes":[]},{"number":12,"text":"For you shall go out with joy, and be led out with peace. The mountains and the hills will break out before you into singing; and all the trees of the fields will clap their hands.","notes":[]},{"number":13,"text":"Instead of the thorn the cypress tree will come up; and instead of the brier the myrtle tree will come up. It will make a name for the LORD, for an everlasting sign that will not be cut off.”","notes":[]}],"source":"https://ebible.org/engwebp/ISA55.htm"},"JAS-3":{"book":"James","chapter":3,"verses":[{"number":1,"text":"Let not many of you be teachers, my brothers, knowing that we will receive heavier judgment.","notes":[]},{"number":2,"text":"For we all stumble in many things. Anyone who doesn’t stumble in word is a perfect person, able to bridle the whole body also.","notes":[]},{"number":3,"text":"Indeed, we put bits into the horses’ mouths so that they may obey us, and we guide their whole body.","notes":[]},{"number":4,"text":"Behold, the ships also, though they are so big and are driven by fierce winds, are yet guided by a very small rudder, wherever the pilot desires.","notes":["“Behold”, from “ἰδοὺ”, means look at, take notice, observe, see, or gaze at. It is often used as an interjection."]},{"number":5,"text":"So the tongue is also a little member, and boasts great things. See how a small fire can spread to a large forest!","notes":[]},{"number":6,"text":"And the tongue is a fire. The world of iniquity among our members is the tongue, which defiles the whole body, and sets on fire the course of nature, and is set on fire by Gehenna.","notes":["or, Hell"]},{"number":7,"text":"For every kind of animal, bird, creeping thing, and sea creature is tamed, and has been tamed by mankind;","notes":[]},{"number":8,"text":"but nobody can tame the tongue. It is a restless evil, full of deadly poison.","notes":[]},{"number":9,"text":"With it we bless our God and Father, and with it we curse men who are made in the image of God.","notes":[]},{"number":10,"text":"Out of the same mouth comes blessing and cursing. My brothers, these things ought not to be so.","notes":[]},{"number":11,"text":"Does a spring send out from the same opening fresh and bitter water?","notes":[]},{"number":12,"text":"Can a fig tree, my brothers, yield olives, or a vine figs? Thus no spring yields both salt water and fresh water.","notes":[]},{"number":13,"text":"Who is wise and understanding among you? Let him show by his good conduct that his deeds are done in gentleness of wisdom.","notes":[]},{"number":14,"text":"But if you have bitter jealousy and selfish ambition in your heart, don’t boast and don’t lie against the truth.","notes":[]},{"number":15,"text":"This wisdom is not that which comes down from above, but is earthly, sensual, and demonic.","notes":[]},{"number":16,"text":"For where jealousy and selfish ambition are, there is confusion and every evil deed.","notes":[]},{"number":17,"text":"But the wisdom that is from above is first pure, then peaceful, gentle, reasonable, full of mercy and good fruits, without partiality, and without hypocrisy.","notes":[]},{"number":18,"text":"Now the fruit of righteousness is sown in peace by those who make peace.","notes":[]}],"source":"https://ebible.org/engwebp/JAS03.htm"},"JER-36":{"book":"Jeremiah","chapter":36,"verses":[{"number":1,"text":"In the fourth year of Jehoiakim the son of Josiah, king of Judah, this word came to Jeremiah from the LORD, saying,","notes":[]},{"number":2,"text":"“Take a scroll of a book, and write in it all the words that I have spoken to you against Israel, against Judah, and against all the nations, from the day I spoke to you, from the days of Josiah even to this day.","notes":[]},{"number":3,"text":"It may be that the house of Judah will hear all the evil which I intend to do to them, that they may each return from his evil way; that I may forgive their iniquity and their sin.”","notes":[]},{"number":4,"text":"Then Jeremiah called Baruch the son of Neriah; and Baruch wrote from the mouth of Jeremiah all the LORD’s words, which he had spoken to him, on a scroll of a book.","notes":[]},{"number":5,"text":"Jeremiah commanded Baruch, saying, “I am restricted. I can’t go into the LORD’s house.","notes":[]},{"number":6,"text":"Therefore you go, and read from the scroll which you have written from my mouth, the LORD’s words, in the ears of the people in the LORD’s house on the fast day. Also you shall read them in the ears of all Judah who come out of their cities.","notes":[]},{"number":7,"text":"It may be they will present their supplication before the LORD, and will each return from his evil way; for the LORD has pronounced great anger and wrath against this people.”","notes":[]},{"number":8,"text":"Baruch the son of Neriah did according to all that Jeremiah the prophet commanded him, reading in the book the LORD’s words in the LORD’s house.","notes":[]},{"number":9,"text":"Now in the fifth year of Jehoiakim the son of Josiah, king of Judah, in the ninth month, all the people in Jerusalem and all the people who came from the cities of Judah to Jerusalem, proclaimed a fast before the LORD.","notes":[]},{"number":10,"text":"Then Baruch read the words of Jeremiah from the book in the LORD’s house, in the room of Gemariah the son of Shaphan the scribe, in the upper court, at the entry of the new gate of the LORD’s house, in the ears of all the people.","notes":[]},{"number":11,"text":"When Micaiah the son of Gemariah, the son of Shaphan, had heard out of the book all the LORD’s words,","notes":[]},{"number":12,"text":"he went down into the king’s house, into the scribe’s room; and behold, all the princes were sitting there, Elishama the scribe, Delaiah the son of Shemaiah, Elnathan the son of Achbor, Gemariah the son of Shaphan, Zedekiah the son of Hananiah, and all the princes.","notes":[]},{"number":13,"text":"Then Micaiah declared to them all the words that he had heard, when Baruch read the book in the ears of the people.","notes":[]},{"number":14,"text":"Therefore all the princes sent Jehudi the son of Nethaniah, the son of Shelemiah, the son of Cushi, to Baruch, saying, “Take in your hand the scroll in which you have read in the ears of the people, and come.” So Baruch the son of Neriah took the scroll in his hand, and came to them.","notes":[]},{"number":15,"text":"They said to him, “Sit down now, and read it in our hearing.” So Baruch read it in their hearing.","notes":[]},{"number":16,"text":"Now when they had heard all the words, they turned in fear one toward another, and said to Baruch, “We will surely tell the king of all these words.”","notes":[]},{"number":17,"text":"They asked Baruch, saying, “Tell us now, how did you write all these words at his mouth?”","notes":[]},{"number":18,"text":"Then Baruch answered them, “He dictated all these words to me with his mouth, and I wrote them with ink in the book.”","notes":[]},{"number":19,"text":"Then the princes said to Baruch, “You and Jeremiah go hide. Don’t let anyone know where you are.”","notes":[]},{"number":20,"text":"They went in to the king into the court, but they had laid up the scroll in the room of Elishama the scribe. Then they told all the words in the hearing of the king.","notes":[]},{"number":21,"text":"So the king sent Jehudi to get the scroll, and he took it out of the room of Elishama the scribe. Jehudi read it in the hearing of the king, and in the hearing of all the princes who stood beside the king.","notes":[]},{"number":22,"text":"Now the king was sitting in the winter house in the ninth month, and there was a fire in the brazier burning before him.","notes":[]},{"number":23,"text":"When Jehudi had read three or four columns, the king cut it with the penknife, and cast it into the fire that was in the brazier, until all the scroll was consumed in the fire that was in the brazier.","notes":[]},{"number":24,"text":"The king and his servants who heard all these words were not afraid, and didn’t tear their garments.","notes":[]},{"number":25,"text":"Moreover Elnathan and Delaiah and Gemariah had made intercession to the king that he would not burn the scroll; but he would not listen to them.","notes":[]},{"number":26,"text":"The king commanded Jerahmeel the king’s son, and Seraiah the son of Azriel, and Shelemiah the son of Abdeel, to arrest Baruch the scribe and Jeremiah the prophet; but the LORD hid them.","notes":[]},{"number":27,"text":"Then the LORD’s word came to Jeremiah, after the king had burned the scroll, and the words which Baruch wrote at the mouth of Jeremiah, saying,","notes":[]},{"number":28,"text":"“Take again another scroll, and write in it all the former words that were in the first scroll, which Jehoiakim the king of Judah has burned.","notes":[]},{"number":29,"text":"Concerning Jehoiakim king of Judah you shall say, ‘The LORD says: “You have burned this scroll, saying, ‘Why have you written therein, saying, “The king of Babylon will certainly come and destroy this land, and will cause to cease from there man and animal”?’ ”","notes":[]},{"number":30,"text":"Therefore the LORD says concerning Jehoiakim king of Judah: “He will have no one to sit on David’s throne. His dead body will be cast out in the day to the heat, and in the night to the frost.","notes":[]},{"number":31,"text":"I will punish him, his offspring, and his servants for their iniquity. I will bring on them, on the inhabitants of Jerusalem, and on the men of Judah, all the evil that I have pronounced against them, but they didn’t listen.” ’ ”","notes":[]},{"number":32,"text":"Then Jeremiah took another scroll, and gave it to Baruch the scribe, the son of Neriah, who wrote therein from the mouth of Jeremiah all the words of the book which Jehoiakim king of Judah had burned in the fire; and many similar words were added to them.","notes":[]}],"source":"https://ebible.org/engwebp/JER36.htm"},"JHN-20":{"book":"John","chapter":20,"verses":[{"number":1,"text":"Now on the first day of the week, Mary Magdalene went early, while it was still dark, to the tomb, and saw that the stone had been taken away from the tomb.","notes":[]},{"number":2,"text":"Therefore she ran and came to Simon Peter and to the other disciple whom Jesus loved, and said to them, “They have taken away the Lord out of the tomb, and we don’t know where they have laid him!”","notes":[]},{"number":3,"text":"Therefore Peter and the other disciple went out, and they went toward the tomb.","notes":[]},{"number":4,"text":"They both ran together. The other disciple outran Peter and came to the tomb first.","notes":[]},{"number":5,"text":"Stooping and looking in, he saw the linen cloths lying there; yet he didn’t enter in.","notes":[]},{"number":6,"text":"Then Simon Peter came, following him, and entered into the tomb. He saw the linen cloths lying,","notes":[]},{"number":7,"text":"and the cloth that had been on his head, not lying with the linen cloths, but rolled up in a place by itself.","notes":[]},{"number":8,"text":"So then the other disciple who came first to the tomb also entered in, and he saw and believed.","notes":[]},{"number":9,"text":"For as yet they didn’t know the Scripture, that he must rise from the dead.","notes":[]},{"number":10,"text":"So the disciples went away again to their own homes.","notes":[]},{"number":11,"text":"But Mary was standing outside at the tomb weeping. So as she wept, she stooped and looked into the tomb,","notes":[]},{"number":12,"text":"and she saw two angels in white sitting, one at the head and one at the feet, where the body of Jesus had lain.","notes":[]},{"number":13,"text":"They asked her, “Woman, why are you weeping?” She said to them, “Because they have taken away my Lord, and I don’t know where they have laid him.”","notes":[]},{"number":14,"text":"When she had said this, she turned around and saw Jesus standing, and didn’t know that it was Jesus.","notes":[]},{"number":15,"text":"Jesus said to her, “Woman, why are you weeping? Who are you looking for?” She, supposing him to be the gardener, said to him, “Sir, if you have carried him away, tell me where you have laid him, and I will take him away.”","notes":[]},{"number":16,"text":"Jesus said to her, “Mary.” She turned and said to him, “Rabboni!” which is to say, “Teacher!”","notes":["Rabboni is a transliteration of the Aramaic word for “great teacher.”","or, Master"]},{"number":17,"text":"Jesus said to her, “Don’t hold me, for I haven’t yet ascended to my Father; but go to my brothers and tell them, ‘I am ascending to my Father and your Father, to my God and your God.’ ”","notes":[]},{"number":18,"text":"Mary Magdalene came and told the disciples that she had seen the Lord, and that he had said these things to her.","notes":[]},{"number":19,"text":"When therefore it was evening on that day, the first day of the week, and when the doors were locked where the disciples were assembled, for fear of the Jews, Jesus came and stood in the middle and said to them, “Peace be to you.”","notes":[]},{"number":20,"text":"When he had said this, he showed them his hands and his side. The disciples therefore were glad when they saw the Lord.","notes":[]},{"number":21,"text":"Jesus therefore said to them again, “Peace be to you. As the Father has sent me, even so I send you.”","notes":[]},{"number":22,"text":"When he had said this, he breathed on them, and said to them, “Receive the Holy Spirit!","notes":[]},{"number":23,"text":"If you forgive anyone’s sins, they have been forgiven them. If you retain anyone’s sins, they have been retained.”","notes":[]},{"number":24,"text":"But Thomas, one of the twelve, called Didymus, wasn’t with them when Jesus came.","notes":["or, Twin"]},{"number":25,"text":"The other disciples therefore said to him, “We have seen the Lord!” But he said to them, “Unless I see in his hands the print of the nails, put my finger into the print of the nails, and put my hand into his side, I will not believe.”","notes":[]},{"number":26,"text":"After eight days, again his disciples were inside and Thomas was with them. Jesus came, the doors being locked, and stood in the middle, and said, “Peace be to you.”","notes":[]},{"number":27,"text":"Then he said to Thomas, “Reach here your finger, and see my hands. Reach here your hand, and put it into my side. Don’t be unbelieving, but believing.”","notes":[]},{"number":28,"text":"Thomas answered him, “My Lord and my God!”","notes":[]},{"number":29,"text":"Jesus said to him, “Because you have seen me, you have believed. Blessed are those who have not seen and have believed.”","notes":["TR adds “Thomas,”"]},{"number":30,"text":"Therefore Jesus did many other signs in the presence of his disciples, which are not written in this book;","notes":[]},{"number":31,"text":"but these are written that you may believe that Jesus is the Christ, the Son of God, and that believing you may have life in his name.","notes":[]}],"source":"https://ebible.org/engwebp/JHN20.htm"},"JOS-4":{"book":"Joshua","chapter":4,"verses":[{"number":1,"text":"When all the nation had completely crossed over the Jordan, the LORD spoke to Joshua, saying,","notes":[]},{"number":2,"text":"“Take twelve men out of the people, a man out of every tribe,","notes":[]},{"number":3,"text":"and command them, saying, ‘Take from out of the middle of the Jordan, out of the place where the priests’ feet stood firm, twelve stones, carry them over with you, and lay them down in the place where you’ll camp tonight.’ ”","notes":[]},{"number":4,"text":"Then Joshua called the twelve men whom he had prepared of the children of Israel, a man out of every tribe.","notes":[]},{"number":5,"text":"Joshua said to them, “Cross before the ark of the LORD your God into the middle of the Jordan, and each of you pick up a stone and put it on your shoulder, according to the number of the tribes of the children of Israel;","notes":[]},{"number":6,"text":"that this may be a sign among you, that when your children ask in the future, saying, ‘What do you mean by these stones?’","notes":[]},{"number":7,"text":"then you shall tell them, ‘Because the waters of the Jordan were cut off before the ark of the LORD’s covenant. When it crossed over the Jordan, the waters of the Jordan were cut off. These stones shall be for a memorial to the children of Israel forever.’ ”","notes":[]},{"number":8,"text":"The children of Israel did as Joshua commanded, and took up twelve stones out of the middle of the Jordan, as the LORD spoke to Joshua, according to the number of the tribes of the children of Israel. They carried them over with them to the place where they camped, and laid them down there.","notes":[]},{"number":9,"text":"Joshua set up twelve stones in the middle of the Jordan, in the place where the feet of the priests who bore the ark of the covenant stood; and they are there to this day.","notes":[]},{"number":10,"text":"For the priests who bore the ark stood in the middle of the Jordan until everything was finished that the LORD commanded Joshua to speak to the people, according to all that Moses commanded Joshua; and the people hurried and passed over.","notes":[]},{"number":11,"text":"When all the people had completely crossed over, the LORD’s ark crossed over with the priests in the presence of the people.","notes":[]},{"number":12,"text":"The children of Reuben, and the children of Gad, and the half-tribe of Manasseh crossed over armed before the children of Israel, as Moses spoke to them.","notes":[]},{"number":13,"text":"About forty thousand men, ready and armed for war, passed over before the LORD to battle, to the plains of Jericho.","notes":[]},{"number":14,"text":"On that day, the LORD magnified Joshua in the sight of all Israel; and they feared him, as they feared Moses, all the days of his life.","notes":[]},{"number":15,"text":"The LORD spoke to Joshua, saying,","notes":[]},{"number":16,"text":"“Command the priests who bear the ark of the covenant, that they come up out of the Jordan.”","notes":[]},{"number":17,"text":"Joshua therefore commanded the priests, saying, “Come up out of the Jordan!”","notes":[]},{"number":18,"text":"When the priests who bore the ark of the LORD’s covenant had come up out of the middle of the Jordan, and the soles of the priests’ feet had been lifted up to the dry ground, the waters of the Jordan returned to their place, and went over all its banks, as before.","notes":[]},{"number":19,"text":"The people came up out of the Jordan on the tenth day of the first month, and encamped in Gilgal, on the east border of Jericho.","notes":[]},{"number":20,"text":"Joshua set up those twelve stones, which they took out of the Jordan, in Gilgal.","notes":[]},{"number":21,"text":"He spoke to the children of Israel, saying, “When your children ask their fathers in time to come, saying, ‘What do these stones mean?’","notes":[]},{"number":22,"text":"Then you shall let your children know, saying, ‘Israel came over this Jordan on dry land.","notes":[]},{"number":23,"text":"For the LORD your God dried up the waters of the Jordan from before you until you had crossed over, as the LORD your God did to the Red Sea, which he dried up from before us, until we had crossed over,","notes":[]},{"number":24,"text":"that all the peoples of the earth may know that the LORD’s hand is mighty, and that you may fear the LORD your God forever.’ ”","notes":[]}],"source":"https://ebible.org/engwebp/JOS04.htm"},"LUK-14":{"book":"Luke","chapter":14,"verses":[{"number":1,"text":"When he went into the house of one of the rulers of the Pharisees on a Sabbath to eat bread, they were watching him.","notes":[]},{"number":2,"text":"Behold, a certain man who had dropsy was in front of him.","notes":[]},{"number":3,"text":"Jesus, answering, spoke to the lawyers and Pharisees, saying, “Is it lawful to heal on the Sabbath?”","notes":[]},{"number":4,"text":"But they were silent. He took him, and healed him, and let him go.","notes":[]},{"number":5,"text":"He answered them, “Which of you, if your son or an ox fell into a well, wouldn’t immediately pull him out on a Sabbath day?”","notes":["TR reads “donkey” instead of “son”"]},{"number":6,"text":"They couldn’t answer him regarding these things.","notes":[]},{"number":7,"text":"He spoke a parable to those who were invited, when he noticed how they chose the best seats, and said to them,","notes":[]},{"number":8,"text":"“When you are invited by anyone to a wedding feast, don’t sit in the best seat, since perhaps someone more honorable than you might be invited by him,","notes":[]},{"number":9,"text":"and he who invited both of you would come and tell you, ‘Make room for this person.’ Then you would begin, with shame, to take the lowest place.","notes":[]},{"number":10,"text":"But when you are invited, go and sit in the lowest place, so that when he who invited you comes, he may tell you, ‘Friend, move up higher.’ Then you will be honored in the presence of all who sit at the table with you.","notes":[]},{"number":11,"text":"For everyone who exalts himself will be humbled, and whoever humbles himself will be exalted.”","notes":[]},{"number":12,"text":"He also said to the one who had invited him, “When you make a dinner or a supper, don’t call your friends, nor your brothers, nor your kinsmen, nor rich neighbors, or perhaps they might also return the favor, and pay you back.","notes":[]},{"number":13,"text":"But when you make a feast, ask the poor, the maimed, the lame, or the blind;","notes":[]},{"number":14,"text":"and you will be blessed, because they don’t have the resources to repay you. For you will be repaid in the resurrection of the righteous.”","notes":[]},{"number":15,"text":"When one of those who sat at the table with him heard these things, he said to him, “Blessed is he who will feast in God’s Kingdom!”","notes":[]},{"number":16,"text":"But he said to him, “A certain man made a great supper, and he invited many people.","notes":[]},{"number":17,"text":"He sent out his servant at supper time to tell those who were invited, ‘Come, for everything is ready now.’","notes":[]},{"number":18,"text":"They all as one began to make excuses. “The first said to him, ‘I have bought a field, and I must go and see it. Please have me excused.’","notes":[]},{"number":19,"text":"“Another said, ‘I have bought five yoke of oxen, and I must go try them out. Please have me excused.’","notes":[]},{"number":20,"text":"“Another said, ‘I have married a wife, and therefore I can’t come.’","notes":[]},{"number":21,"text":"“That servant came, and told his lord these things. Then the master of the house, being angry, said to his servant, ‘Go out quickly into the streets and lanes of the city, and bring in the poor, maimed, blind, and lame.’","notes":[]},{"number":22,"text":"“The servant said, ‘Lord, it is done as you commanded, and there is still room.’","notes":[]},{"number":23,"text":"“The lord said to the servant, ‘Go out into the highways and hedges, and compel them to come in, that my house may be filled.","notes":[]},{"number":24,"text":"For I tell you that none of those men who were invited will taste of my supper. For many are called, but few are chosen. ’ ”","notes":["RP MT includes the last sentence. TR, NU, and FH MT omit: For many are called, but few are chosen."]},{"number":25,"text":"Now great multitudes were going with him. He turned and said to them,","notes":[]},{"number":26,"text":"“If anyone comes to me, and doesn’t disregard his own father, mother, wife, children, brothers, and sisters, yes, and his own life also, he can’t be my disciple.","notes":["or, hate"]},{"number":27,"text":"Whoever doesn’t bear his own cross and come after me, can’t be my disciple.","notes":[]},{"number":28,"text":"For which of you, desiring to build a tower, doesn’t first sit down and count the cost, to see if he has enough to complete it?","notes":[]},{"number":29,"text":"Or perhaps, when he has laid a foundation and isn’t able to finish, everyone who sees begins to mock him,","notes":[]},{"number":30,"text":"saying, ‘This man began to build and wasn’t able to finish.’","notes":[]},{"number":31,"text":"Or what king, as he goes to encounter another king in war, will not sit down first and consider whether he is able with ten thousand to meet him who comes against him with twenty thousand?","notes":[]},{"number":32,"text":"Or else, while the other is yet a great way off, he sends an envoy and asks for conditions of peace.","notes":[]},{"number":33,"text":"So therefore, whoever of you who doesn’t renounce all that he has, he can’t be my disciple.","notes":[]},{"number":34,"text":"“Salt is good, but if the salt becomes flat and tasteless, with what do you season it?","notes":[]},{"number":35,"text":"It is fit neither for the soil nor for the manure pile. It is thrown out. He who has ears to hear, let him hear.”","notes":[]}],"source":"https://ebible.org/engwebp/LUK14.htm"},"LUK-24":{"book":"Luke","chapter":24,"verses":[{"number":1,"text":"But on the first day of the week, at early dawn, they and some others came to the tomb, bringing the spices which they had prepared.","notes":[]},{"number":2,"text":"They found the stone rolled away from the tomb.","notes":[]},{"number":3,"text":"They entered in, and didn’t find the Lord Jesus’ body.","notes":[]},{"number":4,"text":"While they were greatly perplexed about this, behold, two men stood by them in dazzling clothing.","notes":[]},{"number":5,"text":"Becoming terrified, they bowed their faces down to the earth. The men said to them, “Why do you seek the living among the dead?","notes":[]},{"number":6,"text":"He isn’t here, but is risen. Remember what he told you when he was still in Galilee,","notes":[]},{"number":7,"text":"saying that the Son of Man must be delivered up into the hands of sinful men and be crucified, and the third day rise again?”","notes":[]},{"number":8,"text":"They remembered his words,","notes":[]},{"number":9,"text":"returned from the tomb, and told all these things to the eleven and to all the rest.","notes":[]},{"number":10,"text":"Now they were Mary Magdalene, Joanna, and Mary the mother of James. The other women with them told these things to the apostles.","notes":[]},{"number":11,"text":"These words seemed to them to be nonsense, and they didn’t believe them.","notes":[]},{"number":12,"text":"But Peter got up and ran to the tomb. Stooping and looking in, he saw the strips of linen lying by themselves, and he departed to his home, wondering what had happened.","notes":[]},{"number":13,"text":"Behold, two of them were going that very day to a village named Emmaus, which was sixty stadia from Jerusalem.","notes":["60 stadia = about 11 kilometers or about 7 miles."]},{"number":14,"text":"They talked with each other about all of these things which had happened.","notes":[]},{"number":15,"text":"While they talked and questioned together, Jesus himself came near, and went with them.","notes":[]},{"number":16,"text":"But their eyes were kept from recognizing him.","notes":[]},{"number":17,"text":"He said to them, “What are you talking about as you walk, and are sad?”","notes":[]},{"number":18,"text":"One of them, named Cleopas, answered him, “Are you the only stranger in Jerusalem who doesn’t know the things which have happened there in these days?”","notes":[]},{"number":19,"text":"He said to them, “What things?” They said to him, “The things concerning Jesus the Nazarene, who was a prophet mighty in deed and word before God and all the people;","notes":[]},{"number":20,"text":"and how the chief priests and our rulers delivered him up to be condemned to death, and crucified him.","notes":[]},{"number":21,"text":"But we were hoping that it was he who would redeem Israel. Yes, and besides all this, it is now the third day since these things happened.","notes":[]},{"number":22,"text":"Also, certain women of our company amazed us, having arrived early at the tomb;","notes":[]},{"number":23,"text":"and when they didn’t find his body, they came saying that they had also seen a vision of angels, who said that he was alive.","notes":[]},{"number":24,"text":"Some of us went to the tomb and found it just like the women had said, but they didn’t see him.”","notes":[]},{"number":25,"text":"He said to them, “Foolish people, and slow of heart to believe in all that the prophets have spoken!","notes":[]},{"number":26,"text":"Didn’t the Christ have to suffer these things and to enter into his glory?”","notes":[]},{"number":27,"text":"Beginning from Moses and from all the prophets, he explained to them in all the Scriptures the things concerning himself.","notes":[]},{"number":28,"text":"They came near to the village where they were going, and he acted like he would go further.","notes":[]},{"number":29,"text":"They urged him, saying, “Stay with us, for it is almost evening, and the day is almost over.” He went in to stay with them.","notes":[]},{"number":30,"text":"When he had sat down at the table with them, he took the bread and gave thanks. Breaking it, he gave it to them.","notes":[]},{"number":31,"text":"Their eyes were opened and they recognized him; then he vanished out of their sight.","notes":[]},{"number":32,"text":"They said to one another, “Weren’t our hearts burning within us while he spoke to us along the way, and while he opened the Scriptures to us?”","notes":[]},{"number":33,"text":"They rose up that very hour, returned to Jerusalem, and found the eleven gathered together, and those who were with them,","notes":[]},{"number":34,"text":"saying, “The Lord is risen indeed, and has appeared to Simon!”","notes":[]},{"number":35,"text":"They related the things that happened along the way, and how he was recognized by them in the breaking of the bread.","notes":[]},{"number":36,"text":"As they said these things, Jesus himself stood among them, and said to them, “Peace be to you.”","notes":[]},{"number":37,"text":"But they were terrified and filled with fear, and supposed that they had seen a spirit.","notes":[]},{"number":38,"text":"He said to them, “Why are you troubled? Why do doubts arise in your hearts?","notes":[]},{"number":39,"text":"See my hands and my feet, that it is truly me. Touch me and see, for a spirit doesn’t have flesh and bones, as you see that I have.”","notes":[]},{"number":40,"text":"When he had said this, he showed them his hands and his feet.","notes":[]},{"number":41,"text":"While they still didn’t believe for joy, and wondered, he said to them, “Do you have anything here to eat?”","notes":[]},{"number":42,"text":"They gave him a piece of a broiled fish and some honeycomb.","notes":[]},{"number":43,"text":"He took them, and ate in front of them.","notes":[]},{"number":44,"text":"He said to them, “This is what I told you while I was still with you, that all things which are written in the law of Moses, the prophets, and the psalms concerning me must be fulfilled.”","notes":[]},{"number":45,"text":"Then he opened their minds, that they might understand the Scriptures.","notes":[]},{"number":46,"text":"He said to them, “Thus it is written, and thus it was necessary for the Christ to suffer and to rise from the dead the third day,","notes":[]},{"number":47,"text":"and that repentance and remission of sins should be preached in his name to all the nations, beginning at Jerusalem.","notes":[]},{"number":48,"text":"You are witnesses of these things.","notes":[]},{"number":49,"text":"Behold, I send out the promise of my Father on you. But wait in the city of Jerusalem until you are clothed with power from on high.”","notes":[]},{"number":50,"text":"He led them out as far as Bethany, and he lifted up his hands and blessed them.","notes":[]},{"number":51,"text":"While he blessed them, he withdrew from them and was carried up into heaven.","notes":[]},{"number":52,"text":"They worshiped him and returned to Jerusalem with great joy,","notes":[]},{"number":53,"text":"and were continually in the temple, praising and blessing God. Amen.","notes":[]}],"source":"https://ebible.org/engwebp/LUK24.htm"},"MAT-28":{"book":"Matthew","chapter":28,"verses":[{"number":1,"text":"Now after the Sabbath, as it began to dawn on the first day of the week, Mary Magdalene and the other Mary came to see the tomb.","notes":[]},{"number":2,"text":"Behold, there was a great earthquake, for an angel of the Lord descended from the sky and came and rolled away the stone from the door and sat on it.","notes":[]},{"number":3,"text":"His appearance was like lightning, and his clothing white as snow.","notes":[]},{"number":4,"text":"For fear of him, the guards shook, and became like dead men.","notes":[]},{"number":5,"text":"The angel answered the women, “Don’t be afraid, for I know that you seek Jesus, who has been crucified.","notes":[]},{"number":6,"text":"He is not here, for he has risen, just like he said. Come, see the place where the Lord was lying.","notes":[]},{"number":7,"text":"Go quickly and tell his disciples, ‘He has risen from the dead, and behold, he goes before you into Galilee; there you will see him.’ Behold, I have told you.”","notes":[]},{"number":8,"text":"They departed quickly from the tomb with fear and great joy, and ran to bring his disciples word.","notes":[]},{"number":9,"text":"As they went to tell his disciples, behold, Jesus met them, saying, “Rejoice!” They came and took hold of his feet, and worshiped him.","notes":[]},{"number":10,"text":"Then Jesus said to them, “Don’t be afraid. Go tell my brothers that they should go into Galilee, and there they will see me.”","notes":["The word for “brothers” here may be also correctly translated “brothers and sisters” or “siblings.”"]},{"number":11,"text":"Now while they were going, behold, some of the guards came into the city and told the chief priests all the things that had happened.","notes":[]},{"number":12,"text":"When they were assembled with the elders and had taken counsel, they gave a large amount of silver to the soldiers,","notes":[]},{"number":13,"text":"saying, “Say that his disciples came by night and stole him away while we slept.","notes":[]},{"number":14,"text":"If this comes to the governor’s ears, we will persuade him and make you free of worry.”","notes":[]},{"number":15,"text":"So they took the money and did as they were told. This saying was spread abroad among the Jews, and continues until today.","notes":[]},{"number":16,"text":"But the eleven disciples went into Galilee, to the mountain where Jesus had sent them.","notes":[]},{"number":17,"text":"When they saw him, they bowed down to him; but some doubted.","notes":[]},{"number":18,"text":"Jesus came to them and spoke to them, saying, “All authority has been given to me in heaven and on earth.","notes":[]},{"number":19,"text":"Go and make disciples of all nations, baptizing them in the name of the Father and of the Son and of the Holy Spirit,","notes":["TR and NU add “therefore”"]},{"number":20,"text":"teaching them to observe all things that I commanded you. Behold, I am with you always, even to the end of the age.” Amen.","notes":[]}],"source":"https://ebible.org/engwebp/MAT28.htm"},"MIC-6":{"book":"Micah","chapter":6,"verses":[{"number":1,"text":"Listen now to what the LORD says: “Arise, plead your case before the mountains, and let the hills hear what you have to say.","notes":[]},{"number":2,"text":"Hear, you mountains, the LORD’s indictment, and you enduring foundations of the earth; for the LORD has a case against his people, and he will contend with Israel.","notes":[]},{"number":3,"text":"My people, what have I done to you? How have I burdened you? Answer me!","notes":[]},{"number":4,"text":"For I brought you up out of the land of Egypt, and redeemed you out of the house of bondage. I sent before you Moses, Aaron, and Miriam.","notes":[]},{"number":5,"text":"My people, remember now what Balak king of Moab devised, and what Balaam the son of Beor answered him from Shittim to Gilgal, that you may know the righteous acts of the LORD.”","notes":[]},{"number":6,"text":"How shall I come before the LORD, and bow myself before the exalted God? Shall I come before him with burnt offerings, with calves a year old?","notes":[]},{"number":7,"text":"Will the LORD be pleased with thousands of rams? With tens of thousands of rivers of oil? Shall I give my firstborn for my disobedience? The fruit of my body for the sin of my soul?","notes":[]},{"number":8,"text":"He has shown you, O man, what is good. What does the LORD require of you, but to act justly, to love mercy, and to walk humbly with your God?","notes":[]},{"number":9,"text":"The LORD’s voice calls to the city— and wisdom fears your name— “Listen to the rod, and he who appointed it.","notes":[]},{"number":10,"text":"Are there yet treasures of wickedness in the house of the wicked, and a short ephah that is accursed?","notes":["An ephah is a measure of volume (about 22 liters or about 2/3 of a bushel), and a short ephah is made smaller than a full ephah for the purpose of cheating customers."]},{"number":11,"text":"Shall I tolerate dishonest scales, and a bag of deceitful weights?","notes":[]},{"number":12,"text":"Her rich men are full of violence, her inhabitants speak lies, and their tongue is deceitful in their speech.","notes":[]},{"number":13,"text":"Therefore I also have struck you with a grievous wound. I have made you desolate because of your sins.","notes":[]},{"number":14,"text":"You shall eat, but not be satisfied. Your hunger will be within you. You will store up, but not save, and that which you save I will give up to the sword.","notes":[]},{"number":15,"text":"You will sow, but won’t reap. You will tread the olives, but won’t anoint yourself with oil; and crush grapes, but won’t drink the wine.","notes":[]},{"number":16,"text":"For the statutes of Omri are kept, and all the works of Ahab’s house. You walk in their counsels, that I may make you a ruin, and your inhabitants a hissing. You will bear the reproach of my people.”","notes":[]}],"source":"https://ebible.org/engwebp/MIC06.htm"},"NEH-2":{"book":"Nehemiah","chapter":2,"verses":[{"number":1,"text":"In the month Nisan, in the twentieth year of Artaxerxes the king, when wine was before him, I picked up the wine, and gave it to the king. Now I had not been sad before in his presence.","notes":[]},{"number":2,"text":"The king said to me, “Why is your face sad, since you are not sick? This is nothing else but sorrow of heart.” Then I was very much afraid.","notes":[]},{"number":3,"text":"I said to the king, “Let the king live forever! Why shouldn’t my face be sad, when the city, the place of my fathers’ tombs, lies waste, and its gates have been consumed with fire?”","notes":[]},{"number":4,"text":"Then the king said to me, “What is your request?” So I prayed to the God of heaven.","notes":[]},{"number":5,"text":"I said to the king, “If it pleases the king, and if your servant has found favor in your sight, I ask that you would send me to Judah, to the city of my fathers’ tombs, that I may build it.”","notes":[]},{"number":6,"text":"The king said to me (the queen was also sitting by him), “How long will your journey be? When will you return?” So it pleased the king to send me, and I set a time for him.","notes":[]},{"number":7,"text":"Moreover I said to the king, “If it pleases the king, let letters be given me to the governors beyond the River, that they may let me pass through until I come to Judah;","notes":[]},{"number":8,"text":"and a letter to Asaph the keeper of the king’s forest, that he may give me timber to make beams for the gates of the citadel by the temple, for the wall of the city, and for the house that I will occupy.” The king granted my requests, because of the good hand of my God on me.","notes":[]},{"number":9,"text":"Then I came to the governors beyond the River, and gave them the king’s letters. Now the king had sent captains of the army and horsemen with me.","notes":[]},{"number":10,"text":"When Sanballat the Horonite and Tobiah the Ammonite servant heard of it, it grieved them exceedingly, because a man had come to seek the welfare of the children of Israel.","notes":[]},{"number":11,"text":"So I came to Jerusalem, and was there three days.","notes":[]},{"number":12,"text":"I arose in the night, I and a few men with me. I didn’t tell anyone what my God put into my heart to do for Jerusalem. There wasn’t any animal with me except the animal that I rode on.","notes":[]},{"number":13,"text":"I went out by night by the valley gate toward the jackal’s well, then to the dung gate; and I inspected the walls of Jerusalem, which were broken down, and its gates were consumed with fire.","notes":[]},{"number":14,"text":"Then I went on to the spring gate and to the king’s pool, but there was no place for the animal that was under me to pass.","notes":[]},{"number":15,"text":"Then I went up in the night by the brook and inspected the wall; and I turned back, and entered by the valley gate, and so returned.","notes":[]},{"number":16,"text":"The rulers didn’t know where I went, or what I did. I had not as yet told it to the Jews, nor to the priests, nor to the nobles, nor to the rulers, nor to the rest who did the work.","notes":[]},{"number":17,"text":"Then I said to them, “You see the bad situation that we are in, how Jerusalem lies waste, and its gates are burned with fire. Come, let’s build up the wall of Jerusalem, that we won’t be disgraced.”","notes":[]},{"number":18,"text":"I told them about the hand of my God which was good on me, and also about the king’s words that he had spoken to me. They said, “Let’s rise up and build.” So they strengthened their hands for the good work.","notes":[]},{"number":19,"text":"But when Sanballat the Horonite, Tobiah the Ammonite servant, and Geshem the Arabian, heard it, they ridiculed us and despised us, and said, “What is this thing that you are doing? Will you rebel against the king?”","notes":[]},{"number":20,"text":"Then I answered them, and said to them, “The God of heaven will prosper us. Therefore we, his servants, will arise and build; but you have no portion, nor right, nor memorial in Jerusalem.”","notes":[]}],"source":"https://ebible.org/engwebp/NEH02.htm"},"NEH-8":{"book":"Nehemiah","chapter":8,"verses":[{"number":1,"text":"All the people gathered themselves together as one man into the wide place that was in front of the water gate; and they spoke to Ezra the scribe to bring the book of the law of Moses, which the LORD had commanded to Israel.","notes":[]},{"number":2,"text":"Ezra the priest brought the law before the assembly, both men and women, and all who could hear with understanding, on the first day of the seventh month.","notes":[]},{"number":3,"text":"He read from it before the wide place that was in front of the water gate from early morning until midday, in the presence of the men and the women, and of those who could understand. The ears of all the people were attentive to the book of the law.","notes":[]},{"number":4,"text":"Ezra the scribe stood on a pulpit of wood, which they had made for the purpose; and beside him stood Mattithiah, Shema, Anaiah, Uriah, Hilkiah, and Maaseiah, on his right hand; and on his left hand, Pedaiah, Mishael, Malchijah, Hashum, Hashbaddanah, Zechariah, and Meshullam.","notes":[]},{"number":5,"text":"Ezra opened the book in the sight of all the people (for he was above all the people), and when he opened it, all the people stood up.","notes":[]},{"number":6,"text":"Then Ezra blessed the LORD, the great God. All the people answered, “Amen, Amen,” with the lifting up of their hands. They bowed their heads, and worshiped the LORD with their faces to the ground.","notes":[]},{"number":7,"text":"Also Jeshua, Bani, Sherebiah, Jamin, Akkub, Shabbethai, Hodiah, Maaseiah, Kelita, Azariah, Jozabad, Hanan, Pelaiah, and the Levites, caused the people to understand the law; and the people stayed in their place.","notes":[]},{"number":8,"text":"They read in the book, in the law of God, distinctly; and they gave the sense, so that they understood the reading.","notes":[]},{"number":9,"text":"Nehemiah, who was the governor, Ezra the priest and scribe, and the Levites who taught the people said to all the people, “Today is holy to the LORD your God. Don’t mourn, nor weep.” For all the people wept when they heard the words of the law.","notes":[]},{"number":10,"text":"Then he said to them, “Go your way. Eat the fat, drink the sweet, and send portions to him for whom nothing is prepared, for today is holy to our Lord. Don’t be grieved, for the joy of the LORD is your strength.”","notes":[]},{"number":11,"text":"So the Levites calmed all the people, saying, “Hold your peace, for the day is holy. Don’t be grieved.”","notes":[]},{"number":12,"text":"All the people went their way to eat, to drink, to send portions, and to celebrate, because they had understood the words that were declared to them.","notes":[]},{"number":13,"text":"On the second day, the heads of fathers’ households of all the people, the priests, and the Levites were gathered together to Ezra the scribe, to study the words of the law.","notes":[]},{"number":14,"text":"They found written in the law how the LORD had commanded by Moses that the children of Israel should dwell in booths in the feast of the seventh month;","notes":[]},{"number":15,"text":"and that they should publish and proclaim in all their cities and in Jerusalem, saying, “Go out to the mountain, and get olive branches, branches of wild olive, myrtle branches, palm branches, and branches of thick trees, to make temporary shelters, as it is written.”","notes":["or, booths"]},{"number":16,"text":"So the people went out and brought them, and made themselves temporary shelters, everyone on the roof of his house, in their courts, in the courts of God’s house, in the wide place of the water gate, and in the wide place of Ephraim’s gate.","notes":["or, booths"]},{"number":17,"text":"All the assembly of those who had come back out of the captivity made temporary shelters and lived in the temporary shelters, for since the days of Joshua the son of Nun to that day the children of Israel had not done so. There was very great gladness.","notes":["or, booths"]},{"number":18,"text":"Also day by day, from the first day to the last day, he read in the book of the law of God. They kept the feast seven days; and on the eighth day was a solemn assembly, according to the ordinance.","notes":[]}],"source":"https://ebible.org/engwebp/NEH08.htm"},"PHP-1":{"book":"Philippians","chapter":1,"verses":[{"number":1,"text":"Paul and Timothy, servants of Jesus Christ, to all the saints in Christ Jesus who are at Philippi, with the overseers and servants:","notes":["“Christ” means “Anointed One”.","or, superintendents, or bishops","Or, deacons"]},{"number":2,"text":"Grace to you and peace from God our Father and the Lord Jesus Christ.","notes":[]},{"number":3,"text":"I thank my God whenever I remember you,","notes":[]},{"number":4,"text":"always in every request of mine on behalf of you all, making my requests with joy,","notes":[]},{"number":5,"text":"for your partnership in furtherance of the Good News from the first day until now;","notes":["The word translated “partnership” (κοινωνίᾳ) also means “fellowship” and “sharing”."]},{"number":6,"text":"being confident of this very thing, that he who began a good work in you will complete it until the day of Jesus Christ.","notes":[]},{"number":7,"text":"It is even right for me to think this way on behalf of all of you, because I have you in my heart, because both in my bonds and in the defense and confirmation of the Good News, you all are partakers with me of grace.","notes":[]},{"number":8,"text":"For God is my witness, how I long after all of you in the tender mercies of Christ Jesus.","notes":[]},{"number":9,"text":"This I pray, that your love may abound yet more and more in knowledge and all discernment,","notes":[]},{"number":10,"text":"so that you may approve the things that are excellent, that you may be sincere and without offense to the day of Christ,","notes":[]},{"number":11,"text":"being filled with the fruits of righteousness which are through Jesus Christ, to the glory and praise of God.","notes":[]},{"number":12,"text":"Now I desire to have you know, brothers, that the things which happened to me have turned out rather to the progress of the Good News,","notes":["The word for “brothers” here and where context allows may also be correctly translated “brothers and sisters” or “siblings.”"]},{"number":13,"text":"so that it became evident to the whole palace guard, and to all the rest, that my bonds are in Christ,","notes":["or, praetorian"]},{"number":14,"text":"and that most of the brothers in the Lord, being confident through my bonds, are more abundantly bold to speak the word of God without fear.","notes":[]},{"number":15,"text":"Some indeed preach Christ even out of envy and strife, and some also out of good will.","notes":[]},{"number":16,"text":"The former insincerely preach Christ from selfish ambition, thinking that they add affliction to my chains;","notes":[]},{"number":17,"text":"but the latter out of love, knowing that I am appointed for the defense of the Good News.","notes":[]},{"number":18,"text":"What does it matter? Only that in every way, whether in pretense or in truth, Christ is proclaimed. I rejoice in this, yes, and will rejoice.","notes":[]},{"number":19,"text":"For I know that this will turn out to my salvation through your prayers and the supply of the Spirit of Jesus Christ,","notes":[]},{"number":20,"text":"according to my earnest expectation and hope, that I will in no way be disappointed, but with all boldness, as always, now also Christ will be magnified in my body, whether by life or by death.","notes":[]},{"number":21,"text":"For to me to live is Christ, and to die is gain.","notes":[]},{"number":22,"text":"But if I live on in the flesh, this will bring fruit from my work; yet I don’t know what I will choose.","notes":[]},{"number":23,"text":"But I am hard pressed between the two, having the desire to depart and be with Christ, which is far better.","notes":[]},{"number":24,"text":"Yet to remain in the flesh is more needful for your sake.","notes":[]},{"number":25,"text":"Having this confidence, I know that I will remain, yes, and remain with you all for your progress and joy in the faith,","notes":[]},{"number":26,"text":"that your boasting may abound in Christ Jesus in me through my presence with you again.","notes":["or, rejoicing"]},{"number":27,"text":"Only let your way of life be worthy of the Good News of Christ, that whether I come and see you or am absent, I may hear of your state, that you stand firm in one spirit, with one soul striving for the faith of the Good News;","notes":[]},{"number":28,"text":"and in nothing frightened by the adversaries, which is for them a proof of destruction, but to you of salvation, and that from God.","notes":[]},{"number":29,"text":"Because it has been granted to you on behalf of Christ, not only to believe in him, but also to suffer on his behalf,","notes":[]},{"number":30,"text":"having the same conflict which you saw in me and now hear is in me.","notes":[]}],"source":"https://ebible.org/engwebp/PHP01.htm"},"PHP-3":{"book":"Philippians","chapter":3,"verses":[{"number":1,"text":"Finally, my brothers, rejoice in the Lord! To write the same things to you, to me indeed is not tiresome, but for you it is safe.","notes":[]},{"number":2,"text":"Beware of the dogs; beware of the evil workers; beware of the false circumcision.","notes":[]},{"number":3,"text":"For we are the circumcision, who worship God in the Spirit, and rejoice in Christ Jesus, and have no confidence in the flesh;","notes":[]},{"number":4,"text":"though I myself might have confidence even in the flesh. If any other man thinks that he has confidence in the flesh, I yet more:","notes":[]},{"number":5,"text":"circumcised the eighth day, of the stock of Israel, of the tribe of Benjamin, a Hebrew of Hebrews; concerning the law, a Pharisee;","notes":[]},{"number":6,"text":"concerning zeal, persecuting the assembly; concerning the righteousness which is in the law, found blameless.","notes":[]},{"number":7,"text":"However, I consider those things that were gain to me as a loss for Christ.","notes":[]},{"number":8,"text":"Yes most certainly, and I count all things to be a loss for the excellency of the knowledge of Christ Jesus, my Lord, for whom I suffered the loss of all things, and count them nothing but refuse, that I may gain Christ","notes":[]},{"number":9,"text":"and be found in him, not having a righteousness of my own, that which is of the law, but that which is through faith in Christ, the righteousness which is from God by faith,","notes":[]},{"number":10,"text":"that I may know him and the power of his resurrection, and the fellowship of his sufferings, becoming conformed to his death,","notes":[]},{"number":11,"text":"if by any means I may attain to the resurrection from the dead.","notes":[]},{"number":12,"text":"Not that I have already obtained, or am already made perfect; but I press on, that I may take hold of that for which also I was taken hold of by Christ Jesus.","notes":[]},{"number":13,"text":"Brothers, I don’t regard myself as yet having taken hold, but one thing I do: forgetting the things which are behind and stretching forward to the things which are before,","notes":[]},{"number":14,"text":"I press on toward the goal for the prize of the high calling of God in Christ Jesus.","notes":[]},{"number":15,"text":"Let us therefore, as many as are perfect, think this way. If in anything you think otherwise, God will also reveal that to you.","notes":[]},{"number":16,"text":"Nevertheless, to the extent that we have already attained, let’s walk by the same rule. Let’s be of the same mind.","notes":[]},{"number":17,"text":"Brothers, be imitators together of me, and note those who walk this way, even as you have us for an example.","notes":[]},{"number":18,"text":"For many walk, of whom I told you often, and now tell you even weeping, as the enemies of the cross of Christ,","notes":[]},{"number":19,"text":"whose end is destruction, whose god is the belly, and whose glory is in their shame, who think about earthly things.","notes":[]},{"number":20,"text":"For our citizenship is in heaven, from where we also wait for a Savior, the Lord Jesus Christ,","notes":[]},{"number":21,"text":"who will change the body of our humiliation to be conformed to the body of his glory, according to the working by which he is able even to subject all things to himself.","notes":[]}],"source":"https://ebible.org/engwebp/PHP03.htm"},"PHP-4":{"book":"Philippians","chapter":4,"verses":[{"number":1,"text":"Therefore, my brothers, beloved and longed for, my joy and crown, stand firm in the Lord in this way, my beloved.","notes":[]},{"number":2,"text":"I exhort Euodia, and I exhort Syntyche, to think the same way in the Lord.","notes":[]},{"number":3,"text":"Yes, I beg you also, true partner, help these women, for they labored with me in the Good News with Clement also, and the rest of my fellow workers, whose names are in the book of life.","notes":[]},{"number":4,"text":"Rejoice in the Lord always! Again I will say, “Rejoice!”","notes":[]},{"number":5,"text":"Let your gentleness be known to all men. The Lord is at hand.","notes":[]},{"number":6,"text":"In nothing be anxious, but in everything, by prayer and petition with thanksgiving, let your requests be made known to God.","notes":[]},{"number":7,"text":"And the peace of God, which surpasses all understanding, will guard your hearts and your thoughts in Christ Jesus.","notes":[]},{"number":8,"text":"Finally, brothers, whatever things are true, whatever things are honorable, whatever things are just, whatever things are pure, whatever things are lovely, whatever things are of good report: if there is any virtue and if there is anything worthy of praise, think about these things.","notes":[]},{"number":9,"text":"Do the things which you learned, received, heard, and saw in me, and the God of peace will be with you.","notes":[]},{"number":10,"text":"But I rejoice in the Lord greatly that now at length you have revived your thought for me; in which you did indeed take thought, but you lacked opportunity.","notes":[]},{"number":11,"text":"Not that I speak because of lack, for I have learned in whatever state I am, to be content in it.","notes":[]},{"number":12,"text":"I know how to be humbled, and I also know how to abound. In any and all circumstances I have learned the secret both to be filled and to be hungry, both to abound and to be in need.","notes":[]},{"number":13,"text":"I can do all things through Christ who strengthens me.","notes":[]},{"number":14,"text":"However you did well that you shared in my affliction.","notes":[]},{"number":15,"text":"You yourselves also know, you Philippians, that in the beginning of the Good News, when I departed from Macedonia, no assembly shared with me in the matter of giving and receiving but you only.","notes":[]},{"number":16,"text":"For even in Thessalonica you sent once and again to my need.","notes":[]},{"number":17,"text":"Not that I seek for the gift, but I seek for the fruit that increases to your account.","notes":[]},{"number":18,"text":"But I have all things and abound. I am filled, having received from Epaphroditus the things that came from you, a sweet-smelling fragrance, an acceptable and well-pleasing sacrifice to God.","notes":[]},{"number":19,"text":"My God will supply every need of yours according to his riches in glory in Christ Jesus.","notes":[]},{"number":20,"text":"Now to our God and Father be the glory forever and ever! Amen.","notes":[]},{"number":21,"text":"Greet every saint in Christ Jesus. The brothers who are with me greet you.","notes":[]},{"number":22,"text":"All the saints greet you, especially those who are of Caesar’s household.","notes":[]},{"number":23,"text":"The grace of the Lord Jesus Christ be with you all. Amen.","notes":[]}],"source":"https://ebible.org/engwebp/PHP04.htm"},"PRO-15":{"book":"Proverbs","chapter":15,"verses":[{"number":1,"text":"A gentle answer turns away wrath, but a harsh word stirs up anger.","notes":[]},{"number":2,"text":"The tongue of the wise commends knowledge, but the mouths of fools gush out folly.","notes":[]},{"number":3,"text":"The LORD’s eyes are everywhere, keeping watch on the evil and the good.","notes":[]},{"number":4,"text":"A gentle tongue is a tree of life, but deceit in it crushes the spirit.","notes":[]},{"number":5,"text":"A fool despises his father’s correction, but he who heeds reproof shows prudence.","notes":[]},{"number":6,"text":"In the house of the righteous is much treasure, but the income of the wicked brings trouble.","notes":[]},{"number":7,"text":"The lips of the wise spread knowledge; not so with the heart of fools.","notes":[]},{"number":8,"text":"The sacrifice made by the wicked is an abomination to the LORD, but the prayer of the upright is his delight.","notes":[]},{"number":9,"text":"The way of the wicked is an abomination to the LORD, but he loves him who follows after righteousness.","notes":[]},{"number":10,"text":"There is stern discipline for one who forsakes the way. Whoever hates reproof shall die.","notes":[]},{"number":11,"text":"Sheol and Abaddon are before the LORD— how much more then the hearts of the children of men!","notes":["Sheol is the place of the dead."]},{"number":12,"text":"A scoffer doesn’t love to be reproved; he will not go to the wise.","notes":[]},{"number":13,"text":"A glad heart makes a cheerful face, but an aching heart breaks the spirit.","notes":[]},{"number":14,"text":"The heart of one who has understanding seeks knowledge, but the mouths of fools feed on folly.","notes":[]},{"number":15,"text":"All the days of the afflicted are wretched, but one who has a cheerful heart enjoys a continual feast.","notes":[]},{"number":16,"text":"Better is little, with the fear of the LORD, than great treasure with trouble.","notes":[]},{"number":17,"text":"Better is a dinner of herbs, where love is, than a fattened calf with hatred.","notes":[]},{"number":18,"text":"A wrathful man stirs up contention, but one who is slow to anger appeases strife.","notes":[]},{"number":19,"text":"The way of the sluggard is like a thorn patch, but the path of the upright is a highway.","notes":[]},{"number":20,"text":"A wise son makes a father glad, but a foolish man despises his mother.","notes":[]},{"number":21,"text":"Folly is joy to one who is void of wisdom, but a man of understanding keeps his way straight.","notes":[]},{"number":22,"text":"Where there is no counsel, plans fail; but in a multitude of counselors they are established.","notes":[]},{"number":23,"text":"Joy comes to a man with the reply of his mouth. How good is a word at the right time!","notes":[]},{"number":24,"text":"The path of life leads upward for the wise, to keep him from going downward to Sheol.","notes":["Sheol is the place of the dead."]},{"number":25,"text":"The LORD will uproot the house of the proud, but he will keep the widow’s borders intact.","notes":[]},{"number":26,"text":"The LORD detests the thoughts of the wicked, but the thoughts of the pure are pleasing.","notes":[]},{"number":27,"text":"He who is greedy for gain troubles his own house, but he who hates bribes will live.","notes":[]},{"number":28,"text":"The heart of the righteous weighs answers, but the mouth of the wicked gushes out evil.","notes":[]},{"number":29,"text":"The LORD is far from the wicked, but he hears the prayer of the righteous.","notes":[]},{"number":30,"text":"The light of the eyes rejoices the heart. Good news gives health to the bones.","notes":[]},{"number":31,"text":"The ear that listens to reproof lives, and will be at home among the wise.","notes":[]},{"number":32,"text":"He who refuses correction despises his own soul, but he who listens to reproof gets understanding.","notes":[]},{"number":33,"text":"The fear of the LORD teaches wisdom. Before honor is humility.","notes":[]}],"source":"https://ebible.org/engwebp/PRO15.htm"},"PRO-21":{"book":"Proverbs","chapter":21,"verses":[{"number":1,"text":"The king’s heart is in the LORD’s hand like the watercourses. He turns it wherever he desires.","notes":[]},{"number":2,"text":"Every way of a man is right in his own eyes, but the LORD weighs the hearts.","notes":[]},{"number":3,"text":"To do righteousness and justice is more acceptable to the LORD than sacrifice.","notes":[]},{"number":4,"text":"A high look and a proud heart, the lamp of the wicked, is sin.","notes":[]},{"number":5,"text":"The plans of the diligent surely lead to profit; and everyone who is hasty surely rushes to poverty.","notes":[]},{"number":6,"text":"Getting treasures by a lying tongue is a fleeting vapor for those who seek death.","notes":[]},{"number":7,"text":"The violence of the wicked will drive them away, because they refuse to do what is right.","notes":[]},{"number":8,"text":"The way of the guilty is devious, but the conduct of the innocent is upright.","notes":[]},{"number":9,"text":"It is better to dwell in the corner of the housetop than to share a house with a contentious woman.","notes":[]},{"number":10,"text":"The soul of the wicked desires evil; his neighbor finds no mercy in his eyes.","notes":[]},{"number":11,"text":"When the mocker is punished, the simple gains wisdom. When the wise is instructed, he receives knowledge.","notes":[]},{"number":12,"text":"The Righteous One considers the house of the wicked, and brings the wicked to ruin.","notes":[]},{"number":13,"text":"Whoever stops his ears at the cry of the poor, he will also cry out, but shall not be heard.","notes":[]},{"number":14,"text":"A gift in secret pacifies anger, and a bribe in the cloak, strong wrath.","notes":[]},{"number":15,"text":"It is joy to the righteous to do justice; but it is a destruction to the workers of iniquity.","notes":[]},{"number":16,"text":"The man who wanders out of the way of understanding shall rest in the assembly of the departed spirits.","notes":[]},{"number":17,"text":"He who loves pleasure will be a poor man. He who loves wine and oil won’t be rich.","notes":[]},{"number":18,"text":"The wicked is a ransom for the righteous, the treacherous for the upright.","notes":[]},{"number":19,"text":"It is better to dwell in a desert land, than with a contentious and fretful woman.","notes":[]},{"number":20,"text":"There is precious treasure and oil in the dwelling of the wise, but a foolish man swallows it up.","notes":[]},{"number":21,"text":"He who follows after righteousness and kindness finds life, righteousness, and honor.","notes":[]},{"number":22,"text":"A wise man scales the city of the mighty, and brings down the strength of its confidence.","notes":[]},{"number":23,"text":"Whoever guards his mouth and his tongue keeps his soul from troubles.","notes":[]},{"number":24,"text":"The proud and arrogant man—“Scoffer” is his name— he works in the arrogance of pride.","notes":[]},{"number":25,"text":"The desire of the sluggard kills him, for his hands refuse to labor.","notes":[]},{"number":26,"text":"There are those who covet greedily all day long; but the righteous give and don’t withhold.","notes":[]},{"number":27,"text":"The sacrifice of the wicked is an abomination— how much more, when he brings it with a wicked mind!","notes":[]},{"number":28,"text":"A false witness will perish. A man who listens speaks to eternity.","notes":[]},{"number":29,"text":"A wicked man hardens his face; but as for the upright, he establishes his ways.","notes":[]},{"number":30,"text":"There is no wisdom nor understanding nor counsel against the LORD.","notes":[]},{"number":31,"text":"The horse is prepared for the day of battle; but victory is with the LORD.","notes":[]}],"source":"https://ebible.org/engwebp/PRO21.htm"},"PRO-22":{"book":"Proverbs","chapter":22,"verses":[{"number":1,"text":"A good name is more desirable than great riches, and loving favor is better than silver and gold.","notes":[]},{"number":2,"text":"The rich and the poor have this in common: The LORD is the maker of them all.","notes":[]},{"number":3,"text":"A prudent man sees danger and hides himself; but the simple pass on, and suffer for it.","notes":[]},{"number":4,"text":"The result of humility and the fear of the LORD is wealth, honor, and life.","notes":[]},{"number":5,"text":"Thorns and snares are in the path of the wicked; whoever guards his soul stays far from them.","notes":[]},{"number":6,"text":"Train up a child in the way he should go, and when he is old he will not depart from it.","notes":[]},{"number":7,"text":"The rich rule over the poor. The borrower is servant to the lender.","notes":[]},{"number":8,"text":"He who sows wickedness reaps trouble, and the rod of his fury will be destroyed.","notes":[]},{"number":9,"text":"He who has a generous eye will be blessed, for he shares his food with the poor.","notes":[]},{"number":10,"text":"Drive out the mocker, and strife will go out; yes, quarrels and insults will stop.","notes":[]},{"number":11,"text":"He who loves purity of heart and speaks gracefully is the king’s friend.","notes":[]},{"number":12,"text":"The LORD’s eyes watch over knowledge, but he frustrates the words of the unfaithful.","notes":[]},{"number":13,"text":"The sluggard says, “There is a lion outside! I will be killed in the streets!”","notes":[]},{"number":14,"text":"The mouth of an adulteress is a deep pit. He who is under the LORD’s wrath will fall into it.","notes":[]},{"number":15,"text":"Folly is bound up in the heart of a child; the rod of discipline drives it far from him.","notes":[]},{"number":16,"text":"Whoever oppresses the poor for his own increase and whoever gives to the rich, both come to poverty.","notes":[]},{"number":17,"text":"Turn your ear, and listen to the words of the wise. Apply your heart to my teaching.","notes":[]},{"number":18,"text":"For it is a pleasant thing if you keep them within you, if all of them are ready on your lips.","notes":[]},{"number":19,"text":"I teach you today, even you, so that your trust may be in the LORD.","notes":[]},{"number":20,"text":"Haven’t I written to you thirty excellent things of counsel and knowledge,","notes":[]},{"number":21,"text":"To teach you truth, reliable words, to give sound answers to the ones who sent you?","notes":[]},{"number":22,"text":"Don’t exploit the poor because he is poor; and don’t crush the needy in court;","notes":[]},{"number":23,"text":"for the LORD will plead their case, and plunder the life of those who plunder them.","notes":[]},{"number":24,"text":"Don’t befriend a hot-tempered man. Don’t associate with one who harbors anger,","notes":[]},{"number":25,"text":"lest you learn his ways and ensnare your soul.","notes":[]},{"number":26,"text":"Don’t you be one of those who strike hands, of those who are collateral for debts.","notes":[]},{"number":27,"text":"If you don’t have means to pay, why should he take away your bed from under you?","notes":[]},{"number":28,"text":"Don’t move the ancient boundary stone which your fathers have set up.","notes":[]},{"number":29,"text":"Do you see a man skilled in his work? He will serve kings. He won’t serve obscure men.","notes":[]}],"source":"https://ebible.org/engwebp/PRO22.htm"},"PRO-24":{"book":"Proverbs","chapter":24,"verses":[{"number":1,"text":"Don’t be envious of evil men, neither desire to be with them;","notes":[]},{"number":2,"text":"for their hearts plot violence and their lips talk about mischief.","notes":[]},{"number":3,"text":"Through wisdom a house is built; by understanding it is established;","notes":[]},{"number":4,"text":"by knowledge the rooms are filled with all rare and beautiful treasure.","notes":[]},{"number":5,"text":"A wise man has great power. A knowledgeable man increases strength,","notes":[]},{"number":6,"text":"for by wise guidance you wage your war, and victory is in many advisors.","notes":[]},{"number":7,"text":"Wisdom is too high for a fool. He doesn’t open his mouth in the gate.","notes":[]},{"number":8,"text":"One who plots to do evil will be called a schemer.","notes":[]},{"number":9,"text":"The schemes of folly are sin. The mocker is detested by men.","notes":[]},{"number":10,"text":"If you falter in the time of trouble, your strength is small.","notes":[]},{"number":11,"text":"Rescue those who are being led away to death! Indeed, hold back those who are staggering to the slaughter!","notes":[]},{"number":12,"text":"If you say, “Behold, we didn’t know this,” doesn’t he who weighs the hearts consider it? He who keeps your soul, doesn’t he know it? Shall he not give to every man according to his work?","notes":[]},{"number":13,"text":"My son, eat honey, for it is good, the droppings of the honeycomb, which are sweet to your taste;","notes":[]},{"number":14,"text":"so you shall know wisdom to be to your soul. If you have found it, then there will be a reward: Your hope will not be cut off.","notes":[]},{"number":15,"text":"Don’t lay in wait, wicked man, against the habitation of the righteous. Don’t destroy his resting place;","notes":[]},{"number":16,"text":"for a righteous man falls seven times and rises up again, but the wicked are overthrown by calamity.","notes":[]},{"number":17,"text":"Don’t rejoice when your enemy falls. Don’t let your heart be glad when he is overthrown,","notes":[]},{"number":18,"text":"lest the LORD see it, and it displease him, and he turn away his wrath from him.","notes":[]},{"number":19,"text":"Don’t fret yourself because of evildoers, neither be envious of the wicked;","notes":[]},{"number":20,"text":"for there will be no reward to the evil man. The lamp of the wicked will be snuffed out.","notes":[]},{"number":21,"text":"My son, fear the LORD and the king. Don’t join those who are rebellious,","notes":[]},{"number":22,"text":"for their calamity will rise suddenly. Who knows what destruction may come from them both?","notes":[]},{"number":23,"text":"These also are sayings of the wise: To show partiality in judgment is not good.","notes":[]},{"number":24,"text":"He who says to the wicked, “You are righteous,” peoples will curse him, and nations will abhor him—","notes":[]},{"number":25,"text":"but it will go well with those who convict the guilty, and a rich blessing will come on them.","notes":[]},{"number":26,"text":"An honest answer is like a kiss on the lips.","notes":[]},{"number":27,"text":"Prepare your work outside, and get your fields ready. Afterwards, build your house.","notes":[]},{"number":28,"text":"Don’t be a witness against your neighbor without cause. Don’t deceive with your lips.","notes":[]},{"number":29,"text":"Don’t say, “I will do to him as he has done to me; I will repay the man according to his work.”","notes":[]},{"number":30,"text":"I went by the field of the sluggard, by the vineyard of the man void of understanding.","notes":[]},{"number":31,"text":"Behold, it was all grown over with thorns. Its surface was covered with nettles, and its stone wall was broken down.","notes":[]},{"number":32,"text":"Then I saw, and considered well. I saw, and received instruction:","notes":[]},{"number":33,"text":"a little sleep, a little slumber, a little folding of the hands to sleep,","notes":[]},{"number":34,"text":"so your poverty will come as a robber and your want as an armed man.","notes":[]}],"source":"https://ebible.org/engwebp/PRO24.htm"},"PSA-145":{"book":"Psalm","chapter":145,"verses":[{"number":1,"text":"I will exalt you, my God, the King. I will praise your name forever and ever.","notes":[]},{"number":2,"text":"Every day I will praise you. I will extol your name forever and ever.","notes":[]},{"number":3,"text":"Great is the LORD, and greatly to be praised! His greatness is unsearchable.","notes":[]},{"number":4,"text":"One generation will commend your works to another, and will declare your mighty acts.","notes":[]},{"number":5,"text":"I will meditate on the glorious majesty of your honor, on your wondrous works.","notes":[]},{"number":6,"text":"Men will speak of the might of your awesome acts. I will declare your greatness.","notes":[]},{"number":7,"text":"They will utter the memory of your great goodness, and will sing of your righteousness.","notes":[]},{"number":8,"text":"The LORD is gracious, merciful, slow to anger, and of great loving kindness.","notes":[]},{"number":9,"text":"The LORD is good to all. His tender mercies are over all his works.","notes":[]},{"number":10,"text":"All your works will give thanks to you, LORD. Your saints will extol you.","notes":[]},{"number":11,"text":"They will speak of the glory of your kingdom, and talk about your power,","notes":[]},{"number":12,"text":"to make known to the sons of men his mighty acts, the glory of the majesty of his kingdom.","notes":[]},{"number":13,"text":"Your kingdom is an everlasting kingdom. Your dominion endures throughout all generations. The LORD is faithful in all his words, and loving in all his deeds.","notes":["Some manuscripts omit these last two lines."]},{"number":14,"text":"The LORD upholds all who fall, and raises up all those who are bowed down.","notes":[]},{"number":15,"text":"The eyes of all wait for you. You give them their food in due season.","notes":[]},{"number":16,"text":"You open your hand, and satisfy the desire of every living thing.","notes":[]},{"number":17,"text":"The LORD is righteous in all his ways, and gracious in all his works.","notes":[]},{"number":18,"text":"The LORD is near to all those who call on him, to all who call on him in truth.","notes":[]},{"number":19,"text":"He will fulfill the desire of those who fear him. He also will hear their cry, and will save them.","notes":[]},{"number":20,"text":"The LORD preserves all those who love him, but he will destroy all the wicked.","notes":[]},{"number":21,"text":"My mouth will speak the praise of the LORD. Let all flesh bless his holy name forever and ever.","notes":[]}],"source":"https://ebible.org/engwebp/PSA145.htm"},"PSA-78":{"book":"Psalm","chapter":78,"verses":[{"number":1,"text":"Hear my teaching, my people. Turn your ears to the words of my mouth.","notes":[]},{"number":2,"text":"I will open my mouth in a parable. I will utter dark sayings of old,","notes":[]},{"number":3,"text":"which we have heard and known, and our fathers have told us.","notes":[]},{"number":4,"text":"We will not hide them from their children, telling to the generation to come the praises of the LORD, his strength, and his wondrous deeds that he has done.","notes":[]},{"number":5,"text":"For he established a covenant in Jacob, and appointed a teaching in Israel, which he commanded our fathers, that they should make them known to their children;","notes":[]},{"number":6,"text":"that the generation to come might know, even the children who should be born; who should arise and tell their children,","notes":[]},{"number":7,"text":"that they might set their hope in God, and not forget God’s deeds, but keep his commandments,","notes":[]},{"number":8,"text":"and might not be as their fathers— a stubborn and rebellious generation, a generation that didn’t make their hearts loyal, whose spirit was not steadfast with God.","notes":[]},{"number":9,"text":"The children of Ephraim, being armed and carrying bows, turned back in the day of battle.","notes":[]},{"number":10,"text":"They didn’t keep God’s covenant, and refused to walk in his law.","notes":[]},{"number":11,"text":"They forgot his doings, his wondrous deeds that he had shown them.","notes":[]},{"number":12,"text":"He did marvelous things in the sight of their fathers, in the land of Egypt, in the field of Zoan.","notes":[]},{"number":13,"text":"He split the sea, and caused them to pass through. He made the waters stand as a heap.","notes":[]},{"number":14,"text":"In the daytime he also led them with a cloud, and all night with a light of fire.","notes":[]},{"number":15,"text":"He split rocks in the wilderness, and gave them drink abundantly as out of the depths.","notes":[]},{"number":16,"text":"He brought streams also out of the rock, and caused waters to run down like rivers.","notes":[]},{"number":17,"text":"Yet they still went on to sin against him, to rebel against the Most High in the desert.","notes":[]},{"number":18,"text":"They tempted God in their heart by asking food according to their desire.","notes":[]},{"number":19,"text":"Yes, they spoke against God. They said, “Can God prepare a table in the wilderness?","notes":[]},{"number":20,"text":"Behold, he struck the rock, so that waters gushed out, and streams overflowed. Can he give bread also? Will he provide meat for his people?”","notes":[]},{"number":21,"text":"Therefore the LORD heard, and was angry. A fire was kindled against Jacob, anger also went up against Israel,","notes":[]},{"number":22,"text":"because they didn’t believe in God, and didn’t trust in his salvation.","notes":[]},{"number":23,"text":"Yet he commanded the skies above, and opened the doors of heaven.","notes":[]},{"number":24,"text":"He rained down manna on them to eat, and gave them food from the sky.","notes":[]},{"number":25,"text":"Man ate the bread of angels. He sent them food to the full.","notes":[]},{"number":26,"text":"He caused the east wind to blow in the sky. By his power he guided the south wind.","notes":[]},{"number":27,"text":"He also rained meat on them as the dust, winged birds as the sand of the seas.","notes":[]},{"number":28,"text":"He let them fall in the middle of their camp, around their habitations.","notes":[]},{"number":29,"text":"So they ate, and were well filled. He gave them their own desire.","notes":[]},{"number":30,"text":"They didn’t turn from their cravings. Their food was yet in their mouths,","notes":[]},{"number":31,"text":"when the anger of God went up against them, killed some of their strongest, and struck down the young men of Israel.","notes":[]},{"number":32,"text":"For all this they still sinned, and didn’t believe in his wondrous works.","notes":[]},{"number":33,"text":"Therefore he consumed their days in vanity, and their years in terror.","notes":[]},{"number":34,"text":"When he killed them, then they inquired after him. They returned and sought God earnestly.","notes":[]},{"number":35,"text":"They remembered that God was their rock, the Most High God, their redeemer.","notes":[]},{"number":36,"text":"But they flattered him with their mouth, and lied to him with their tongue.","notes":[]},{"number":37,"text":"For their heart was not right with him, neither were they faithful in his covenant.","notes":[]},{"number":38,"text":"But he, being merciful, forgave iniquity, and didn’t destroy them. Yes, many times he turned his anger away, and didn’t stir up all his wrath.","notes":[]},{"number":39,"text":"He remembered that they were but flesh, a wind that passes away, and doesn’t come again.","notes":[]},{"number":40,"text":"How often they rebelled against him in the wilderness, and grieved him in the desert!","notes":[]},{"number":41,"text":"They turned again and tempted God, and provoked the Holy One of Israel.","notes":[]},{"number":42,"text":"They didn’t remember his hand, nor the day when he redeemed them from the adversary;","notes":[]},{"number":43,"text":"how he set his signs in Egypt, his wonders in the field of Zoan,","notes":[]},{"number":44,"text":"he turned their rivers into blood, and their streams, so that they could not drink.","notes":[]},{"number":45,"text":"He sent among them swarms of flies, which devoured them; and frogs, which destroyed them.","notes":[]},{"number":46,"text":"He also gave their increase to the caterpillar, and their labor to the locust.","notes":[]},{"number":47,"text":"He destroyed their vines with hail, their sycamore fig trees with frost.","notes":[]},{"number":48,"text":"He also gave over their livestock to the hail, and their flocks to hot thunderbolts.","notes":[]},{"number":49,"text":"He threw on them the fierceness of his anger, wrath, indignation, and trouble, and a band of angels of evil.","notes":[]},{"number":50,"text":"He made a path for his anger. He didn’t spare their soul from death, but gave their life over to the pestilence,","notes":[]},{"number":51,"text":"and struck all the firstborn in Egypt, the chief of their strength in the tents of Ham.","notes":[]},{"number":52,"text":"But he led out his own people like sheep, and guided them in the wilderness like a flock.","notes":[]},{"number":53,"text":"He led them safely, so that they weren’t afraid, but the sea overwhelmed their enemies.","notes":[]},{"number":54,"text":"He brought them to the border of his sanctuary, to this mountain, which his right hand had taken.","notes":[]},{"number":55,"text":"He also drove out the nations before them, allotted them for an inheritance by line, and made the tribes of Israel to dwell in their tents.","notes":[]},{"number":56,"text":"Yet they tempted and rebelled against the Most High God, and didn’t keep his testimonies,","notes":[]},{"number":57,"text":"but turned back, and dealt treacherously like their fathers. They were twisted like a deceitful bow.","notes":[]},{"number":58,"text":"For they provoked him to anger with their high places, and moved him to jealousy with their engraved images.","notes":[]},{"number":59,"text":"When God heard this, he was angry, and greatly abhorred Israel,","notes":[]},{"number":60,"text":"so that he abandoned the tent of Shiloh, the tent which he placed among men,","notes":[]},{"number":61,"text":"and delivered his strength into captivity, his glory into the adversary’s hand.","notes":[]},{"number":62,"text":"He also gave his people over to the sword, and was angry with his inheritance.","notes":[]},{"number":63,"text":"Fire devoured their young men. Their virgins had no wedding song.","notes":[]},{"number":64,"text":"Their priests fell by the sword, and their widows couldn’t weep.","notes":[]},{"number":65,"text":"Then the Lord awakened as one out of sleep, like a mighty man who shouts by reason of wine.","notes":[]},{"number":66,"text":"He struck his adversaries backward. He put them to a perpetual reproach.","notes":[]},{"number":67,"text":"Moreover he rejected the tent of Joseph, and didn’t choose the tribe of Ephraim,","notes":[]},{"number":68,"text":"But chose the tribe of Judah, Mount Zion which he loved.","notes":[]},{"number":69,"text":"He built his sanctuary like the heights, like the earth which he has established forever.","notes":[]},{"number":70,"text":"He also chose David his servant, and took him from the sheepfolds;","notes":[]},{"number":71,"text":"from following the ewes that have their young, he brought him to be the shepherd of Jacob, his people, and Israel, his inheritance.","notes":[]},{"number":72,"text":"So he was their shepherd according to the integrity of his heart, and guided them by the skillfulness of his hands.","notes":[]}],"source":"https://ebible.org/engwebp/PSA078.htm"},"PSA-96":{"book":"Psalm","chapter":96,"verses":[{"number":1,"text":"Sing to the LORD a new song! Sing to the LORD, all the earth.","notes":[]},{"number":2,"text":"Sing to the LORD! Bless his name! Proclaim his salvation from day to day!","notes":[]},{"number":3,"text":"Declare his glory among the nations, his marvelous works among all the peoples.","notes":[]},{"number":4,"text":"For the LORD is great, and greatly to be praised! He is to be feared above all gods.","notes":[]},{"number":5,"text":"For all the gods of the peoples are idols, but the LORD made the heavens.","notes":[]},{"number":6,"text":"Honor and majesty are before him. Strength and beauty are in his sanctuary.","notes":[]},{"number":7,"text":"Ascribe to the LORD, you families of nations, ascribe to the LORD glory and strength.","notes":[]},{"number":8,"text":"Ascribe to the LORD the glory due to his name. Bring an offering, and come into his courts.","notes":[]},{"number":9,"text":"Worship the LORD in holy array. Tremble before him, all the earth.","notes":[]},{"number":10,"text":"Say among the nations, “The LORD reigns.” The world is also established. It can’t be moved. He will judge the peoples with equity.","notes":[]},{"number":11,"text":"Let the heavens be glad, and let the earth rejoice. Let the sea roar, and its fullness!","notes":[]},{"number":12,"text":"Let the field and all that is in it exult! Then all the trees of the woods shall sing for joy","notes":[]},{"number":13,"text":"before the LORD; for he comes, for he comes to judge the earth. He will judge the world with righteousness, the peoples with his truth.","notes":[]}],"source":"https://ebible.org/engwebp/PSA096.htm"},"REV-21":{"book":"Revelation","chapter":21,"verses":[{"number":1,"text":"I saw a new heaven and a new earth, for the first heaven and the first earth have passed away, and the sea is no more.","notes":[]},{"number":2,"text":"I saw the holy city, New Jerusalem, coming down out of heaven from God, prepared like a bride adorned for her husband.","notes":[]},{"number":3,"text":"I heard a loud voice out of heaven saying, “Behold, God’s dwelling is with people; and he will dwell with them, and they will be his people, and God himself will be with them as their God.","notes":[]},{"number":4,"text":"He will wipe away every tear from their eyes. Death will be no more; neither will there be mourning, nor crying, nor pain any more. The first things have passed away.”","notes":[]},{"number":5,"text":"He who sits on the throne said, “Behold, I am making all things new.” He said, “Write, for these words of God are faithful and true.”","notes":[]},{"number":6,"text":"He said to me, “I am the Alpha and the Omega, the Beginning and the End. I will give freely to him who is thirsty from the spring of the water of life.","notes":[]},{"number":7,"text":"He who overcomes, I will give him these things. I will be his God, and he will be my son.","notes":[]},{"number":8,"text":"But for the cowardly, unbelieving, sinners, abominable, murderers, sexually immoral, sorcerers, idolaters, and all liars, their part is in the lake that burns with fire and sulfur, which is the second death.”","notes":["TR and NU omit “sinners”","The word for “sorcerers” here also includes users of potions and drugs."]},{"number":9,"text":"One of the seven angels who had the seven bowls which were loaded with the seven last plagues came, and he spoke with me, saying, “Come here. I will show you the bride, the Lamb’s wife.”","notes":[]},{"number":10,"text":"He carried me away in the Spirit to a great and high mountain, and showed me the holy city, Jerusalem, coming down out of heaven from God,","notes":[]},{"number":11,"text":"having the glory of God. Her light was like a most precious stone, like a jasper stone, clear as crystal;","notes":[]},{"number":12,"text":"having a great and high wall with twelve gates, and at the gates twelve angels, and names written on them, which are the names of the twelve tribes of the children of Israel.","notes":[]},{"number":13,"text":"On the east were three gates, and on the north three gates, and on the south three gates, and on the west three gates.","notes":[]},{"number":14,"text":"The wall of the city had twelve foundations, and on them twelve names of the twelve Apostles of the Lamb.","notes":[]},{"number":15,"text":"He who spoke with me had for a measure a golden reed to measure the city, its gates, and its walls.","notes":[]},{"number":16,"text":"The city is square. Its length is as great as its width. He measured the city with the reed: twelve thousand twelve stadia. Its length, width, and height are equal.","notes":["12,012 stadia = 2,221 kilometers or 1,380 miles. TR reads 12,000 stadia instead of 12,012 stadia."]},{"number":17,"text":"Its wall is one hundred forty-four cubits, by the measure of a man, that is, of an angel.","notes":["144 cubits is about 65.8 meters or 216 feet"]},{"number":18,"text":"The construction of its wall was jasper. The city was pure gold, like pure glass.","notes":[]},{"number":19,"text":"The foundations of the city’s wall were adorned with all kinds of precious stones. The first foundation was jasper, the second sapphire, the third chalcedony, the fourth emerald,","notes":["or, lapis lazuli"]},{"number":20,"text":"the fifth sardonyx, the sixth sardius, the seventh chrysolite, the eighth beryl, the ninth topaz, the tenth chrysoprase, the eleventh jacinth, and the twelfth amethyst.","notes":[]},{"number":21,"text":"The twelve gates were twelve pearls. Each one of the gates was made of one pearl. The street of the city was pure gold, like transparent glass.","notes":[]},{"number":22,"text":"I saw no temple in it, for the Lord God the Almighty and the Lamb are its temple.","notes":[]},{"number":23,"text":"The city has no need for the sun or moon to shine, for the very glory of God illuminated it and its lamp is the Lamb.","notes":[]},{"number":24,"text":"The nations will walk in its light. The kings of the earth bring the glory and honor of the nations into it.","notes":[]},{"number":25,"text":"Its gates will in no way be shut by day (for there will be no night there),","notes":[]},{"number":26,"text":"and they shall bring the glory and the honor of the nations into it so that they may enter.","notes":[]},{"number":27,"text":"There will in no way enter into it anything profane, or one who causes an abomination or a lie, but only those who are written in the Lamb’s book of life.","notes":[]}],"source":"https://ebible.org/engwebp/REV21.htm"},"REV-5":{"book":"Revelation","chapter":5,"verses":[{"number":1,"text":"I saw, in the right hand of him who sat on the throne, a book written inside and outside, sealed shut with seven seals.","notes":[]},{"number":2,"text":"I saw a mighty angel proclaiming with a loud voice, “Who is worthy to open the book, and to break its seals?”","notes":[]},{"number":3,"text":"No one in heaven above, or on the earth, or under the earth, was able to open the book or to look in it.","notes":[]},{"number":4,"text":"Then I wept much, because no one was found worthy to open the book or to look in it.","notes":[]},{"number":5,"text":"One of the elders said to me, “Don’t weep. Behold, the Lion who is of the tribe of Judah, the Root of David, has overcome: he who opens the book and its seven seals.”","notes":[]},{"number":6,"text":"I saw in the middle of the throne and of the four living creatures, and in the middle of the elders, a Lamb standing, as though it had been slain, having seven horns and seven eyes, which are the seven Spirits of God, sent out into all the earth.","notes":[]},{"number":7,"text":"Then he came, and he took it out of the right hand of him who sat on the throne.","notes":[]},{"number":8,"text":"Now when he had taken the book, the four living creatures and the twenty-four elders fell down before the Lamb, each one having a harp, and golden bowls full of incense, which are the prayers of the saints.","notes":[]},{"number":9,"text":"They sang a new song, saying, “You are worthy to take the book and to open its seals, for you were killed, and bought us for God with your blood out of every tribe, language, people, and nation,","notes":[]},{"number":10,"text":"and made us kings and priests to our God; and we will reign on the earth.”","notes":[]},{"number":11,"text":"I looked, and I heard something like a voice of many angels around the throne, the living creatures, and the elders. The number of them was ten thousands of ten thousands, and thousands of thousands,","notes":[]},{"number":12,"text":"saying with a loud voice, “Worthy is the Lamb who has been killed to receive the power, wealth, wisdom, strength, honor, glory, and blessing!”","notes":[]},{"number":13,"text":"I heard every created thing which is in heaven, on the earth, under the earth, on the sea, and everything in them, saying, “To him who sits on the throne and to the Lamb be the blessing, the honor, the glory, and the dominion, forever and ever! Amen!”","notes":["TR omits “Amen!”"]},{"number":14,"text":"The four living creatures said, “Amen!” Then the elders fell down and worshiped.","notes":["TR adds “twenty-four”","TR adds “the one living forever and ever”"]}],"source":"https://ebible.org/engwebp/REV05.htm"},"REV-7":{"book":"Revelation","chapter":7,"verses":[{"number":1,"text":"After this, I saw four angels standing at the four corners of the earth, holding the four winds of the earth, so that no wind would blow on the earth, or on the sea, or on any tree.","notes":[]},{"number":2,"text":"I saw another angel ascend from the sunrise, having the seal of the living God. He cried with a loud voice to the four angels to whom it was given to harm the earth and the sea,","notes":[]},{"number":3,"text":"saying, “Don’t harm the earth, the sea, or the trees, until we have sealed the bondservants of our God on their foreheads!”","notes":[]},{"number":4,"text":"I heard the number of those who were sealed, one hundred forty-four thousand, sealed out of every tribe of the children of Israel:","notes":[]},{"number":5,"text":"of the tribe of Judah twelve thousand were sealed, of the tribe of Reuben twelve thousand, of the tribe of Gad twelve thousand,","notes":[]},{"number":6,"text":"of the tribe of Asher twelve thousand, of the tribe of Naphtali twelve thousand, of the tribe of Manasseh twelve thousand,","notes":[]},{"number":7,"text":"of the tribe of Simeon twelve thousand, of the tribe of Levi twelve thousand, of the tribe of Issachar twelve thousand,","notes":[]},{"number":8,"text":"of the tribe of Zebulun twelve thousand, of the tribe of Joseph twelve thousand, and of the tribe of Benjamin twelve thousand were sealed.","notes":[]},{"number":9,"text":"After these things I looked, and behold, a great multitude which no man could count, out of every nation and of all tribes, peoples, and languages, standing before the throne and before the Lamb, dressed in white robes, with palm branches in their hands.","notes":[]},{"number":10,"text":"They cried with a loud voice, saying, “Salvation be to our God, who sits on the throne, and to the Lamb!”","notes":[]},{"number":11,"text":"All the angels were standing around the throne, the elders, and the four living creatures; and they fell on their faces before his throne, and worshiped God,","notes":[]},{"number":12,"text":"saying, “Amen! Blessing, glory, wisdom, thanksgiving, honor, power, and might, be to our God forever and ever! Amen.”","notes":[]},{"number":13,"text":"One of the elders answered, saying to me, “These who are arrayed in the white robes, who are they, and where did they come from?”","notes":[]},{"number":14,"text":"I told him, “My lord, you know.” He said to me, “These are those who came out of the great suffering. They washed their robes and made them white in the Lamb’s blood.","notes":["or, oppression"]},{"number":15,"text":"Therefore they are before the throne of God, and they serve him day and night in his temple. He who sits on the throne will spread his tabernacle over them.","notes":[]},{"number":16,"text":"They will never be hungry or thirsty any more. The sun won’t beat on them, nor any heat;","notes":[]},{"number":17,"text":"for the Lamb who is in the middle of the throne shepherds them and leads them to springs of life-giving waters. And God will wipe away every tear from their eyes.”","notes":[]}],"source":"https://ebible.org/engwebp/REV07.htm"},"ROM-10":{"book":"Romans","chapter":10,"verses":[{"number":1,"text":"Brothers, my heart’s desire and my prayer to God is for Israel, that they may be saved.","notes":[]},{"number":2,"text":"For I testify about them that they have a zeal for God, but not according to knowledge.","notes":[]},{"number":3,"text":"For being ignorant of God’s righteousness, and seeking to establish their own righteousness, they didn’t subject themselves to the righteousness of God.","notes":[]},{"number":4,"text":"For Christ is the fulfillment of the law for righteousness to everyone who believes.","notes":["or, completion, or end"]},{"number":5,"text":"For Moses writes about the righteousness of the law, “The one who does them will live by them.”","notes":["Leviticus 18:5"]},{"number":6,"text":"But the righteousness which is of faith says this, “Don’t say in your heart, ‘Who will ascend into heaven?’ (that is, to bring Christ down);","notes":["Deuteronomy 30:12"]},{"number":7,"text":"or, ‘Who will descend into the abyss?’ (that is, to bring Christ up from the dead.)”","notes":["Deuteronomy 30:13"]},{"number":8,"text":"But what does it say? “The word is near you, in your mouth and in your heart;” that is, the word of faith which we preach:","notes":["Deuteronomy 30:14"]},{"number":9,"text":"that if you will confess with your mouth that Jesus is Lord and believe in your heart that God raised him from the dead, you will be saved.","notes":[]},{"number":10,"text":"For with the heart one believes resulting in righteousness; and with the mouth confession is made resulting in salvation.","notes":[]},{"number":11,"text":"For the Scripture says, “Whoever believes in him will not be disappointed.”","notes":["Isaiah 28:16"]},{"number":12,"text":"For there is no distinction between Jew and Greek; for the same Lord is Lord of all, and is rich to all who call on him.","notes":[]},{"number":13,"text":"For, “Whoever will call on the name of the Lord will be saved.”","notes":["Joel 2:32"]},{"number":14,"text":"How then will they call on him in whom they have not believed? How will they believe in him whom they have not heard? How will they hear without a preacher?","notes":[]},{"number":15,"text":"And how will they preach unless they are sent? As it is written: “How beautiful are the feet of those who preach the Good News of peace, who bring glad tidings of good things!”","notes":["Isaiah 52:7"]},{"number":16,"text":"But they didn’t all listen to the glad news. For Isaiah says, “Lord, who has believed our report?”","notes":["Isaiah 53:1"]},{"number":17,"text":"So faith comes by hearing, and hearing by the word of God.","notes":[]},{"number":18,"text":"But I say, didn’t they hear? Yes, most certainly, “Their sound went out into all the earth, their words to the ends of the world.”","notes":["Psalms 19:4"]},{"number":19,"text":"But I ask, didn’t Israel know? First Moses says, “I will provoke you to jealousy with that which is no nation. I will make you angry with a nation void of understanding.”","notes":["Deuteronomy 32:21"]},{"number":20,"text":"Isaiah is very bold and says, “I was found by those who didn’t seek me. I was revealed to those who didn’t ask for me.”","notes":["Isaiah 65:1"]},{"number":21,"text":"But about Israel he says, “All day long I stretched out my hands to a disobedient and contrary people.”","notes":["Isaiah 65:2"]}],"source":"https://ebible.org/engwebp/ROM10.htm"},"ROM-15":{"book":"Romans","chapter":15,"verses":[{"number":1,"text":"Now we who are strong ought to bear the weaknesses of the weak, and not to please ourselves.","notes":[]},{"number":2,"text":"Let each one of us please his neighbor for that which is good, to be building him up.","notes":[]},{"number":3,"text":"For even Christ didn’t please himself. But, as it is written, “The reproaches of those who reproached you fell on me.”","notes":["Psalms 69:9"]},{"number":4,"text":"For whatever things were written before were written for our learning, that through perseverance and through encouragement of the Scriptures we might have hope.","notes":[]},{"number":5,"text":"Now the God of perseverance and of encouragement grant you to be of the same mind with one another according to Christ Jesus,","notes":[]},{"number":6,"text":"that with one accord you may with one mouth glorify the God and Father of our Lord Jesus Christ.","notes":[]},{"number":7,"text":"Therefore accept one another, even as Christ also accepted you, to the glory of God.","notes":["TR reads “us” instead of “you”"]},{"number":8,"text":"Now I say that Christ has been made a servant of the circumcision for the truth of God, that he might confirm the promises given to the fathers,","notes":[]},{"number":9,"text":"and that the Gentiles might glorify God for his mercy. As it is written, “Therefore I will give praise to you among the Gentiles and sing to your name.”","notes":["2 Samuel 22:50; Psalms 18:49"]},{"number":10,"text":"Again he says, “Rejoice, you Gentiles, with his people.”","notes":["Deuteronomy 32:43"]},{"number":11,"text":"Again, “Praise the Lord, all you Gentiles! Let all the peoples praise him.”","notes":["Psalms 117:1"]},{"number":12,"text":"Again, Isaiah says, “There will be the root of Jesse, he who arises to rule over the Gentiles; in him the Gentiles will hope.”","notes":["Isaiah 11:10"]},{"number":13,"text":"Now may the God of hope fill you with all joy and peace in believing, that you may abound in hope in the power of the Holy Spirit.","notes":[]},{"number":14,"text":"I myself am also persuaded about you, my brothers, that you yourselves are full of goodness, filled with all knowledge, able also to admonish others.","notes":["The word for “brothers” here and where context allows may also be correctly translated “brothers and sisters” or “siblings.”"]},{"number":15,"text":"But I write the more boldly to you in part as reminding you, because of the grace that was given to me by God,","notes":[]},{"number":16,"text":"that I should be a servant of Christ Jesus to the Gentiles, serving as a priest of the Good News of God, that the offering up of the Gentiles might be made acceptable, sanctified by the Holy Spirit.","notes":[]},{"number":17,"text":"I have therefore my boasting in Christ Jesus in things pertaining to God.","notes":[]},{"number":18,"text":"For I will not dare to speak of any things except those which Christ worked through me for the obedience of the Gentiles, by word and deed,","notes":[]},{"number":19,"text":"in the power of signs and wonders, in the power of God’s Spirit; so that from Jerusalem and around as far as to Illyricum, I have fully preached the Good News of Christ;","notes":[]},{"number":20,"text":"yes, making it my aim to preach the Good News, not where Christ was already named, that I might not build on another’s foundation.","notes":[]},{"number":21,"text":"But, as it is written, “They will see, to whom no news of him came. They who haven’t heard will understand.”","notes":["Isaiah 52:15"]},{"number":22,"text":"Therefore also I was hindered these many times from coming to you,","notes":[]},{"number":23,"text":"but now, no longer having any place in these regions, and having these many years a longing to come to you,","notes":[]},{"number":24,"text":"whenever I travel to Spain, I will come to you. For I hope to see you on my journey, and to be helped on my way there by you, if first I may enjoy your company for a while.","notes":[]},{"number":25,"text":"But now, I say, I am going to Jerusalem, serving the saints.","notes":[]},{"number":26,"text":"For it has been the good pleasure of Macedonia and Achaia to make a certain contribution for the poor among the saints who are at Jerusalem.","notes":[]},{"number":27,"text":"Yes, it has been their good pleasure, and they are their debtors. For if the Gentiles have been made partakers of their spiritual things, they owe it to them also to serve them in material things.","notes":[]},{"number":28,"text":"When therefore I have accomplished this, and have sealed to them this fruit, I will go on by way of you to Spain.","notes":[]},{"number":29,"text":"I know that when I come to you, I will come in the fullness of the blessing of the Good News of Christ.","notes":[]},{"number":30,"text":"Now I beg you, brothers, by our Lord Jesus Christ and by the love of the Spirit, that you strive together with me in your prayers to God for me,","notes":[]},{"number":31,"text":"that I may be delivered from those who are disobedient in Judea, and that my service which I have for Jerusalem may be acceptable to the saints,","notes":[]},{"number":32,"text":"that I may come to you in joy through the will of God, and together with you, find rest.","notes":[]},{"number":33,"text":"Now the God of peace be with you all. Amen.","notes":[]}],"source":"https://ebible.org/engwebp/ROM15.htm"},"TIT-2":{"book":"Titus","chapter":2,"verses":[{"number":1,"text":"But say the things which fit sound doctrine,","notes":[]},{"number":2,"text":"that older men should be temperate, sensible, sober minded, sound in faith, in love, and in perseverance,","notes":[]},{"number":3,"text":"and that older women likewise be reverent in behavior, not slanderers nor enslaved to much wine, teachers of that which is good,","notes":[]},{"number":4,"text":"that they may train the young wives to love their husbands, to love their children,","notes":[]},{"number":5,"text":"to be sober minded, chaste, workers at home, kind, being in subjection to their own husbands, that God’s word may not be blasphemed.","notes":[]},{"number":6,"text":"Likewise, exhort the younger men to be sober minded.","notes":[]},{"number":7,"text":"In all things show yourself an example of good works. In your teaching, show integrity, seriousness, incorruptibility,","notes":[]},{"number":8,"text":"and soundness of speech that can’t be condemned, that he who opposes you may be ashamed, having no evil thing to say about us.","notes":[]},{"number":9,"text":"Exhort servants to be in subjection to their own masters and to be well-pleasing in all things, not contradicting,","notes":[]},{"number":10,"text":"not stealing, but showing all good fidelity, that they may adorn the doctrine of God, our Savior, in all things.","notes":[]},{"number":11,"text":"For the grace of God has appeared, bringing salvation to all men,","notes":[]},{"number":12,"text":"instructing us to the intent that, denying ungodliness and worldly lusts, we would live soberly, righteously, and godly in this present age;","notes":[]},{"number":13,"text":"looking for the blessed hope and appearing of the glory of our great God and Savior, Jesus Christ,","notes":[]},{"number":14,"text":"who gave himself for us, that he might redeem us from all iniquity and purify for himself a people for his own possession, zealous for good works.","notes":[]},{"number":15,"text":"Say these things and exhort and reprove with all authority. Let no one despise you.","notes":[]}],"source":"https://ebible.org/engwebp/TIT02.htm"},"ZEC-4":{"book":"Zechariah","chapter":4,"verses":[{"number":1,"text":"The angel who talked with me came again and wakened me, as a man who is wakened out of his sleep.","notes":[]},{"number":2,"text":"He said to me, “What do you see?” I said, “I have seen, and behold, a lamp stand all of gold, with its bowl on the top of it, and its seven lamps on it; there are seven pipes to each of the lamps which are on the top of it;","notes":[]},{"number":3,"text":"and two olive trees by it, one on the right side of the bowl, and the other on the left side of it.”","notes":[]},{"number":4,"text":"I answered and spoke to the angel who talked with me, saying, “What are these, my lord?”","notes":[]},{"number":5,"text":"Then the angel who talked with me answered me, “Don’t you know what these are?” I said, “No, my lord.”","notes":[]},{"number":6,"text":"Then he answered and spoke to me, saying, “This is the LORD’s word to Zerubbabel, saying, ‘Not by might, nor by power, but by my Spirit,’ says the LORD of Armies.","notes":[]},{"number":7,"text":"Who are you, great mountain? Before Zerubbabel you are a plain; and he will bring out the capstone with shouts of ‘Grace, grace, to it!’ ”","notes":[]},{"number":8,"text":"Moreover the LORD’s word came to me, saying,","notes":[]},{"number":9,"text":"“The hands of Zerubbabel have laid the foundation of this house. His hands shall also finish it; and you will know that the LORD of Armies has sent me to you.","notes":[]},{"number":10,"text":"Indeed, who despises the day of small things? For these seven shall rejoice, and shall see the plumb line in the hand of Zerubbabel. These are the LORD’s eyes, which run back and forth through the whole earth.”","notes":[]},{"number":11,"text":"Then I asked him, “What are these two olive trees on the right side of the lamp stand and on the left side of it?”","notes":[]},{"number":12,"text":"I asked him the second time, “What are these two olive branches, which are beside the two golden spouts that pour the golden oil out of themselves?”","notes":[]},{"number":13,"text":"He answered me, “Don’t you know what these are?” I said, “No, my lord.”","notes":[]},{"number":14,"text":"Then he said, “These are the two anointed ones who stand by the Lord of the whole earth.”","notes":["The word translated “Lord” is “Adonai.”"]}],"source":"https://ebible.org/engwebp/ZEC04.htm"}}}; if(typeof module!=="undefined"&&module.exports)module.exports=data; r.WTTNScripture=data;})(globalThis);
